INSERT INTO `trivia_questions` (`questionNumber`,`language`,`question`,`answerA`,`answerB`,`answerC`,`correctAnswer`,`explanation`,`image`,`category`) VALUES
(1,'de','Warum hat Emmentaler Löcher?','Sie werden beim Formen mit Nadeln gestochen','Bakterien produzieren Kohlendioxid im Käse','Beim Reifen verdunstet Flüssigkeit aus Hohlräumen','B','Verantwortlich sind Propionsäurebakterien. Sie bauen während der Reifung Milchsäure ab und setzen dabei Kohlendioxid frei. Das Gas kann aus dem festen Laib nicht entweichen und sammelt sich an winzigen Keimstellen – daraus werden die runden Löcher, im Fachjargon »Nester«.\n\nInteressant ist, was passiert, wenn man zu sauber arbeitet: Früher dienten kleine Heupartikel in der Milch als Keimstellen. Seit moderne Melkanlagen praktisch partikelfreie Milch liefern, werden die Löcher messbar kleiner. Manche Käsereien geben deshalb bewusst wieder Heustaub zu.','assets/quiz-illustrations/emmentaler.svg','Essen & Trinken'),
(2,'de','Warum sind Bananen krumm?','Die Frucht wächst gegen die Schwerkraft nach oben','Das Gewicht des Fruchtbündels biegt sie nach unten','Die Schale trocknet einseitig und zieht sich zusammen','A','Der Blütenstand der Bananenstaude hängt zunächst nach unten. Die jungen Früchte wachsen dann gegen die Schwerkraft dem Licht entgegen wieder nach oben – Botaniker nennen das negativen Gravitropismus. Weil sie unten ansetzen und oben enden, entsteht der Bogen.\n\nDie Krümmung ist damit kein Zuchtergebnis, sondern eine gewöhnliche Wachstumsreaktion. Wildbananen sind genauso krumm – nur stecken sie voller harter Kerne und sind kaum essbar.',NULL,'Natur'),
(3,'de','Warum brennt Chili im Mund, obwohl nichts heiß ist?','Der Scharfstoff ätzt die Schleimhaut leicht an','Er erhöht kurzzeitig die Temperatur im Mundraum','Er reizt genau die Nerven, die Hitze melden','C','Der Scharfstoff Capsaicin dockt an einen Rezeptor namens TRPV1 an. Der ist eigentlich ein Hitzemelder und feuert normalerweise ab etwa 43 Grad. Capsaicin öffnet ihn auf chemischem Weg – das Gehirn bekommt also eine echte Hitzemeldung, ohne dass irgendwo Wärme im Spiel ist.\n\nDeshalb hilft Wasser kaum: Capsaicin ist fettlöslich. Milch, Joghurt oder Sahne binden es dagegen wirksam. Und weil Vögel diesen Rezeptor anders gebaut haben, schmecken ihnen Chilis überhaupt nicht scharf – für die Pflanze praktisch, denn Vögel verbreiten die Samen unbeschadet.','assets/quiz-illustrations/chili.svg','Körper'),
(4,'de','Warum muss man beim Zwiebelschneiden weinen?','Der intensive Geruch löst einen Reflex im Gehirn aus','Zwiebelsaft reizt mechanisch die Hornhaut','Ein Gas bildet auf dem Auge eine Säure','C','Wird die Zwiebel verletzt, treffen zwei Stoffe zusammen, die vorher getrennt in der Zelle lagen. Ein Enzym baut daraus eine flüchtige Schwefelverbindung. Die steigt auf und reagiert auf der feuchten Augenoberfläche zu einer schwachen Säure. Das Auge spült mit Tränen nach.\n\nDas erklärt auch, warum die Hausmittel funktionieren: Eine gekühlte Zwiebel gibt weniger Gas ab, ein scharfes Messer zerstört weniger Zellen, und wer nah am Abzug arbeitet, bekommt weniger davon ans Auge.',NULL,'Essen & Trinken'),
(5,'de','Warum hat ein Golfball Dellen?','Sie verringern den Luftwiderstand deutlich','Sie machen den Ball im Gras besser sichtbar','Sie verbessern den Griff beim Abschlag','A','Ein glatter Ball reißt die Luftströmung früh ab und zieht ein breites Sog-Gebiet hinter sich her. Die Dellen erzeugen eine dünne, verwirbelte Schicht direkt an der Oberfläche, die der Kontur länger folgt. Das Sog-Gebiet wird kleiner, der Widerstand sinkt – und der Rückwärtsdrall erzeugt zusätzlich Auftrieb.\n\nDer Effekt ist gewaltig: Ein glatter Golfball fliegt nur etwa halb so weit. Entdeckt wurde er zufällig, weil Spieler im 19. Jahrhundert merkten, dass ihre alten, zerschrammten Bälle besser flogen als die neuen.','assets/quiz-illustrations/golfball.svg','Technik'),
(6,'de','Warum sind Tennisbälle gelb?','Wegen der Sichtbarkeit im Farbfernsehen','Gelb bleibt auf Sand am längsten sauber','Der Farbstoff macht den Filz widerstandsfähiger','A','Bis in die 1970er-Jahre waren Tennisbälle weiß. Mit dem Farbfernsehen wurde das zum Problem: Vor hellen Linien und weißer Kleidung war der Ball auf dem Bildschirm schlecht zu verfolgen. Untersuchungen zeigten, dass ein knalliges Grüngelb am besten zu erkennen war. Der Weltverband erlaubte es 1972.\n\nWimbledon blieb trotzdem noch bis 1986 beim weißen Ball – Tradition. Die offizielle Farbbezeichnung lautet übrigens »optic yellow«, und ob der Ball nun gelb oder grün ist, darüber streiten Zuschauer bis heute.',NULL,'Geschichte'),
(7,'de','Warum wird im Flugzeug bei Start und Landung das Kabinenlicht gedimmt?','Damit die Augen an Dunkelheit angepasst sind','Um Strom für die Triebwerke zu sparen','Damit die Piloten weniger Reflexionen im Cockpit haben','A','Start und Landung sind die kritischen Phasen. Müsste man bei Dunkelheit evakuieren, bräuchten Augen, die sich gerade noch an helles Kabinenlicht gewöhnt haben, mehrere Minuten, um draußen etwas zu erkennen. Bei gedimmtem Licht sind sie schon vorangepasst.\n\nAus dem gleichen Grund müssen die Fensterblenden offen bleiben: Die Crew soll von innen sehen können, ob auf einer Seite Feuer oder Trümmer liegen, bevor sie eine Tür öffnet. Und die Notbeleuchtung verläuft am Boden, weil sie dort auch bei Rauch sichtbar bleibt.',NULL,'Technik'),
(8,'de','Warum hat jedes Flugzeugfenster unten ein kleines Loch?','Damit die Scheibe innen nicht beschlägt','Es sorgt dafür, dass die äußere Scheibe den Druck trägt','Es dient als Ablauf für Kondenswasser','B','Ein Kabinenfenster besteht aus mehreren Acrylscheiben. Das winzige Loch in der mittleren Scheibe verbindet den Zwischenraum mit der Kabine. Dadurch liegt der gesamte Druckunterschied zur dünnen Außenluft auf der äußeren Scheibe, die genau dafür konstruiert ist. Die mittlere ist die Reserve, falls die äußere versagt.\n\nAls Nebeneffekt entweicht Feuchtigkeit aus dem Zwischenraum, so dass die Scheiben nicht von innen vereisen. Beides gleichzeitig zu erledigen ist gute Ingenieurskunst mit einem Bohrloch.','assets/quiz-illustrations/flugzeugfenster.svg','Technik'),
(9,'de','Warum ist das Meer salzig?','Flüsse tragen gelöstes Gestein hinein','Unterseeische Salzlager lösen sich langsam auf','Meeresorganismen geben stetig Salze ab','A','Regen ist leicht säuerlich und löst beim Abfließen Mineralien aus dem Gestein. Flüsse transportieren diese Salze ins Meer. Wasser verdunstet von dort wieder – die Salze bleiben. Über Jahrmillionen hat sich so ein Gehalt von rund 35 Gramm pro Liter eingestellt. Unterseeische Vulkanquellen liefern einen zweiten Beitrag.\n\nWarum wird es dann nicht immer salziger? Weil Salze auch wieder verschwinden: Sie werden in Sedimente eingebaut, in abgeschnittenen Meeresbecken abgelagert und mit den Erdplatten in die Tiefe gezogen. Zufuhr und Abfuhr halten sich ungefähr die Waage.',NULL,'Natur'),
(10,'de','Was knackt, wenn man mit den Fingerknöcheln knackt?','Eine Gasblase in der Gelenkflüssigkeit','Sehnen springen über einen Knochenvorsprung','Knorpelflächen reiben kurz aufeinander','A','Zieht man das Gelenk auseinander, wächst der Spalt schneller, als Flüssigkeit nachlaufen kann. Der Druck fällt, und gelöste Gase bilden schlagartig eine Blase. Dieses Entstehen der Blase erzeugt das Geräusch – MRT-Aufnahmen haben es inzwischen im Film festgehalten.\n\nDeshalb geht es nicht sofort noch einmal: Erst muss sich das Gas wieder lösen, das dauert etwa 20 Minuten. Und die verbreitete Warnung stimmt so nicht – Studien fanden bei Dauer-Knackern keine erhöhte Arthroserate, allenfalls etwas weniger Griffkraft.',NULL,'Körper'),
(11,'de','Wie viele Herzen hat ein Oktopus?','Drei','Zwei, eines je Körperhälfte','Eines, aber mit vier Kammern','A','Zwei Kiemenherzen pumpen das Blut jeweils durch eine Kieme, ein größeres Hauptherz schickt es anschließend durch den Körper. Das ist nötig, weil der Sauerstoffträger im Oktopusblut, das kupferhaltige Hämocyanin, deutlich ineffizienter arbeitet als unser eisenhaltiges Hämoglobin. Es macht das Blut übrigens bläulich.\n\nDas Hauptherz setzt beim Schwimmen aus – einer der Gründe, warum Oktopusse lieber über den Boden laufen als schwimmen. Schwimmen macht sie schlicht schneller müde.',NULL,'Tiere'),
(12,'de','Warum frieren Pinguine nicht an den Füßen fest?','Zu- und abfließendes Blut tauschen Wärme','Ihre Fußsohlen sind mit Fett isoliert','Sie halten die Füße dauerhaft leicht angehoben','A','In den Beinen liegen Arterien und Venen dicht beieinander und gegenläufig. Das warme Blut aus dem Körper gibt seine Wärme direkt an das kalte, zurücklaufende Blut ab. Unten ankommen tut es nur noch knapp über dem Gefrierpunkt – gerade warm genug, um nicht festzufrieren, und kalt genug, dass kaum Wärme verloren geht.\n\nDieses Gegenstromprinzip nutzen auch Enten auf dem Eis, Wale in ihren Flossen und Rentiere in den Beinen. Der Pinguin kann den Blutfluss zusätzlich regulieren – an warmen Tagen lässt er mehr Wärme über die Füße ab.','assets/quiz-illustrations/pinguin.svg','Tiere'),
(13,'de','Welche Farbe hat die Haut eines Eisbären?','Hellgrau mit weißen Flecken','Rosa wie bei anderen Bären','Schwarz','C','Unter dem Fell ist die Haut des Eisbären schwarz – gut zu sehen an Nase und Lippen. Dunkle Haut nimmt Wärme besser auf. Die Haare selbst sind nicht weiß, sondern farblos und lichtdurchlässig. Sie erscheinen weiß, weil das Licht in ihnen gestreut wird, ähnlich wie bei Schnee oder Zuckerwatte.\n\nDeshalb können Eisbären in Zoos grünlich werden: Setzen sich Algen in den hohlen Haaren fest, schimmert das Fell grün. Die verbreitete Idee, die Haare würden Sonnenlicht wie Lichtleiter zur Haut führen, gilt heute als widerlegt.',NULL,'Tiere'),
(14,'de','Warum ist der Himmel blau?','Er spiegelt die Farbe der Ozeane','Luftmoleküle streuen blaues Licht am stärksten','Wasserdampf filtert rotes Licht heraus','B','Sonnenlicht enthält alle Farben. An den Molekülen der Luft wird kurzwelliges Licht viel stärker in alle Richtungen gestreut als langwelliges – dieser Zusammenhang heißt Rayleigh-Streuung. Blau kommt daher aus dem ganzen Himmel, nicht nur direkt von der Sonne.\n\nViolett würde sogar noch stärker gestreut, aber die Sonne strahlt davon weniger ab und unsere Augen sind dafür unempfindlicher. Und abends? Dann läuft das Licht schräg durch viel mehr Luft, das Blau ist unterwegs herausgestreut – übrig bleiben Orange und Rot.','assets/quiz-illustrations/himmelblau.svg','Natur'),
(15,'de','Warum schwimmt Eis auf Wasser?','Wasser wird beim Erstarren leichter','Die Oberflächenspannung hält es oben','Eingeschlossene Luftbläschen tragen es','A','Fast alle Stoffe werden beim Erstarren dichter. Wasser nicht: Die Moleküle ordnen sich im Eis zu einem weitmaschigen Gitter mit Hohlräumen. Eis nimmt dadurch etwa neun Prozent mehr Platz ein als dieselbe Menge flüssiges Wasser – also schwimmt es. Am dichtesten ist Wasser bei rund vier Grad.\n\nDiese Dichteanomalie ist einer der Gründe, warum Leben in Seen den Winter übersteht: Die Eisdecke bildet sich oben und isoliert, unten bleibt es bei vier Grad flüssig. Würde Eis absinken, würden Seen von unten zufrieren.','assets/quiz-illustrations/eis.svg','Physik'),
(16,'de','Warum sind Kanaldeckel rund?','Weil Rohre rund sind und der Deckel dazu passt','Weil runde Deckel nicht in den Schacht fallen können','Weil sich runde Deckel besser gießen lassen','B','Ein Kreis hat in jeder Richtung denselben Durchmesser. Ein runder Deckel lässt sich deshalb nicht so drehen, dass er durch seine eigene Öffnung rutscht – bei einem quadratischen Deckel genügt es, ihn diagonal zu stellen. Für Arbeiter unter der Straße ist das ein handfestes Sicherheitsargument.\n\nDazu kommt Praktisches: Runde Deckel muss man beim Einsetzen nicht ausrichten, sie lassen sich rollen statt tragen, und die runde Form leitet das Gewicht darüberfahrender Lastwagen gleichmäßig in den Rand – Ecken wären Schwachstellen.','assets/quiz-illustrations/kanaldeckel.svg','Alltag'),
(17,'de','Woher stammt der Name der Funktechnik Bluetooth?','Von einem blauen Bauteil im ersten Prototyp','Von einem dänischen König','Von einem Codenamen für blaue Kabel bei Ericsson','B','Pate ist Harald Blauzahn, der im 10. Jahrhundert dänische Stammesgebiete vereinte und Norwegen anband. Ein Ingenieur schlug den Namen als Arbeitstitel vor: So wie der König Volksstämme vereinte, sollte die Technik verschiedene Geräte vereinen. Der Arbeitstitel blieb, weil sich das Marketing nicht auf etwas anderes einigen konnte.\n\nSogar das Logo passt: Es kombiniert die altnordischen Runen für H und B – die Initialen des Königs. Woher der Beiname Blauzahn kam, ist unklar; vielleicht von einem dunklen, abgestorbenen Zahn.',NULL,'Sprache'),
(18,'de','Warum haben Jeans an den Taschen kleine Metallnieten?','Sie sind ein Erkennungszeichen für echte Markenware','Sie verstärken die Stellen, an denen der Stoff reißt','Sie leiten statische Aufladung ab','B','Der Schneider Jacob Davis flickte Arbeitshosen für Goldsucher und ärgerte sich, dass immer die Taschenecken aufgingen. Er setzte kurzerhand Nieten aus der Pferdegeschirr-Werkstatt ein. Weil ihm das Geld für ein Patent fehlte, tat er sich 1873 mit seinem Stofflieferanten Levi Strauss zusammen – aus dieser Niete wurde die moderne Jeans.\n\nEine Niete verschwand später wieder: die am Schritt. Sie wurde am Lagerfeuer unangenehm heiß. Und die kleine fünfte Tasche vorn war einmal die Tasche für die Taschenuhr.',NULL,'Alltag'),
(19,'de','Warum sehen wir vom Mond immer dieselbe Seite?','Seine Drehung dauert genauso lang wie ein Umlauf','Er dreht sich gar nicht','Die Erde verdeckt die andere Seite mit ihrem Schatten','A','Der Mond rotiert durchaus – nur braucht er dafür genauso lange wie für eine Runde um die Erde, etwa 27 Tage. Deshalb zeigt er uns stets dasselbe Gesicht. Diese gebundene Rotation ist kein Zufall: Die Gezeitenkräfte der Erde haben seine Drehung über Jahrmillionen abgebremst, bis sie einrastete.\n\nGanz starr ist der Anblick nicht. Weil die Mondbahn leicht elliptisch und gekippt ist, schaukelt er ein wenig hin und her. Über die Zeit werden dadurch rund 59 Prozent seiner Oberfläche von der Erde aus sichtbar.','assets/quiz-illustrations/mond.svg','Weltall'),
(20,'de','Warum gibt es Jahreszeiten?','Weil die Erdachse geneigt ist','Weil der Abstand zur Sonne schwankt','Weil die Sonne unterschiedlich stark strahlt','A','Die Erdachse steht um gut 23 Grad schief. Dadurch trifft das Sonnenlicht die Nordhalbkugel im Juni steiler und länger, im Dezember flacher und kürzer – auf der Südhalbkugel genau umgekehrt. Steiler heißt: Dieselbe Energie verteilt sich auf weniger Fläche.\n\nDer Abstand kann es schon deshalb nicht sein, weil dann überall gleichzeitig Sommer wäre. Tatsächlich ist die Erde Anfang Januar der Sonne am nächsten – mitten im europäischen Winter.','assets/quiz-illustrations/jahreszeiten.svg','Weltall'),
(21,'de','Warum funkeln Sterne, Planeten aber kaum?','Planeten leuchten nicht selbst, sondern reflektieren nur','Sterne ändern ihre Helligkeit tatsächlich ständig','Planeten erscheinen als Scheibchen, Sterne als Punkt','C','Das Funkeln entsteht nicht am Stern, sondern in unserer Atmosphäre: Luftschichten unterschiedlicher Temperatur brechen das Licht verschieden und lenken es hin und her. Ein Stern ist selbst im Teleskop nur ein Lichtpunkt – wird der abgelenkt, sieht man es sofort.\n\nEin Planet dagegen steht so nah, dass er ein winziges Scheibchen bildet, also viele Punkte nebeneinander. Deren Schwankungen mitteln sich weg, das Licht bleibt ruhig. Ein praktischer Trick am Nachthimmel: Was ruhig steht, ist meist ein Planet.',NULL,'Physik'),
(22,'de','Warum wird Honig praktisch nie schlecht?','Bienen setzen ein natürliches Konservierungsmittel zu','Es ist zu wenig freies Wasser darin, als dass Keime wachsen','Der hohe Zuckergehalt tötet Keime chemisch ab','B','Reifer Honig enthält nur um 17 Prozent Wasser, und das ist durch den Zucker fest gebunden. Mikroorganismen brauchen freies Wasser – in Honig entzieht ihnen die Umgebung stattdessen Flüssigkeit. Dazu ist Honig säuerlich und enthält geringe Mengen Wasserstoffperoxid, das die Bienen über ein Enzym einbringen.\n\nIn ägyptischen Gräbern wurde Honig gefunden, der nach Jahrtausenden noch nicht verdorben war. Verdünnt man ihn aber, fällt der Schutz weg und er beginnt zu gären – genau das nutzt man beim Herstellen von Honigwein.',NULL,'Essen & Trinken'),
(23,'de','Warum sprudelt Cola so heftig, wenn man Mentos hineinwirft?','Die Bonbons reagieren chemisch mit der Säure','Ihre raue Oberfläche bietet unzählige Blasenkeime','Sie lösen sich schlagartig auf und verdrängen Flüssigkeit','B','Kohlensäurehaltige Getränke sind mit Gas übersättigt. Damit sich eine Blase bilden kann, braucht es einen Startpunkt. Die Mentos-Oberfläche ist unter dem Mikroskop voller Poren und Kanten – tausende Startpunkte auf einmal. Das Gas entweicht in Sekunden und schiebt die Flüssigkeit als Fontäne nach oben.\n\nEine chemische Reaktion ist es nicht. Zusatzstoffe in den Bonbons senken zusätzlich die Oberflächenspannung, was die Blasenbildung weiter erleichtert. Mit Light-Cola wird die Fontäne höher, weil sie ohne Zuckersirup dünnflüssiger ist.',NULL,'Essen & Trinken'),
(24,'de','Warum schrumpelt die Haut an den Fingern im Wasser?','Die Haut saugt sich mit Wasser voll und dehnt sich','Hautfett wird ausgewaschen und die Haut fällt ein','Das Nervensystem verengt aktiv die Blutgefäße','C','Man würde ein reines Aufquellen erwarten – tatsächlich ist es eine gesteuerte Reaktion. Das autonome Nervensystem verengt die Blutgefäße unter der Haut, das Volumen darunter nimmt ab, und die feste Hornschicht wirft Falten. Der Beweis: Ist der zuständige Nerv verletzt, schrumpeln die Finger nicht mehr.\n\nWarum der Körper das tut, ist nicht endgültig geklärt. Experimente deuten darauf hin, dass die Rillen nasse Gegenstände besser greifen lassen – ähnlich wie das Profil eines Reifens Wasser abführt.',NULL,'Körper'),
(25,'de','Warum bekommen Vögel auf einer Stromleitung keinen Schlag?','Ihre Krallen sind aus isolierendem Material','Federn leiten Strom nicht weiter','Zwischen ihren Füßen liegt kaum Spannung','C','Strom fließt nur, wenn es einen Spannungsunterschied gibt. Beide Füße des Vogels sitzen auf demselben Draht, wenige Zentimeter voneinander entfernt – dazwischen liegt fast keine Spannung, also fließt so gut wie kein Strom durch den Vogel. Der bequemere Weg bleibt das Kupfer.\n\nGefährlich wird es, sobald der Vogel zusätzlich etwas anderes berührt: einen zweiten Draht, einen Mast oder ein geerdetes Bauteil. Genau deshalb sind große Vogelarten mit weiter Spannweite an Hochspannungsmasten besonders bedroht.','assets/quiz-illustrations/vogel-leitung.svg','Tiere'),
(26,'de','Woher kommt die Redewendung »aus dem Stegreif«?','Vom Steigbügel des Reiters','Von einem Reif, den Handwerker als Maß nutzten','Von einem Steg, über den man ohne Umweg ging','A','»Stegreif« ist ein altes Wort für Steigbügel. Wer eine Sache aus dem Stegreif erledigte, tat es, ohne vom Pferd zu steigen – also sofort, ohne Vorbereitung, im Vorbeireiten. Weil das Wort außer in dieser Wendung ausgestorben ist, wird es heute oft falsch als »Stehgreif« geschrieben.\n\nEine verwandte Wendung aus derselben Welt: etwas aus dem Handgelenk schütteln. Und wer »hoch zu Ross« saß, tat das ganz wörtlich – mit dem entsprechenden Blick von oben.',NULL,'Sprache'),
(27,'de','Was bedeutete der Wunsch »Hals- und Beinbruch« ursprünglich?','Eine Warnung vor gefährlicher Arbeit','Einen Trinkspruch der Bergleute','Einen Segen aus dem Jiddischen','C','Dahinter steht sehr wahrscheinlich die jiddische Formel »hatslokhe un brokhe« – Glück und Segen. Deutsche Ohren hörten daraus lautlich »Hals und Bruch«, und weil das keinen Sinn ergab, machte der Volksmund einen vollständigen Unglückswunsch daraus.\n\nDas passte gut zu einem verbreiteten Aberglauben: Wer offen Glück wünscht, ruft das Gegenteil herbei – also wünscht man lieber Schlimmes. Im Englischen tut man genau dasselbe mit »break a leg«.',NULL,'Sprache'),
(28,'de','Warum steht auf Rettungswagen vorn die Aufschrift spiegelverkehrt?','Weil die Folie so einfacher von innen zu kleben ist','Damit sie im Rückspiegel richtig zu lesen ist','Es ist eine internationale Vorgabe für Blaulichtfahrzeuge','B','Die Schrift auf der Front ist für den Fahrer des vorausfahrenden Autos gedacht. Der sieht das Fahrzeug im Rückspiegel – und dort erscheint jede Schrift seitenverkehrt. Wird sie von Anfang an gespiegelt aufgebracht, liest er sie im Spiegel korrekt und kann schneller reagieren.\n\nDeshalb steht die Spiegelschrift auch immer nur vorn, nie an den Seiten oder hinten: Nur die Front landet überhaupt im Rückspiegel anderer.',NULL,'Alltag'),
(29,'de','Warum gefährdet ein Blitzeinschlag die Insassen eines Flugzeugs nicht?','Die Gummireifen isolieren das Flugzeug','Die Höhe schwächt den Blitz so stark ab','Die Metallhülle leitet den Strom außen herum','C','Die leitende Außenhaut wirkt als faradayscher Käfig: Der Strom läuft über die Oberfläche und verlässt das Flugzeug an einer Ableitspitze wieder, während der Innenraum praktisch feldfrei bleibt. Verkehrsflugzeuge werden statistisch etwa einmal im Jahr getroffen, meist merken die Passagiere nur Knall und Lichtblitz.\n\nAufwendig ist das bei modernen Rumpfteilen aus Kohlefaser, die schlechter leiten. Dort werden feine Metallgitter oder Kupferfolien einlaminiert, damit der Käfig weiter funktioniert. Zusätzlich sitzen kleine Entladungsspitzen an Flügel- und Leitwerkskanten.','assets/quiz-illustrations/blitz-flugzeug.svg','Physik'),
(30,'de','Warum sind Flamingos rosa?','Die Farbe stammt aus ihrer Nahrung','Das Federkleid enthält einen eigenen roten Farbstoff','Die Federstruktur bricht das Licht rosa','A','Flamingos filtern Kleinkrebse und Algen aus dem Wasser. Darin stecken Carotinoide – dieselbe Stoffgruppe, die Karotten orange macht. Der Vogel baut sie in Haut und Federn ein. Ohne diese Kost bleibt er blassweiß, was in Zoos früher regelmäßig zu sehen war, bevor das Futter angepasst wurde.\n\nDie Farbe ist auch ein Signal: Kräftiges Rosa zeigt, dass ein Tier gut frisst und gesund ist – entsprechend attraktiv wirkt es bei der Partnerwahl. Brütende Eltern verblassen dagegen, weil sie Farbstoffe an ihre Küken abgeben.',NULL,'Natur'),
(31,'de','Warum riecht der Urin nach dem Verzehr von Spargel?','Der Körper baut eine Spargelsäure zu Schwefelverbindungen ab','Der Spargel enthält selbst stark riechende Öle','Spargel entwässert und macht den Urin dadurch konzentrierter','A','Spargel enthält Asparagusinsäure, die es in dieser Form in kaum einem anderen Lebensmittel gibt. Die Verdauung zerlegt sie in kleine, leicht flüchtige Schwefelverbindungen. Weil sie so flüchtig sind, riecht man sie schon nach etwa einer Viertelstunde.\n\nDas Kuriose: Nicht jeder nimmt den Geruch wahr. Eine verbreitete Genvariante im Riechvermögen macht einen erheblichen Teil der Menschen dafür blind. Lange dachte man deshalb, nur manche Leute würden den Geruch überhaupt produzieren – tatsächlich tun es fast alle.',NULL,'Körper'),
(32,'de','Warum schmeckt Orangensaft direkt nach dem Zähneputzen scheußlich?','Die Zahnpasta reagiert mit der Fruchtsäure','Das Menthol betäubt die Zunge vollständig','Ein Schaumbildner blockiert die Süßwahrnehmung','C','Verantwortlich ist meist Natriumlaurylsulfat, der Stoff, der die Zahnpasta schäumen lässt. Er dämpft die Rezeptoren für Süß und greift gleichzeitig Fettmoleküle an, die sonst die Bitterwahrnehmung abmildern. Ergebnis: Die Süße des Saftes fehlt, die Säure und die Bitterstoffe bleiben – und schmecken plötzlich unerträglich.\n\nZahnpasta ohne diesen Schaumbildner löst den Effekt kaum aus. Wer nicht warten will, kann das Frühstück auch einfach vor dem Zähneputzen erledigen.',NULL,'Körper'),
(33,'de','Warum kommt Ketchup erst nicht und dann schwallweise aus der Flasche?','Luft muss erst in die Flasche nachströmen','Die enge Öffnung staut ihn zunächst auf','Er wird durch Schütteln dünnflüssiger','C','Ketchup gehört zu den nichtnewtonschen Flüssigkeiten. In Ruhe bilden die Tomatenpartikel ein lockeres Netz, das ihn fast wie einen Feststoff zusammenhält. Wirkt genug Kraft – Schütteln, Klopfen, Druck – bricht dieses Netz zusammen und die Zähigkeit sinkt binnen Sekunden dramatisch. Dann fließt alles auf einmal.\n\nDas Verhalten heißt Thixotropie und wird gezielt genutzt: Wandfarbe soll unter dem Pinsel dünn sein und an der Wand nicht tropfen, Zahnpasta soll in der Tube stehen und auf Druck herauskommen.','assets/quiz-illustrations/ketchup.svg','Physik'),
(34,'de','Warum rostet Edelstahl nicht, obwohl er vor allem aus Eisen besteht?','Er ist mit einer aufgetragenen Schutzschicht überzogen','Das Eisen wird durch Legieren chemisch unangreifbar','Enthaltenes Chrom bildet selbst eine hauchdünne Sperrschicht','C','Ab etwa zwölf Prozent Chrom passiert etwas Elegantes: Das Chrom reagiert an der Oberfläche sofort mit Sauerstoff zu einer nur wenige Atomlagen dünnen, dichten Oxidschicht. Die sitzt fest, ist unsichtbar und lässt keinen Sauerstoff mehr an das Eisen darunter. Rost braucht aber genau diesen Zugang.\n\nDas Beste daran ist die Selbstheilung: Kratzt man die Schicht auf, bildet sie sich in Sekunden neu. Nur wenn Sauerstoff dauerhaft fehlt – etwa unter einer festsitzenden Ablagerung – oder Chlorid sie lokal durchbricht, kann auch Edelstahl korrodieren.','assets/quiz-illustrations/edelstahl.svg','Technik'),
(35,'de','Warum sind die Buchstaben auf der Tastatur so unpraktisch angeordnet?','Die Anordnung folgt der Buchstabenhäufigkeit im Englischen','Sie stammt von der Anordnung im Telegrafenalphabet','Sie sollte das Verhaken der Schreibmaschinenhebel verhindern','C','In mechanischen Schreibmaschinen schlugen Typenhebel von unten gegen das Papier. Lagen zwei häufig aufeinanderfolgende Buchstaben nebeneinander, verhakten sich die Hebel bei schnellem Anschlag. Christopher Latham Sholes zog deshalb in den 1870er-Jahren häufige Buchstabenpaare räumlich auseinander. Das Ergebnis ist die QWERTY-Reihe, deutsch mit getauschtem Z und Y.\n\nMit Computern ist der Grund entfallen, geblieben ist die Anordnung trotzdem: Millionen Menschen hatten sie gelernt. Nachweislich schnellere Layouts wie Dvorak oder Neo haben sich nie durchgesetzt.','assets/quiz-illustrations/qwertz.svg','Technik'),
(36,'de','Warum fährt man in Großbritannien links?','Wegen der Lenkung der ersten dort gebauten Autos','Weil die Eisenbahn dort links fuhr und die Straßen folgten','Damit Reiter die Schwerthand zum Gegenverkehr hatten','C','Die gängige Erklärung reicht weit vor das Auto zurück. Wer beritten unterwegs war und ein Schwert trug, führte es rechts. Ritt man links, blieb die Waffenhand dem Gegenüber zugewandt – und man konnte die rechte Hand zum Grüßen oder zum Griff nutzen, ohne die Zügel zu wechseln. Papst Bonifatius VIII. soll Pilgern im Jahr 1300 links zu gehen empfohlen haben.\n\nDass ein großer Teil der Welt heute rechts fährt, hat viel mit Frankreich und den USA zu tun: Breite Fuhrwerke mit mehreren Zugpferden wurden vom linken hinteren Pferd aus gelenkt – der Kutscher wollte den Gegenverkehr links neben sich sehen und hielt sich deshalb rechts.',NULL,'Geschichte'),
(37,'de','Warum hat eine Woche sieben Tage?','Weil sich ein Mondmonat sauber in vier Teile teilen lässt','Wegen der sieben mit dem Auge sichtbaren Wandelsterne','Weil sieben in Babylon als göttliche Zahl gilt','B','Babylonische Astronomen kannten sieben Himmelskörper, die sich vor dem Sternenhintergrund bewegen: Sonne, Mond, Merkur, Venus, Mars, Jupiter und Saturn. Jedem wurde ein Tag zugeordnet. Über Griechen und Römer kam die Siebentagewoche nach Europa – anders als Monat und Jahr hat sie also keinen astronomischen Takt, dem sie folgen müsste.\n\nDie Namen verraten die Herkunft bis heute. Im Englischen sind Saturday, Sunday und Monday direkt Saturn, Sonne und Mond. Im Deutschen stecken germanische Götter darin, die die römischen ersetzten: Dienstag von Tiu, Donnerstag von Donar, Freitag von Frija.',NULL,'Geschichte'),
(38,'de','Warum heißt der Mittwoch nicht nach einem Gott wie die übrigen Wochentage?','Weil er in der Antike als Ruhetag ohne Gottheit galt','Weil die Kirche den Namen des Gottes Wodan verdrängte','Weil er erst im Mittelalter zur Woche hinzukam','B','Ursprünglich war es der Tag des Gottes Wodan – im Englischen heißt er noch heute Wednesday, im Niederländischen woensdag. Im deutschen Sprachraum setzte die Kirche im Frühmittelalter die nüchterne Zählform durch: der Tag in der Mitte der Woche.\n\nBeim Samstag hat sie es teilweise auch geschafft. Der Norden sagt Sonnabend, also Vorabend des Sonntags, der Süden Samstag – das kommt über Umwege vom hebräischen Sabbat. Nur beim Dienstag, Donnerstag und Freitag blieben die alten Götternamen stehen.',NULL,'Sprache'),
(39,'de','Warum haben Sektkorken die Form eines Pilzes?','Sie werden so gepresst, damit man sie besser greifen kann','Sie sind zylindrisch und werden erst in der Flasche verformt','Der Pilzkopf verteilt den Druck des Drahtkorbs','B','Vor dem Verkorken ist ein Sektkorken ein dicker Zylinder, deutlich breiter als der Flaschenhals. Beim Verschließen wird er stark zusammengedrückt. Der untere Teil bleibt im Hals gefangen und behält die zusammengedrückte Form, der obere Teil federt außerhalb wieder auf – daraus wird der Pilzkopf.\n\nAn der Form lässt sich sogar das Alter ablesen: Je länger die Flasche liegt, desto weniger elastisch ist der Kork und desto schmaler bleibt der herausgezogene Korken. Ein fast zylindrischer Korken deutet auf einen lange gelagerten Sekt.','assets/quiz-illustrations/sektkorken.svg','Essen & Trinken'),
(40,'de','Warum haben Weingläser einen langen Stiel?','Damit die Hand den Wein nicht erwärmt','Damit das Glas beim Schwenken stabiler steht','Damit sich die Aromen im Stiel sammeln','A','Am Stiel gehalten, bleibt die Handwärme vom Wein weg – bei einem gekühlten Weißwein macht das über ein längeres Essen mehrere Grad aus. Nebeneffekt: Der Kelch bleibt frei von Fingerabdrücken und beschlägt nicht, man sieht Farbe und Klarheit besser.\n\nDeshalb gehört zu einem Cognacschwenker gerade kein langer Stiel: Dort ist die Handwärme gewollt, sie treibt die Aromen aus. Und moderne stiellose Gläser sind ein bewusster Kompromiss – bequemer zu spülen, dafür wärmt die Hand mit.',NULL,'Essen & Trinken'),
(41,'de','Warum knurrt der Magen?','Magensäure brodelt bei leerem Magen','Gas und Flüssigkeit werden durch den Darm geschoben','Die Magenwand vibriert vor Anspannung','B','Magen und Darm arbeiten auch ohne Nahrung: Etwa alle eineinhalb bis zwei Stunden läuft eine kräftige Reinigungswelle durch den Verdauungstrakt und schiebt Reste weiter. Trifft sie auf ein Gemisch aus Flüssigkeit und Luft, entstehen die gurgelnden Geräusche, die Mediziner Borborygmus nennen.\n\nDass es bei leerem Magen so laut ist, hat einen einfachen Grund: Es fehlt der Inhalt, der den Schall dämpft. Voll knurrt es genauso, man hört es nur nicht.',NULL,'Körper'),
(42,'de','Was passiert im Körper beim Schluckauf?','Die Speiseröhre verkrampft sich ringförmig','Der Magen drückt kurzzeitig gegen die Lunge','Das Zwerchfell zuckt und die Stimmbänder schlagen zu','C','Ein Reflex lässt das Zwerchfell ruckartig zusammenziehen – man zieht unwillkürlich Luft ein. Nur einen Bruchteil einer Sekunde später schließt der Kehlkopf die Stimmbänder. Die einströmende Luft trifft auf den Verschluss, und genau das erzeugt den typischen Ton.\n\nWarum es diesen Reflex gibt, ist unklar; eine Vermutung führt ihn auf Kaulquappen zurück, die beim Kiemenatmen etwas Ähnliches tun. Die Hausmittel haben immerhin ein gemeinsames Prinzip: Luft anhalten, Wasser trinken oder Kaltes schlucken erhöhen den CO₂-Gehalt oder reizen den beteiligten Nerv – beides kann den Reflex unterbrechen.',NULL,'Körper'),
(43,'de','Warum bekommt man Kopfschmerzen, wenn man Eis zu schnell isst?','Das Gehirn kühlt kurzzeitig messbar ab','Gefäße am Gaumen reagieren und der Schmerz wird falsch verortet','Der Zucker lässt den Blutdruck kurz einbrechen','B','Kälte am Gaumen lässt Blutgefäße erst zusammenziehen und dann schnell weiten. Diese Reaktion registriert der Trigeminusnerv – derselbe Nerv, der auch große Bereiche des Gesichts und der Stirn versorgt. Das Gehirn kann die Meldung nicht genau zuordnen und verlegt den Schmerz nach vorn in die Stirn. Fachleute sprechen von übertragenem Schmerz.\n\nDas Gehirn selbst kühlt dabei nicht ab, es hat auch keine Schmerzrezeptoren. Der Spuk ist nach höchstens einer halben Minute vorbei; wer die Zunge an den Gaumen presst, wärmt die Stelle und verkürzt ihn.',NULL,'Körper'),
(44,'de','Warum hört man in einer großen Muschel ein Rauschen wie am Meer?','Man hört das eigene Blut in den Ohrgefäßen','Eingeschlossene Luft schwingt in einer festen Tonhöhe','Die Muschel verstärkt leise Umgebungsgeräusche','C','Der Hohlraum der Muschel ist ein Resonanzkörper. Er greift aus dem allgegenwärtigen leisen Geräuschteppich der Umgebung bestimmte Frequenzen heraus und verstärkt sie – heraus kommt ein breitbandiges Rauschen, das dem Meer ähnelt. Ein Becher oder eine hohle Hand am Ohr tun genau dasselbe.\n\nDie Blut-Erklärung lässt sich leicht widerlegen: In einem sehr stillen Raum wird das Rauschen deutlich schwächer, und beim Treppensteigen mit schnellem Puls wird es nicht lauter. Wäre es das eigene Blut, müsste es umgekehrt sein.',NULL,'Körper'),
(45,'de','Warum wird man seekrank?','Der Luftdruck an Deck verändert den Innendruck des Ohrs','Die Schwankungen bringen den Magen mechanisch aus dem Takt','Das Gleichgewichtsorgan meldet etwas anderes als die Augen','C','Unter Deck sieht das Auge eine ruhende Kabine, das Gleichgewichtsorgan im Innenohr spürt aber Schaukeln. Das Gehirn kann die widersprüchlichen Meldungen nicht zusammenbringen. Eine gängige Erklärung: Es deutet den Konflikt als Vergiftung – und die sinnvolle Reaktion auf eine Vergiftung ist Erbrechen.\n\nDaraus folgen die wirksamen Gegenmittel unmittelbar: an Deck gehen und den Horizont ansehen, damit Augen und Innenohr dasselbe melden. Aus dem gleichen Grund wird dem Fahrer selten schlecht, dem Beifahrer mit Buch dagegen schnell.',NULL,'Körper'),
(46,'de','Warum kann eine Eule den Kopf so weit drehen?','Weil sich ihre Augen nicht bewegen lassen','Ihr Schädel sitzt beweglich auf einem Kugelgelenk','Damit sie beim Fliegen nach hinten sehen kann','A','Eulenaugen sind für maximale Lichtstärke riesig und keine Kugeln, sondern Röhren – sie füllen die Augenhöhle vollständig aus und sind praktisch unbeweglich. Die Eule kann also nicht mit den Augen blicken, sie muss den ganzen Kopf drehen. Dafür hat sie 14 Halswirbel, doppelt so viele wie ein Mensch, und schafft rund 270 Grad.\n\nDie Blutversorgung ist an dieses Extrem angepasst: Die Arterien verlaufen in weiten Kanälen und haben Reservepolster, so dass sie beim starken Verdrehen nicht abgeklemmt werden. Ein Mensch würde bei derselben Bewegung die Durchblutung des Gehirns unterbrechen.','assets/quiz-illustrations/eule.svg','Tiere'),
(47,'de','Warum haben Ziegen rechteckige Pupillen?','Um bei praller Sonne weniger Licht einzulassen','Damit sie Farben besser unterscheiden können','Für ein sehr breites Blickfeld ohne Kopfdrehung','C','Der waagerechte Schlitz wirkt wie ein Panoramaformat: Er lässt Licht aus einem sehr weiten horizontalen Winkel herein und liefert am Boden ein scharfes Bild, während oben und unten wenig verloren geht. Zusammen mit den seitlich sitzenden Augen kommt die Ziege auf ein Blickfeld von annähernd 320 Grad – sie sieht grasend fast rundum, ohne den Kopf zu heben.\n\nDas Muster passt zur Lebensweise: Weidende Beutetiere wie Ziegen, Schafe und Pferde haben waagerechte Pupillen. Katzen als lauernde Jäger haben senkrechte Schlitze, die Entfernungen besser einschätzen lassen. Und beim Grasen bleibt der Schlitz waagerecht – das Auge dreht mit dem gesenkten Kopf gegen.','assets/quiz-illustrations/ziegenpupille.svg','Tiere'),
(48,'de','Wie erzeugt ein Glühwürmchen sein Licht?','Durch Reibung feiner Chitinplatten','Durch Bakterien, die im Hinterleib leben','Durch eine chemische Reaktion mit Sauerstoff','C','Im Hinterleib bringt ein Enzym den Stoff Luciferin mit Sauerstoff zusammen. Die Energie der Reaktion wird fast vollständig als Licht abgegeben, kaum als Wärme – deshalb der Name Kaltes Licht. Der Wirkungsgrad liegt bei rund 40 Prozent und schlägt jede Glühbirne um Längen.\n\nDas Blinken ist eine Partnerannonce, und jede Art hat ihren eigenen Takt. Bei den heimischen Leuchtkäfern sitzen meist die flugunfähigen Weibchen im Gras und leuchten, während die Männchen fliegend suchen. Manche amerikanischen Arten treiben es weiter: Ihre Weibchen imitieren den Takt fremder Arten und fressen die angelockten Männchen.',NULL,'Tiere'),
(49,'de','Warum kann eine Fliege an der Zimmerdecke laufen?','Winzige Härchen halten über eine Flüssigkeit','Sie erzeugt mit den Beinen einen leichten Unterdruck','Ihre Krallen greifen in Unebenheiten des Putzes','A','An den Fußspitzen sitzen zwei Haftpolster mit tausenden feinster Härchen. Jedes gibt eine winzige Menge einer öligen Flüssigkeit ab. Der dünne Flüssigkeitsfilm zieht das Härchen über Kapillarkräfte an die Oberfläche – jedes einzeln fast nichts, alle zusammen deutlich mehr als das Gewicht der Fliege.\n\nDas erklärt zwei Beobachtungen: Auf glattem Glas hält es besser als auf staubigen Flächen, weil Staub den Kontakt unterbricht. Und die Fliege muss aktiv abrollen, um sich zu lösen – festkleben und wieder loskommen sind zwei getrennte Kunststücke.','assets/quiz-illustrations/fliege.svg','Tiere'),
(50,'de','Welche Farbe hatten Karotten ursprünglich?','Orange, so wie heute','Violett und weiß','Grün wie ihr Kraut','B','Die Kulturmöhre stammt aus dem Raum Afghanistan und war violett, gelblich oder weiß. Orange Sorten entstanden erst in der frühen Neuzeit durch Auslese, maßgeblich in den Niederlanden. Sie enthielten viel Beta-Carotin, schmeckten milder und setzten sich in Europa durch – bis Orange als die natürliche Karottenfarbe galt.\n\nDie beliebte Erzählung, niederländische Gärtner hätten die Möhre dem Hause Oranien zu Ehren orange gezüchtet, ist hübsch, aber historisch nicht belegt. Violette Sorten sind übrigens zurück im Handel – als Neuheit.',NULL,'Natur'),
(51,'de','Warum wird eine angeschnittene Avocado braun?','Chlorophyll zerfällt unter Lichteinfluss','Die Fettsäuren im Fruchtfleisch werden ranzig','Ein Enzym reagiert mit Luftsauerstoff','C','Beim Schneiden werden Zellen zerstört und ein Enzym namens Polyphenoloxidase trifft auf Sauerstoff. Es baut pflanzliche Inhaltsstoffe zu braunen Pigmenten um – dieselbe Reaktion färbt aufgeschnittene Äpfel, Bananen und Kartoffeln. Verdorben ist die Frucht dadurch nicht.\n\nDas Enzym braucht Sauerstoff und mag Säure nicht. Deshalb funktionieren Zitronensaft und luftdichtes Abdecken, und deshalb hilft es, das Fruchtfleisch beim Guacamole direkt mit Limette zu mischen. Der Kern im Dip hält dagegen nur die Fläche frei, die er selbst bedeckt.',NULL,'Essen & Trinken'),
(52,'de','Warum wird Brot im Kühlschrank besonders schnell altbacken?','Es trocknet dort schneller aus als bei Zimmertemperatur','Die Stärke kristallisiert bei Kühlschranktemperatur am schnellsten','Kälte tötet die Hefen ab, die es weich halten','B','Altbackenwerden ist kein Austrocknen, sondern eine Umordnung: Die beim Backen aufgeschlossene Stärke bildet allmählich wieder feste, kristalline Bereiche und drängt Wasser aus. Der Fachbegriff ist Retrogradation. Genau dieser Vorgang läuft im Bereich weniger Grad über null am schnellsten – Kühlschranktemperatur ist der ungünstigste Punkt.\n\nDeshalb gilt: Brot bei Zimmertemperatur lagern oder gleich einfrieren, denn tief gefroren stoppt der Vorgang praktisch. Und weil er umkehrbar ist, wird altbackenes Brot im Ofen wieder weich – kurz aufbacken schmilzt die Kristalle auf.',NULL,'Essen & Trinken'),
(53,'de','Welcher Gipfel ist am weitesten vom Erdmittelpunkt entfernt?','Der Chimborazo in Ecuador','Der Mount Everest im Himalaya','Der Denali in Alaska','A','Die Erde ist keine Kugel, sondern durch ihre Rotation am Äquator ausgebeult – dort liegt der Meeresspiegel rund 21 Kilometer weiter außen als an den Polen. Der Chimborazo steht fast auf dem Äquator. Obwohl er mit gut 6260 Metern über dem Meer weit unter dem Everest bleibt, liegt sein Gipfel etwa zwei Kilometer weiter vom Erdmittelpunkt entfernt.\n\nHöchster Berg ist der Everest damit trotzdem, nur nach einem anderen Maßstab. Nimmt man den Fuß als Bezug, gewinnt ein Dritter: Der Mauna Kea auf Hawaii ragt vom Meeresboden gerechnet über 10.000 Meter auf – knapp die Hälfte davon liegt unter Wasser.','assets/quiz-illustrations/chimborazo.svg','Weltall'),
(54,'de','Warum hört man den Donner erst nach dem Blitz?','Der Donner entsteht erst kurz nach der Entladung','Schall ist rund eine Million Mal langsamer als Licht','Der Schall wird von Wolken zunächst zurückgehalten','B','Blitz und Donner entstehen gleichzeitig: Der Blitzkanal heizt die Luft binnen Mikrosekunden auf viele tausend Grad, sie dehnt sich explosionsartig aus, und diese Druckwelle ist der Donner. Das Licht braucht für die Strecke praktisch keine Zeit, der Schall etwa drei Sekunden pro Kilometer.\n\nDaraus wird die bekannte Faustregel: Sekunden zählen, durch drei teilen, Entfernung in Kilometern. Das lange Grollen kommt daher, dass der Blitzkanal kilometerlang ist – seine Abschnitte sind unterschiedlich weit entfernt, also trifft der Schall nach und nach ein.','assets/quiz-illustrations/blitz-donner.svg','Physik'),
(55,'de','Warum sind Wolken weiß, Regenwolken aber grau?','Dicke Wolken lassen kaum Licht nach unten durch','Regenwolken enthalten Staub, der sie dunkel färbt','Wassertropfen werden beim Wachsen dunkler','A','Wolkentröpfchen streuen alle Farben gleich stark, deshalb erscheint eine Wolke weiß. Wächst sie in die Höhe, muss das Licht immer mehr Tröpfchen passieren, wird bei jeder Streuung ein Stück abgelenkt und kommt unten kaum noch an. Von unten betrachtet wirkt die Wolke deshalb grau bis fast schwarz – nicht wegen ihrer Farbe, sondern wegen ihrer Dicke.\n\nVon oben, etwa aus dem Flugzeug, ist dieselbe Gewitterwolke strahlend weiß. Und weil große Regentropfen weniger Fläche pro Wassermenge bieten als viele kleine Tröpfchen, streut eine Wolke kurz vor dem Regen zusätzlich schwächer.',NULL,'Natur'),
(56,'de','Warum ist Rot international die Farbe für »Halt«?','Weil sie an Blut und damit an Gefahr erinnert','Weil frühe Signallampen nur rotes Glas hatten','Weil sie am weitesten sichtbar bleibt und selten natürlich vorkommt','C','Rotes Licht wird von Dunst und Regen weniger gestreut als blaues und ist deshalb über große Entfernungen gut zu sehen – dasselbe Prinzip, das Sonnenuntergänge rot macht. Dazu kommt, dass Rot in der Landschaft selten ist und damit auffällt. Die Eisenbahn setzte es im 19. Jahrhundert als Haltsignal durch, von dort übernahm es der Straßenverkehr.\n\nEine Farbe fiel dabei durch: Ursprünglich stand Weiß für »freie Fahrt«. Nachdem in einem Fall das rote Glas herausgefiel und der Lokführer die nackte weiße Lampe als Freigabe las, wurde daraus Grün.',NULL,'Alltag'),
(57,'de','Warum sind Verkehrsflugzeuge meist weiß?','Weiße Lackierungen sind besonders langlebig','Weiß bleibt im Flug am kühlsten und zeigt Schäden','Weiß ist im Radar am besten zu erfassen','B','Weiß reflektiert Sonnenlicht und hält den Rumpf am Boden deutlich kühler, was Klimaanlage und Material entlastet. Auf hellem Grund sind außerdem Risse, Ölspuren und Treibstofflecks bei der Kontrolle sofort zu sehen. Weiß verblasst zudem kaum, während kräftige Farben in Höhenstrahlung schnell ausbleichen und häufiger nachlackiert werden müssen.\n\nDazu kommt ein handfestes Argument: Vollflächige Lackierung wiegt bei einem Großflugzeug mehrere hundert Kilogramm und kostet über die Jahre Treibstoff. Einige Airlines lassen deshalb Teile bewusst blank oder lackieren so dünn wie möglich.',NULL,'Technik'),
(58,'de','Warum haben Einkaufswagen ein Schloss für eine Münze?','Um die Ausgabe der Wagen zählen zu können','Damit die Wagen zurückgebracht werden','Um Diebstahl der Wagen unmöglich zu machen','B','Die Münze ist ein Pfand, das nur der zurückbekommt, der den Wagen wieder einhängt. Betriebswirtschaftlich lohnt sich das nicht wegen des Geldes, sondern wegen der eingesparten Arbeitszeit: Ohne Pfand muss Personal die Wagen dauernd vom Parkplatz einsammeln, und dabei entstehen die meisten Blechschäden an Kundenautos.\n\nDer Betrag ist bewusst klein gewählt. Er muss nur groß genug sein, damit sich das Zurückschieben lohnt – nicht so groß, dass er Kunden abschreckt, die keine passende Münze dabei haben.',NULL,'Alltag'),
(59,'de','Woher kommt die Wendung »Schwein gehabt«?','Vom Sparschwein als Zeichen von Wohlstand','Vom Schwein als Trostpreis bei Wettkämpfen','Von einem Schweineglücksbringer der Seefahrer','B','Bei mittelalterlichen Schützen- und Sportwettbewerben erhielt der Letzte ein Schwein als Trostpreis. Wer als Verlierer immerhin ein wertvolles Tier heimtrug, hatte trotz der Niederlage Glück gehabt – daraus wurde die Wendung. Ein Schwein war Vermögen: Es lieferte Fleisch, Fett und Nachwuchs.\n\nAus derselben Wurzel stammt das Glücksschwein zum Neujahr. Das Sparschwein hingegen hat wahrscheinlich einen ganz anderen Ursprung: eine Tonart namens »pygg«, aus der man Sparbehälter formte – und die englische Lautähnlichkeit zu »pig« tat den Rest.',NULL,'Sprache'),
(60,'de','Warum beginnt der Tag in der Zeitrechnung um Mitternacht?','Weil die Römer den Amtstag um Mitternacht wechselten','Weil der Sonnenaufgang je nach Jahreszeit wandert','Weil die Kirche den Tag mit der Nachtmesse beginnen ließ','B','Als Beginn eines Tages sind mehrere Punkte denkbar, und historisch waren sie alle in Gebrauch: Für Ägypter und später die Römer begann der bürgerliche Tag um Mitternacht, jüdische und islamische Kalender lassen ihn mit Sonnenuntergang beginnen. Praktisch durchgesetzt hat sich Mitternacht aus einem einfachen Grund: Sonnenauf- und -untergang wandern über das Jahr und mit dem Breitengrad, Mitternacht als Gegenpunkt zum Sonnenhöchststand ist dagegen astronomisch fest definierbar.\n\nAstronomen hielten sich lange nicht daran: Bis 1925 begann ihr Tag mittags, damit eine Beobachtungsnacht nicht mitten im Datum zerfiel. Wer alte Sternkataloge liest, muss diesen Unterschied mitrechnen.',NULL,'Geschichte'),
(61,'de','Wie erzeugt eine Katze das Schnurren?','Durch Luft, die an den Zähnen vorbeistreicht','Durch Vibration der Kehlkopfmuskeln','Durch ein Flattern des Zwerchfells','B','Ein Signal aus dem Gehirn lässt die Muskeln am Kehlkopf etwa 25 bis 30 Mal pro Sekunde zusammenziehen. Die Stimmbänder öffnen und schließen sich dabei im Takt, und weil das beim Ein- und Ausatmen funktioniert, kann eine Katze minutenlang ohne Unterbrechung schnurren – anders als beim Miauen.\n\nSchnurren heißt nicht automatisch Wohlbefinden. Katzen schnurren auch bei Schmerzen, beim Tierarzt und im Sterben. Eine Vermutung: Die Frequenz liegt im Bereich, der in Versuchen die Knochenheilung anregt – Schnurren wäre dann auch Selbstberuhigung und vielleicht mehr.',NULL,'Tiere'),
(62,'de','Was steckt im Höcker eines Kamels?','Ein Wasserspeicher','Ein Geflecht aus Blutgefäßen','Fett','C','Der Höcker ist ein Fettdepot von bis zu 35 Kilogramm. Fett ist der beste Energiespeicher, den ein Körper bauen kann, und beim Verbrennen entsteht sogar etwas Wasser – der eigentliche Gewinn ist aber die Energie. Bei langem Hunger schrumpft der Höcker und kippt schlaff zur Seite.\n\nDie Wasserleistung des Kamels liegt woanders: Es lässt seine Körpertemperatur tagsüber um mehrere Grad steigen, statt zu schwitzen, und seine roten Blutkörperchen sind oval und dehnbar, so dass sie das schlagartige Trinken von über 100 Litern überstehen, ohne zu platzen.','assets/quiz-illustrations/kamel.svg','Tiere'),
(63,'de','Wozu dienen die großen Ohren eines afrikanischen Elefanten vor allem?','Zum besonders feinen Hören','Zum Abgeben von Körperwärme','Zum Abwehren von Insekten','B','Die Ohren sind von einem dichten Netz oberflächlicher Blutgefäße durchzogen und bieten mehrere Quadratmeter Fläche. Durch Fächeln streicht Luft daran vorbei und kühlt das Blut, bevor es zurück in den Körper fließt – bei günstigen Bedingungen um mehrere Grad. Für ein Tier dieser Masse ist Wärme loszuwerden das größere Problem als Wärme zu halten.\n\nDaran lassen sich die Arten unterscheiden: Der Afrikanische Elefant lebt in heißerer, offener Landschaft und hat deutlich größere Ohren als der Asiatische. Hören kann er ohnehin gut, allerdings vor allem sehr tiefe Töne, die er kilometerweit wahrnimmt.','assets/quiz-illustrations/elefantenohr.svg','Tiere'),
(64,'de','Wie viele Halswirbel hat eine Giraffe?','Sieben, genauso viele wie ein Mensch','Vierzehn','Über zwanzig, ähnlich wie ein Schwan','A','Fast alle Säugetiere haben sieben Halswirbel – die Maus, der Mensch, der Wal und eben auch die Giraffe. Bei ihr ist jeder einzelne Wirbel bis zu 25 Zentimeter lang. Die Zahl ist in der Entwicklung so streng festgelegt, dass Abweichungen beim Menschen meist mit Fehlbildungen einhergehen.\n\nAusnahmen gibt es: Faultiere kommen je nach Art auf sechs bis neun, Seekühe auf sechs. Vögel sind gar nicht gebunden, ein Schwan hat über zwanzig – deshalb ist sein Hals so beweglich, während die Giraffe ihren eher wie einen Kran bewegt.',NULL,'Tiere'),
(65,'de','Warum umkreisen Nachtfalter eine Lampe?','Sie halten die Lampe für den Mond und verrechnen sich','Sie werden von der Wärme der Lampe angezogen','Sie drehen instinktiv den Rücken zum hellsten Licht','C','Lange galt die Mond-Erklärung. Hochgeschwindigkeitsaufnahmen fliegender Insekten haben aber etwas anderes gezeigt: Sie halten reflexhaft ihren Rücken zur hellsten Lichtquelle. Am Himmel ist das der richtige Weg, oben zu bleiben. Neben einer Lampe kippt dieser Reflex die Flugbahn – das Tier gerät in eine enge Kurve um die Lampe, statt sie anzusteuern.\n\nDas erklärt Beobachtungen, die zur Mond-Theorie nie passten: Falter fliegen nicht direkt in die Lampe, sondern kreisen, taumeln und bleiben manchmal darunter regelrecht hängen. Für nachtaktive Insekten ist künstliches Licht damit weniger Anziehung als Orientierungsfalle.',NULL,'Tiere'),
(66,'de','Warum leuchten Katzenaugen im Scheinwerferlicht?','Hinter der Netzhaut sitzt eine spiegelnde Schicht','Die Netzhaut selbst gibt Licht ab','Die Hornhaut wirft das Licht wie eine Linse zurück','A','Hinter der Netzhaut liegt das Tapetum lucidum, eine Schicht aus feinen Kristallen, die Licht nach vorn zurückwirft. Was die Sehzellen beim ersten Durchgang verpasst haben, bekommen sie beim zweiten – das verbessert das Sehen in der Dämmerung erheblich. Der Rest verlässt das Auge wieder und ist als Leuchten zu sehen.\n\nDer Preis dafür ist Schärfe: Das zurückgeworfene Licht streut ein wenig, das Bild wird körniger. Menschen haben diese Schicht nicht, deshalb erscheinen unsere Augen auf Blitzbildern rot – da sieht man einfach die durchblutete Netzhaut.','assets/quiz-illustrations/katzenauge.svg','Tiere'),
(67,'de','Welche Form hätte eine Kerzenflamme in Schwerelosigkeit?','Sie sähe genauso aus wie auf der Erde','Sie wäre flach und breit','Sie wäre kugelförmig','C','Die spitze Form kommt allein von der Schwerkraft: Heißes Gas ist leichter, steigt auf und zieht unten kühle Luft nach. Fällt dieser Auftrieb weg, kann Sauerstoff nur noch von allen Seiten hineindiffundieren – die Flamme wird zur kleinen Kugel. Auf der Raumstation wurde das mehrfach beobachtet.\n\nSie sieht dabei auch anders aus: bläulich statt gelb und deutlich kühler. Ohne aufsteigenden Strom bekommt sie weniger Sauerstoff, es entsteht kaum Ruß – und gelb ist eine Kerzenflamme auf der Erde nur, weil glühende Rußteilchen darin leuchten.','assets/quiz-illustrations/kerze.svg','Physik'),
(68,'de','Wie löst Seife Fett, das Wasser allein nicht wegbekommt?','Ihre Moleküle haben ein wasser- und ein fettliebendes Ende','Sie zersetzt das Fett chemisch','Sie senkt die Temperatur, bei der Fett schmilzt','A','Ein Seifenmolekül ist ein Zwitter: ein langer fettliebender Schwanz, ein wasserliebender Kopf. Im Wasser lagern sich viele davon so um einen Fetttropfen, dass alle Schwänze im Fett stecken und alle Köpfe nach außen zeigen. Diese Kügelchen nennt man Micellen – von außen wirken sie wasserfreundlich und lassen sich einfach abspülen.\n\nDerselbe Bau macht Seife gegen viele Viren wirksam: Sie haben eine Fetthülle, und die Seifenschwänze fahren regelrecht hinein und reißen sie auf. Deshalb ist gründliches Händewaschen kein bloßes Wegspülen.','assets/quiz-illustrations/seife.svg','Alltag'),
(69,'de','Warum vergilbt altes Papier?','Der Leim zwischen den Fasern zerfällt','Papier nimmt mit der Zeit Staub in die Fasern auf','Holzbestandteile werden durch Luft und Licht abgebaut','C','Billiges Papier enthält Lignin, den Stoff, der Holz steif macht. Lignin reagiert mit Sauerstoff und Licht, und die Abbauprodukte sind gelblich-braun. Dazu kommt Säure aus der Herstellung, die die Zellulosefasern langsam zerlegt – das Papier wird nicht nur gelb, sondern auch brüchig.\n\nZeitungspapier vergilbt in Tagen am Fenster, gutes Buchpapier hält Jahrzehnte. Archive verwenden deshalb säurefreies, ligninarmes Papier. Und Bücher aus dem 16. Jahrhundert sind oft besser erhalten als solche von 1900: Damals wurde aus Hadern gearbeitet, nicht aus Holzschliff.',NULL,'Alltag'),
(70,'de','Warum hat gewöhnliches Fensterglas an der Schnittkante einen grünen Ton?','Von einer Beschichtung gegen Wärmeeinstrahlung','Von einer Grünfärbung, die Sprünge sichtbar macht','Von Eisenverunreinigungen im Sand','C','Der Quarzsand für Flachglas enthält immer Spuren von Eisen. Eisenoxid absorbiert vor allem im roten Bereich, übrig bleibt ein leichter Grünstich. Durch eine dünne Scheibe fällt das kaum auf, entlang der Kante schaut man aber durch viele Zentimeter Glas – und dort summiert sich der Effekt sichtbar.\n\nWo es auf Farbtreue ankommt, wird eisenarmer Sand verwendet: Solche Weißgläser kosten mehr und kommen bei Vitrinen, Bilderrahmen und Solarmodulen zum Einsatz. Umgekehrt lassen sich mit anderen Metallzusätzen kräftige Farben erzeugen – Kobalt für Blau, Selen für Rot.',NULL,'Physik'),
(71,'de','Warum klingt die eigene Stimme in einer Aufnahme so fremd?','Mikrofone geben tiefe Töne schwächer wieder','Beim Sprechen hört man sich zusätzlich über die Schädelknochen','Man hört sich selbst immer mit Verzögerung','B','Beim Sprechen erreicht der Schall das Innenohr auf zwei Wegen: durch die Luft und direkt durch Kiefer- und Schädelknochen. Der Knochenweg überträgt tiefe Frequenzen besonders gut. Man hört sich deshalb voller und dunkler, als man tatsächlich klingt. Die Aufnahme kennt nur den Luftweg – und die ist die ehrliche Version.\n\nDas ist auch der Grund, warum man beim Zuhalten der Ohren die eigene Stimme noch dröhnend hört. Sänger und Sprecher üben deshalb mit Aufnahmen: Nur so hören sie, was das Publikum hört.','assets/quiz-illustrations/stimme.svg','Körper'),
(72,'de','Warum kann man sich nicht selbst kitzeln?','Der Reiz erreicht das Gehirn zu langsam','Die eigene Hand berührt zu gleichmäßig','Das Kleinhirn kündigt die eigene Berührung vorher an','C','Das Kleinhirn schickt bei jeder eigenen Bewegung eine Vorhersage an die Sinnesbereiche des Gehirns: Achtung, diese Berührung kommt von uns. Was zur Vorhersage passt, wird abgeschwächt. Genau deshalb erschrickt man auch nicht über den eigenen Schritt und stört sich nicht am Gefühl der eigenen Kleidung.\n\nForscher haben den Effekt mit einem Roboterarm ausgehebelt: Baut man eine kleine Verzögerung zwischen Handbewegung und Berührung ein, kitzelt es plötzlich doch. Und Menschen mit bestimmten psychischen Erkrankungen, bei denen diese Vorhersage gestört ist, können sich sehr wohl selbst kitzeln.',NULL,'Körper'),
(73,'de','Warum sieht man Blutgefäße unter der Haut bläulich, obwohl Blut rot ist?','Sauerstoffarmes Blut in den Venen ist tatsächlich blau','Die Gefäßwände selbst sind bläulich gefärbt','Die Haut lässt rotes Licht anders passieren als blaues','C','Sauerstoffarmes Blut ist nicht blau, sondern dunkelrot – bei einer Blutabnahme kann man das sehen. Blau entsteht erst durch die Haut: Rotes Licht dringt tief ein und wird im Gewebe fast vollständig verschluckt, blaues wird schon in oberen Schichten zurückgestreut. Über einem dunklen Gefäß gewinnt daher der blaue Anteil.\n\nDeshalb hängt der Effekt an der Tiefe: Sehr oberflächliche Gefäße wirken rötlich, tiefere kaum sichtbar, und in der mittleren Tiefe erscheinen sie blau. Es ist derselbe Grund, aus dem Tätowierfarbe in tieferen Hautschichten bläulich schimmert.',NULL,'Körper'),
(74,'de','Warum müssen manche Menschen niesen, wenn sie ins helle Licht treten?','Licht trocknet die Nasenschleimhaut aus','Ein Nerv leitet den Reiz fehl','Die Pupillenbewegung reizt die Nasennebenhöhlen','B','Sehnerv und Gesichtsnerven laufen nahe beieinander, und bei einem Teil der Menschen springt der starke Lichtreiz auf die Bahn über, die den Niesreflex auslöst. Das Gehirn deutet ihn als Reizung in der Nase. Der Reflex ist erblich, betrifft je nach Untersuchung 18 bis 35 Prozent der Bevölkerung und wird meist nach ein bis drei Mal Niesen abgeschlossen.\n\nBeschrieben hat ihn schon Aristoteles, der ihn allerdings der Wärme der Sonne zuschrieb. Für Kampfpiloten und Skispringer ist er tatsächlich ein Thema – ein Nieser beim Verlassen eines Tunnels kommt zum ungünstigsten Zeitpunkt.',NULL,'Körper'),
(75,'de','Warum werden Haare grau?','Sie lagern mit dem Alter weißes Keratin ein','Die Farbstoffzellen in der Haarwurzel geben auf','Luft dringt in den Haarschaft ein','B','Die Farbe eines Haares kommt von Melanozyten in der Wurzel, die dem wachsenden Haar Pigment beigeben. Deren Nachschub an Stammzellen erschöpft sich mit den Jahren; kommt kein Pigment mehr, wächst das Haar farblos nach. Es wirkt weiß, weil Licht in ihm gestreut wird. Grau ist nur der Mischeindruck aus weißen und noch pigmentierten Haaren.\n\nEin einzelnes Haar wird also nicht grau – es wächst grau nach. Als Beschleuniger gilt außerdem Wasserstoffperoxid, das sich in der Wurzel anreichert und Pigment bleicht. Dass Haare über Nacht vom Schreck weiß werden, ist dagegen physikalisch unmöglich.',NULL,'Körper'),
(76,'de','Warum haben Männer Brustwarzen?','Sie sind ein Rest aus der Evolution der Säugetiere','Alle Embryonen legen sie an, bevor Hormone wirken','Sie erfüllen eine Aufgabe bei der Temperaturregelung','B','In den ersten Wochen entwickeln sich alle Embryonen nach demselben Bauplan, und dazu gehört die Anlage der Brustdrüsen. Erst danach steuern Hormone die weitere Entwicklung in eine Richtung. Die bereits angelegte Struktur wird nicht rückgebaut – sie bleibt einfach unentwickelt stehen.\n\nDass sie funktionsfähiges Gewebe ist, zeigt sich in Ausnahmen: Unter bestimmten hormonellen Bedingungen kann auch bei Männern Brustgewebe wachsen, und Männer können an Brustkrebs erkranken. Rund ein Prozent aller Fälle betrifft Männer – oft spät erkannt, weil niemand damit rechnet.',NULL,'Körper'),
(77,'de','Warum schmeckt Essen im Flugzeug fade?','Es wird zu lange warmgehalten','Trockene Luft, niedriger Druck und Lärm dämpfen den Geschmack','Die Bordküche darf kein Salz verwenden','B','Drei Dinge kommen zusammen. Die Kabinenluft ist extrem trocken, die Nasenschleimhaut nimmt Duftstoffe schlechter auf – und Geschmack ist zum größten Teil Geruch. Der reduzierte Druck dämpft zusätzlich. Und der Dauerlärm von rund 85 Dezibel senkt messbar die Wahrnehmung von süß und salzig. Etwa 30 Prozent Empfindlichkeit gehen verloren.\n\nEine Geschmacksrichtung bleibt weitgehend verschont und wird im Lärm sogar verstärkt: Umami. Genau deshalb ist Tomatensaft an Bord so beliebt, obwohl ihn am Boden kaum jemand bestellt – und deshalb würzen Airline-Küchen deutlich kräftiger, als es am Boden schmecken würde.',NULL,'Essen & Trinken'),
(78,'de','Warum hallt ein leerer Raum so stark?','Weil die Luft ohne Möbel besser schwingt','Weil Möbel und Textilien den Schall sonst aufnehmen','Weil der Schall an mehr Ecken gebrochen wird','B','Schall wird an harten, glatten Flächen fast vollständig zurückgeworfen und läuft im Raum hin und her, bis die Energie verbraucht ist. Weiche und poröse Dinge – Sofa, Teppich, Vorhang, Bücherregal, auch Menschen – nehmen ihn stattdessen auf und wandeln ihn in ein wenig Wärme um. Fehlen sie, dauert das Ausklingen deutlich länger.\n\nGenau diese Nachhallzeit ist die zentrale Größe der Raumakustik: In einem Wohnzimmer liegt sie bei etwa einer halben Sekunde, in einem leeren Neubau gern über zwei, in einer großen Kirche bei sechs oder mehr. Und weil Publikum stark absorbiert, klingt ein Konzertsaal bei der Probe anders als bei der Aufführung.',NULL,'Alltag'),
(79,'de','Warum kann man den Mond auch am helllichten Tag sehen?','Weil er hell genug ist, um sich gegen den blauen Himmel zu behaupten','Weil er näher ist als jeder Stern','Weil das Sonnenlicht ihn tagsüber zusätzlich anstrahlt','A','Der Mond ist kein Nachtobjekt – er steht schlicht dann am Himmel, wenn seine Bahn ihn dorthin führt, und das ist oft am Tag. Sichtbar ist er, weil seine Oberfläche genug Sonnenlicht zurückwirft, um heller zu sein als der gestreute blaue Himmel dahinter. Sterne schaffen das nicht, ihr Licht geht darin unter.\n\nAm besten gelingt es rund um die Halbmondphasen: Dann steht der Mond etwa 90 Grad von der Sonne entfernt, also hoch am Himmel, während die Sonne noch scheint. Bei Vollmond geht er dagegen ungefähr mit dem Sonnenuntergang auf – tagsüber ist er dann unter dem Horizont.',NULL,'Weltall'),
(80,'de','Warum haben fast alle Schrauben ein Rechtsgewinde?','Weil es für Rechtshänder beim Anziehen günstiger ist','Weil Linksgewinde sich leichter von selbst lösen','Weil die ersten Gewindeschneidmaschinen nur so arbeiten konnten','A','Beim Anziehen mit der rechten Hand ist die Drehung im Uhrzeigersinn kräftiger und kontrollierter als die Gegenrichtung – der Unterarm dreht dabei nach innen. Da die meisten Menschen Rechtshänder sind, setzte sich diese Richtung als Norm durch und wurde später einfach festgeschrieben.\n\nLinksgewinde gibt es dort, wo die Norm gefährlich wäre: an der linken Fahrradpedale, damit sie sich im Betrieb nicht losdreht, an manchen Sägeblattmuttern und an Gasflaschen für brennbare Gase, damit man keinen falschen Anschluss aufschraubt. Die Ausnahme ist also immer eine bewusste Sicherung.',NULL,'Geschichte'),
(81,'de','Was bedeutet »ok« ursprünglich?','Es ist die Abkürzung eines Ortsnamens','Es stammt von einem indianischen Wort für zustimmen','Es war ein Scherz mit absichtlich falscher Schreibung','C','1839 war in Bostoner Zeitungen eine Mode in Umlauf, Redewendungen absichtlich falsch zu schreiben und dann abzukürzen. »Oll korrect« für »all correct« wurde zu o.k. Die meisten dieser Scherzkürzel starben binnen Monaten – dieses eines nicht, weil es kurz darauf im Präsidentschaftswahlkampf eine zweite Bedeutung bekam.\n\nMartin Van Buren stammte aus Kinderhook und wurde »Old Kinderhook« genannt; seine Anhänger gründeten O.K.-Clubs. Beides zusammen machte die zwei Buchstaben unsterblich – heute gilt »ok« als das international am weitesten verbreitete Wort überhaupt.',NULL,'Sprache'),
(82,'de','Woher kommt das Wort »Panik«?','Von einem mittelalterlichen Arzt, der es beschrieb','Von einem lateinischen Wort für Flucht','Von einem griechischen Gott','C','Pan war der griechische Hirtengott mit Ziegenbeinen, zuständig für Wälder und Weiden. Ihm wurde nachgesagt, Wanderer und ganze Herden mit einem plötzlichen Schrecken zu überfallen – ein grundloses Entsetzen, das ohne erkennbaren Anlass durch die Menge lief. Dieser panische Schrecken wurde zum Wort.\n\nAuf ihn geht noch mehr zurück: die Panflöte, die er der Sage nach erfand, und über einen Umweg die christliche Teufelsdarstellung mit Hörnern und Ziegenfüßen. Das Wort »Pandemie« hat dagegen nichts mit ihm zu tun – das ist griechisch »das ganze Volk«.',NULL,'Sprache'),
(83,'de','Warum riecht es nach Regen so charakteristisch?','Tropfen schleudern Bodenöle und Bakteriensporen in die Luft','Blitze erzeugen Ozon in Bodennähe','Verdunstendes Wasser nimmt Staubgeruch mit','A','Trifft ein Tropfen auf trockenen Boden, schließt er kurz Luft ein. Die entweicht als Schwarm winziger Bläschen und reißt Stoffe von der Oberfläche mit: pflanzliche Öle, die sich in Trockenzeiten ablagern, und den Duftstoff Geosmin aus Bodenbakterien. Der Vorgang wurde mit Hochgeschwindigkeitskameras sichtbar gemacht.\n\nGeosmin ist der Hauptträger dieses Erdgeruchs, und die menschliche Nase ist dafür extrem empfindlich – wenige Teile pro Billion genügen. Derselbe Stoff macht Rote Bete erdig und ist der Grund, warum ein einzelner Tropfen Regenwasser im Trinkwasser sofort auffällt. Der Name für den Duft: Petrichor.',NULL,'Natur'),
(84,'de','Warum ist Schnee weiß, Eis aber durchsichtig?','Schnee enthält eingeschlossene Luft, die das Licht streut','Schneekristalle haben eine weiße Eigenfarbe','Schnee reflektiert nur Licht von der Oberfläche','A','Schnee ist nichts anderes als Eis – nur besteht er aus Millionen winziger Kristalle mit Luft dazwischen. An jeder Grenze zwischen Eis und Luft wird Licht ein Stück abgelenkt. Nach unzähligen Ablenkungen verlässt es den Schnee in alle Richtungen und in allen Farben gleichmäßig: Das nehmen wir als Weiß wahr.\n\nDasselbe Prinzip macht Zuckerwatte, Schaum und Wolken weiß, obwohl ihre Bestandteile klar sind. Und wo Schnee tief und dicht gepresst ist, sieht man den nächsten Effekt: In Gletschern wird nach langem Weg rotes Licht doch absorbiert – deshalb leuchtet Gletschereis blau.',NULL,'Natur'),
(85,'de','Warum bleibt Wasser in einem Eimer, den man im Kreis herumschleudert?','Eine Kraft drückt es nach außen an den Boden','Der Eimerboden zwingt es fortwährend auf die Kreisbahn','Die Luftströmung hält es im Eimer','B','Nach Trägheit will das Wasser geradeaus weiterfliegen. Der Eimerboden steht ihm dabei ständig im Weg und lenkt es nach innen um – diese nach innen gerichtete Kraft hält es auf der Kreisbahn. Am höchsten Punkt übernimmt die Schwerkraft einen Teil davon, den Rest liefert weiter der Boden. Wird zu langsam geschleudert, reicht die Schwerkraft allein nicht als Kurvenkraft aus, und das Wasser fällt heraus.\n\nDie oft genannte Zentrifugalkraft »nach außen« gibt es nur als Rechenhilfe für einen Beobachter, der sich mitdreht. Von außen betrachtet wirkt keine nach außen gerichtete Kraft – es wirkt nur zu wenig nach innen.',NULL,'Physik'),
(86,'de','Warum haben Flugzeugflügel oft nach oben gebogene Enden?','Um den Wirbel an der Flügelspitze zu bremsen','Um bei Bodenmanövern Platz zu sparen','Um dem Flügel mehr Stabilität zu geben','A','An der Flügelspitze trifft der Überdruck von unten auf den Unterdruck oben und rollt sich zu einem kräftigen Wirbel auf. Dieser Wirbel kostet Energie, ohne Auftrieb zu bringen. Ein aufgestelltes Ende – Winglet oder gebogene Spitze – erschwert dieses Umströmen und schwächt den Wirbel ab. Je nach Bauart bringt das mehrere Prozent Kraftstoffersparnis.\n\nDie Wirbel sind mehr als eine Detailfrage: Sie sind der Grund für die vorgeschriebenen Abstände zwischen startenden Flugzeugen, weil ein Wirbelschlepp ein kleineres Flugzeug hinter einem großen umwerfen kann. Bei Zugvögeln nutzt der Formationsflug denselben Effekt aus – der Nachfolger fliegt im Aufwind des Vordermanns.',NULL,'Technik'),
(87,'de','Warum ist es im Weltall kalt, obwohl die Sonne dort ungefiltert scheint?','Weil ohne Materie kaum Wärme übertragen werden kann','Weil die Sonnenstrahlung sich mit der Entfernung fast verliert','Weil die Temperatur im Vakuum grundsätzlich null ist','A','Temperatur ist die Bewegung von Teilchen – wo fast keine sind, gibt es kaum etwas zu erwärmen. Auf der Erde geben Luft und Wasser Wärme durch Berührung und Strömung weiter; im Vakuum fällt beides weg, es bleibt nur Strahlung. Ein Objekt in der Sonne wird darum sehr heiß, im Schatten sehr kalt, und zwischen beiden Seiten liegen Hunderte Grad.\n\nDaher ist Kühlen im All das eigentliche Problem, nicht Heizen: Die Raumstation trägt große Radiatoren, um Abwärme loszuwerden. Und Raumanzüge sind nicht dick gegen Kälte, sondern isolieren nach beiden Seiten und haben ein eigenes Kühlsystem gegen die Körperwärme.',NULL,'Weltall'),
(88,'de','Warum hat die Zahnpasta-Tube oben ein farbiges Rechteck?','Es ist eine Markierung für die Schneidemaschine','Es verschlüsselt die Inhaltsstoffe','Es zeigt die Herkunft der Rohstoffe an','A','Die farbigen Kästchen sind Passermarken für die Verpackungsmaschine. Ein Lichtsensor erkennt den Farbblock gegen den hellen Untergrund und weiß dadurch genau, an welcher Stelle die endlose Tubenbahn geschnitten und versiegelt werden muss. Die Farbe selbst ist beliebig – sie muss nur genug Kontrast liefern.\n\nEntsprechend ist die verbreitete Erzählung frei erfunden, grün stehe für rein natürliche und schwarz für rein chemische Inhaltsstoffe. Dieselben Marken finden sich an Chipstüten, Kaffeeverpackungen und Wurstfolien, wo niemand eine geheime Botschaft vermutet.',NULL,'Alltag'),
(89,'de','Warum wird ein Handyakku im Winter draußen so schnell leer?','Die chemischen Vorgänge im Akku laufen langsamer','Das Display braucht bei Kälte mehr Strom','Der Akku verliert bei Kälte tatsächlich Ladung','A','In einem Lithium-Ionen-Akku müssen Ionen durch einen Elektrolyten wandern. Bei Kälte wird der zäher und die Wanderung langsamer, der Innenwiderstand steigt. Der Akku kann die geforderte Leistung nicht mehr liefern, die Spannung bricht unter Last ein, und die Elektronik deutet das als »leer« und schaltet ab. Die Energie ist dabei nicht verloren – im Warmen zeigt das Gerät oft wieder Ladung an.\n\nWichtig ist die Folge fürs Laden: Ein Akku unter null Grad sollte nicht geladen werden, weil sich dann metallisches Lithium abscheiden kann, was ihn dauerhaft schädigt. Gute Geräte verweigern das Laden bei Kälte deshalb von selbst.',NULL,'Technik'),
(90,'de','Warum sind die Gleise in vielen Ländern genau 1435 Millimeter breit?','Das Maß ergab sich aus Berechnungen zur Kurvenstabilität','Es entspricht der Breite eines römischen Streitwagens','Es übernahm das Maß englischer Kohlebahnen','C','George Stephenson baute seine Lokomotiven für Kohlebahnen im Nordosten Englands, deren Spurweite sich aus dem örtlichen Fuhrwerksbau ergeben hatte. Als seine Maschinen sich durchsetzten, wurde deren Maß mitgeliefert und später als Normalspur festgeschrieben – gut 1435 Millimeter, also vier Fuß achteinhalb Zoll.\n\nDie beliebte Erzählung, das Maß gehe auf die Achsbreite römischer Streitwagen zurück, ist eine Legende ohne Belege. Dass verschiedene Länder bewusst andere Spurweiten wählten, hatte oft militärische Gründe: Eine abweichende Spur bremst einen Angreifer, weil er seine Züge nicht einfach weiterfahren lassen kann.',NULL,'Geschichte'),
(1,'en','Why does Emmental cheese have holes?','They are punched with needles during moulding','Bacteria produce carbon dioxide inside the cheese','Liquid evaporates from cavities as it ripens','B','Propionic acid bacteria are responsible. As the cheese ripens they break down lactic acid and release carbon dioxide in the process. The gas cannot escape from the solid wheel, so it collects at tiny nucleation points – and those become the round holes, known in the trade as »eyes«.\n\nWhat happens when you work too cleanly is telling: small particles of hay in the milk used to serve as those nucleation points. Since modern milking systems deliver practically particle-free milk, the holes have become measurably smaller. Some dairies now deliberately add hay dust again.','assets/quiz-illustrations/emmentaler.svg','Food & Drink'),
(2,'en','Why are bananas curved?','The fruit grows upwards against gravity','The weight of the bunch bends them downwards','The skin dries on one side and contracts','A','The flower stalk of the banana plant hangs downwards at first. The young fruits then grow back upwards, against gravity and towards the light – botanists call this negative gravitropism. Because they start low and end high, the curve appears.\n\nSo the bend is not the result of breeding but an ordinary growth response. Wild bananas are just as curved – they are simply full of hard seeds and barely edible.',NULL,'Nature'),
(3,'en','Why does chilli burn in your mouth when nothing is actually hot?','The pungent compound slightly corrodes the mucous membrane','It irritates precisely the nerves that report heat','It briefly raises the temperature inside your mouth','C','The pungent compound capsaicin docks onto a receptor called TRPV1. That receptor is really a heat detector and normally fires from about 43 degrees. Capsaicin opens it chemically – so the brain receives a genuine heat report without any warmth being involved.\n\nThat is why water hardly helps: capsaicin is fat-soluble. Milk, yoghurt or cream bind it effectively. And because birds have this receptor built differently, chillies do not taste hot to them at all – handy for the plant, since birds spread the seeds unharmed.','assets/quiz-illustrations/chili.svg','Body'),
(4,'en','Why do onions make you cry when you cut them?','A gas forms an acid on the surface of your eye','Onion juice mechanically irritates the cornea','The intense smell triggers a reflex in the brain','C','When the onion is damaged, two substances meet that were kept apart inside the cell. An enzyme builds a volatile sulphur compound from them. It rises, and on the moist surface of the eye it reacts to form a weak acid. The eye flushes it away with tears.\n\nThat also explains why the household remedies work: a chilled onion releases less gas, a sharp knife destroys fewer cells, and anyone working close to an extractor hood gets less of it into their eyes.',NULL,'Food & Drink'),
(5,'en','Why does a golf ball have dimples?','They improve your grip at the tee','They make the ball easier to spot in the grass','They reduce air resistance considerably','A','A smooth ball makes the airflow separate early and drags a wide wake behind it. The dimples create a thin, turbulent layer right at the surface that follows the contour for longer. The wake shrinks, drag falls – and the backspin generates additional lift.\n\nThe effect is enormous: a smooth golf ball flies only about half as far. It was discovered by accident, because players in the 19th century noticed that their old, scuffed balls flew better than new ones.','assets/quiz-illustrations/golfball.svg','Technology'),
(6,'en','Why are tennis balls yellow?','Yellow stays clean longest on clay','Because of visibility on colour television','The dye makes the felt more durable','A','Until the 1970s tennis balls were white. Colour television turned that into a problem: against bright lines and white clothing the ball was hard to follow on screen. Studies showed that a vivid yellow-green was easiest to see. The international federation permitted it in 1972.\n\nWimbledon nevertheless stuck with the white ball until 1986 – tradition. The official name of the colour is »optic yellow«, and whether the ball is yellow or green is something spectators argue about to this day.',NULL,'History'),
(7,'en','Why are the cabin lights dimmed for take-off and landing?','To save power for the engines','So that your eyes are adapted to darkness','So the pilots get fewer reflections in the cockpit','A','Take-off and landing are the critical phases. If an evacuation were needed in the dark, eyes that had just been used to bright cabin lighting would take several minutes to make anything out outside. With the lights dimmed they are already pre-adapted.\n\nWindow blinds have to stay open for the same reason: from inside, the crew must be able to see whether there is fire or debris on one side before opening a door. And the emergency lighting runs along the floor, because down there it stays visible even in smoke.',NULL,'Technology'),
(8,'en','Why does every aircraft window have a small hole at the bottom?','So the pane does not fog up on the inside','It drains condensation','It makes sure the outer pane carries the pressure','B','A cabin window consists of several acrylic panes. The tiny hole in the middle pane connects the gap to the cabin. As a result the entire pressure difference to the thin outside air rests on the outer pane, which is built precisely for it. The middle one is the reserve, in case the outer one fails.\n\nAs a side effect, moisture escapes from the gap so the panes do not ice up from inside. Handling both at once is good engineering with a drill hole.','assets/quiz-illustrations/flugzeugfenster.svg','Technology'),
(9,'en','Why is the sea salty?','Rivers carry dissolved rock into it','Undersea salt deposits slowly dissolve','Marine organisms constantly release salts','A','Rain is slightly acidic and dissolves minerals out of rock as it runs off. Rivers transport these salts to the sea. Water evaporates from there again – the salts stay behind. Over millions of years this has settled at a content of around 35 grams per litre. Undersea volcanic vents supply a second contribution.\n\nSo why does it not get ever saltier? Because salts also disappear again: they are built into sediments, deposited in cut-off sea basins and dragged into the depths with the tectonic plates. Supply and removal roughly balance out.',NULL,'Nature'),
(10,'en','What is the cracking sound when you crack your knuckles?','Tendons snapping over a bony ridge','A gas bubble in the joint fluid','Cartilage surfaces briefly rubbing together','A','When you pull the joint apart, the gap widens faster than fluid can flow in. Pressure drops, and dissolved gases abruptly form a bubble. It is the formation of that bubble which makes the sound – MRI scans have now caught it on film.\n\nThat is why you cannot do it again immediately: the gas has to dissolve back in first, which takes around 20 minutes. And the popular warning is not quite right – studies of habitual crackers found no increased rate of arthritis, at most slightly less grip strength.',NULL,'Body'),
(11,'en','How many hearts does an octopus have?','One, but with four chambers','Two, one per side of the body','Three','A','Two branchial hearts each pump the blood through one gill, and a larger main heart then sends it around the body. This is necessary because the oxygen carrier in octopus blood, copper-based haemocyanin, works far less efficiently than our iron-based haemoglobin. Incidentally, it makes the blood bluish.\n\nThe main heart stops while the animal swims – one reason octopuses prefer walking across the seabed to swimming. Swimming simply tires them out faster.',NULL,'Animals'),
(12,'en','Why do penguins not freeze to the ice by their feet?','The soles of their feet are insulated with fat','Incoming and outgoing blood exchange heat','They keep their feet permanently slightly raised','A','In the legs, arteries and veins lie close together and run in opposite directions. Warm blood from the body passes its heat straight to the cold blood returning. What arrives at the bottom is only just above freezing – warm enough not to freeze fast, and cold enough that almost no heat is lost.\n\nDucks on ice, whales in their flukes and reindeer in their legs use this counter-current principle too. The penguin can also regulate the blood flow – on warm days it releases more heat through its feet.','assets/quiz-illustrations/pinguin.svg','Animals'),
(13,'en','What colour is a polar bear\'s skin?','Black','Pink, as in other bears','Light grey with white patches','C','Under the fur, a polar bear\'s skin is black – clearly visible on the nose and lips. Dark skin absorbs heat better. The hairs themselves are not white but colourless and translucent. They look white because light is scattered inside them, much as in snow or candyfloss.\n\nThat is why polar bears in zoos can turn greenish: if algae settle in the hollow hairs, the coat takes on a green shimmer. The widespread idea that the hairs channel sunlight to the skin like optical fibres is now considered disproved.',NULL,'Animals'),
(14,'en','Why is the sky blue?','It reflects the colour of the oceans','Air molecules scatter blue light most strongly','Water vapour filters out red light','B','Sunlight contains all colours. Air molecules scatter short-wavelength light in all directions far more strongly than long-wavelength light – this relationship is called Rayleigh scattering. Blue therefore reaches us from the whole sky, not just directly from the sun.\n\nViolet would be scattered even more strongly, but the sun emits less of it and our eyes are less sensitive to it. And in the evening? Then the light travels at a slant through far more air, the blue has been scattered out along the way – what remains is orange and red.','assets/quiz-illustrations/himmelblau.svg','Nature'),
(15,'en','Why does ice float on water?','Trapped air bubbles keep it up','Surface tension holds it at the top','Water becomes lighter as it freezes','A','Almost all substances become denser as they solidify. Water does not: in ice the molecules arrange themselves into a wide-meshed lattice with cavities. Ice therefore takes up about nine per cent more room than the same amount of liquid water – so it floats. Water is densest at around four degrees.\n\nThis density anomaly is one reason life in lakes survives the winter: the ice sheet forms on top and insulates, while below it stays liquid at four degrees. If ice sank, lakes would freeze from the bottom up.','assets/quiz-illustrations/eis.svg','Physics'),
(16,'en','Why are manhole covers round?','Because a round cover cannot fall into the shaft','Because pipes are round and the cover matches them','Because round covers are easier to cast','B','A circle has the same diameter in every direction. A round cover therefore cannot be turned in a way that lets it slip through its own opening – with a square cover it is enough to hold it diagonally. For workers under the street that is a solid safety argument.\n\nOn top of that come practical points: round covers do not need to be aligned when you put them back, they can be rolled instead of carried, and the round shape channels the weight of lorries driving over evenly into the rim – corners would be weak spots.','assets/quiz-illustrations/kanaldeckel.svg','Everyday life'),
(17,'en','Where does the name of the Bluetooth wireless standard come from?','From a blue component in the first prototype','From a Danish king','From a code name for blue cables at Ericsson','B','The namesake is Harald Bluetooth, who united Danish tribal territories in the 10th century and brought Norway into the fold. An engineer proposed the name as a working title: just as the king united tribes, the technology was meant to unite different devices. The working title stuck because marketing could not agree on anything else.\n\nEven the logo fits: it combines the Old Norse runes for H and B – the king\'s initials. Where the nickname Bluetooth came from is unclear; perhaps from a dark, dead tooth.',NULL,'Language'),
(18,'en','Why do jeans have small metal rivets at the pockets?','They are a mark of genuine branded goods','They reinforce the places where the fabric tears','They discharge static electricity','B','The tailor Jacob Davis patched work trousers for gold prospectors and was annoyed that the pocket corners always came apart. He simply fitted rivets from the harness workshop. Because he lacked the money for a patent, in 1873 he teamed up with his fabric supplier Levi Strauss – and that rivet became the modern pair of jeans.\n\nOne rivet later disappeared again: the one at the crotch. It became uncomfortably hot by the campfire. And the small fifth pocket at the front was once the pocket for a pocket watch.',NULL,'Everyday life'),
(19,'en','Why do we always see the same side of the moon?','It does not rotate at all','Its rotation takes exactly as long as one orbit','The earth hides the other side with its shadow','A','The moon does rotate – it just takes exactly as long to do so as it takes to travel once around the earth, about 27 days. That is why it always shows us the same face. This tidal locking is no coincidence: the earth\'s tidal forces slowed its rotation over millions of years until it clicked into place.\n\nThe view is not entirely rigid. Because the moon\'s orbit is slightly elliptical and tilted, it rocks a little back and forth. Over time this makes around 59 per cent of its surface visible from earth.','assets/quiz-illustrations/mond.svg','Space'),
(20,'en','Why are there seasons?','Because the earth\'s axis is tilted','Because the distance to the sun varies','Because the sun shines with varying strength','A','The earth\'s axis is tilted by a good 23 degrees. As a result sunlight hits the northern hemisphere more steeply and for longer in June, and more shallowly and briefly in December – and exactly the other way round in the southern hemisphere. More steeply means the same energy is spread over less area.\n\nDistance cannot be the reason, if only because it would then be summer everywhere at once. In fact the earth is closest to the sun in early January – in the middle of the European winter.','assets/quiz-illustrations/jahreszeiten.svg','Space'),
(21,'en','Why do stars twinkle but planets barely do?','Planets do not shine themselves, they only reflect','Stars really do change their brightness constantly','Planets appear as a small disc, stars as a point','C','The twinkling does not happen at the star but in our atmosphere: layers of air at different temperatures refract the light differently and steer it back and forth. Even through a telescope a star is only a point of light – if that point is deflected, you notice at once.\n\nA planet, by contrast, is so close that it forms a tiny disc, that is many points side by side. Their fluctuations average out and the light stays steady. A practical trick under the night sky: whatever stands still is usually a planet.',NULL,'Physics'),
(22,'en','Why does honey practically never go off?','Bees add a natural preservative','There is too little free water in it for germs to grow','The high sugar content kills germs chemically','B','Ripe honey contains only around 17 per cent water, and the sugar binds it firmly. Micro-organisms need free water – in honey the surroundings draw fluid out of them instead. Honey is also acidic and contains small amounts of hydrogen peroxide, which the bees introduce via an enzyme.\n\nHoney has been found in Egyptian tombs that had not spoiled after thousands of years. Dilute it, though, and the protection falls away and it starts to ferment – which is exactly what mead-making exploits.',NULL,'Food & Drink'),
(23,'en','Why does cola fizz up so violently when you drop Mentos into it?','The sweets react chemically with the acid','Their rough surface offers countless bubble seeds','They dissolve instantly and displace liquid','B','Carbonated drinks are supersaturated with gas. For a bubble to form, it needs a starting point. Under the microscope the surface of a Mentos is full of pores and edges – thousands of starting points at once. The gas escapes within seconds and pushes the liquid up as a fountain.\n\nIt is not a chemical reaction. Additives in the sweets also lower the surface tension, which makes bubbles form more easily still. With diet cola the fountain goes higher, because without sugar syrup it is thinner.',NULL,'Food & Drink'),
(24,'en','Why does the skin on your fingers wrinkle in water?','The skin soaks up water and expands','The nervous system actively narrows the blood vessels','Skin oil is washed away and the skin collapses','C','You would expect simple swelling – in fact it is a controlled response. The autonomic nervous system narrows the blood vessels under the skin, the volume beneath decreases, and the firm outer layer folds. The proof: if the relevant nerve is damaged, the fingers no longer wrinkle.\n\nWhy the body does this is not settled. Experiments suggest the grooves make wet objects easier to grip – rather as the tread of a tyre channels water away.',NULL,'Body'),
(25,'en','Why do birds on a power line not get a shock?','Their claws are made of insulating material','Feathers do not conduct electricity onwards','There is barely any voltage between their feet','C','Current only flows where there is a difference in voltage. Both of the bird\'s feet sit on the same wire, a few centimetres apart – between them there is almost no voltage, so virtually no current flows through the bird. The easier route remains the copper.\n\nIt becomes dangerous the moment the bird touches something else as well: a second wire, a pylon or an earthed part. That is precisely why large birds with a wide wingspan are particularly at risk on high-voltage pylons.','assets/quiz-illustrations/vogel-leitung.svg','Animals'),
(26,'en','What does the English phrase »to steal someone\'s thunder« originally refer to?','A theatre sound effect','A stolen weather almanac','A cannon fired before a battle','A','In the early 18th century the playwright John Dennis invented a device for producing stage thunder for one of his plays. The play flopped and was taken off, but rival theatres promptly adopted his thunder machine. Dennis is said to have complained that they would not run his play but were stealing his thunder.\n\nThe phrase outlived both the man and his play, and today it means taking someone else\'s moment of glory. Which, given the origin, is rather fitting.',NULL,'Language'),
(27,'en','Why do people say »break a leg« to wish an actor good luck?','Because a famous actor once broke a leg on stage','Because of a superstition that open good wishes bring bad luck','Because bowing deeply was called breaking a leg','C','Behind it lies a widespread superstition in the theatre: whoever wishes for luck openly summons the opposite. So you wish for something bad instead. The custom exists in many languages – Germans wish each other »Hals- und Beinbruch«, a neck and a leg break, and the Italians send you to the wolf.\n\nThe German version probably has an extra twist. It very likely goes back to the Yiddish formula »hatslokhe un brokhe« – luck and blessing. German ears heard something close to »Hals und Bruch«, and since that made no sense, popular usage turned it into a full-blown curse.',NULL,'Language'),
(28,'en','Why is the lettering on the front of an ambulance mirrored?','So it reads correctly in the rear-view mirror','Because the film is easier to apply from inside','It is an international requirement for emergency vehicles','B','The lettering on the front is meant for the driver of the car ahead. They see the vehicle in their rear-view mirror – and in a mirror any writing appears reversed. Applied mirrored from the start, they read it correctly in the mirror and can react sooner.\n\nThat is also why the mirrored lettering only ever appears at the front, never on the sides or the back: only the front ever ends up in someone else\'s rear-view mirror.',NULL,'Everyday life'),
(29,'en','Why does a lightning strike not endanger the people inside an aircraft?','The rubber tyres insulate the aircraft','The metal skin conducts the current around the outside','The altitude weakens the lightning that much','C','The conductive outer skin acts as a Faraday cage: the current runs across the surface and leaves the aircraft again at a discharge point, while the interior stays practically field-free. Statistically, airliners are struck about once a year; passengers usually notice nothing more than a bang and a flash.\n\nIt takes effort with modern carbon-fibre fuselage sections, which conduct less well. There, fine metal meshes or copper foils are laminated in so that the cage keeps working. In addition, small discharge points sit on the trailing edges of wings and tail.','assets/quiz-illustrations/blitz-flugzeug.svg','Physics'),
(30,'en','Why are flamingos pink?','Their plumage contains a red pigment of its own','The colour comes from their food','The structure of the feathers refracts light pink','A','Flamingos filter small crustaceans and algae out of the water. These contain carotenoids – the same group of substances that makes carrots orange. The bird builds them into its skin and feathers. Without that diet it stays pale white, which used to be a regular sight in zoos before the feed was adjusted.\n\nThe colour is also a signal: a strong pink shows that an animal is feeding well and is healthy – and it looks correspondingly attractive when choosing a mate. Breeding parents, on the other hand, fade, because they pass pigments on to their chicks.',NULL,'Nature'),
(31,'en','Why does urine smell after eating asparagus?','Asparagus itself contains strongly smelling oils','The body breaks an asparagus acid down into sulphur compounds','Asparagus is a diuretic and makes the urine more concentrated','A','Asparagus contains asparagusic acid, which barely occurs in this form in any other food. Digestion breaks it down into small, highly volatile sulphur compounds. Because they are so volatile, you can smell them after about a quarter of an hour.\n\nThe curious part: not everyone perceives the smell. A widespread gene variant in the sense of smell makes a substantial share of people blind to it. That is why it was long assumed only some people produced the smell at all – in fact almost everyone does.',NULL,'Body'),
(32,'en','Why does orange juice taste appalling straight after brushing your teeth?','The toothpaste reacts with the fruit acid','A foaming agent blocks your perception of sweetness','The menthol numbs the tongue completely','C','The culprit is usually sodium lauryl sulphate, the substance that makes toothpaste foam. It dampens the receptors for sweetness and at the same time attacks fat molecules that otherwise soften the perception of bitterness. The result: the sweetness of the juice is missing, the acid and the bitter compounds remain – and suddenly taste unbearable.\n\nToothpaste without that foaming agent barely triggers the effect. And anyone who does not want to wait can simply have breakfast before brushing.',NULL,'Body'),
(33,'en','Why does ketchup refuse to come out and then arrive all at once?','Shaking makes it thinner','The narrow opening dams it up at first','Air has to flow into the bottle first','C','Ketchup is one of the non-Newtonian fluids. At rest the tomato particles form a loose network that holds it together almost like a solid. Apply enough force – shaking, tapping, pressure – and that network collapses and the viscosity drops dramatically within seconds. Then everything flows at once.\n\nThe behaviour is called thixotropy and is used deliberately: wall paint should be thin under the brush and not drip on the wall, toothpaste should stand up in the tube and come out under pressure.','assets/quiz-illustrations/ketchup.svg','Physics'),
(34,'en','Why does stainless steel not rust, although it consists mostly of iron?','It is covered with a protective coating applied to it','The chromium in it forms a wafer-thin barrier by itself','Alloying makes the iron chemically untouchable','C','From around twelve per cent chromium something elegant happens: at the surface the chromium reacts immediately with oxygen to form a dense oxide layer only a few atoms thick. It sits firmly, is invisible, and lets no more oxygen reach the iron beneath. But rust needs precisely that access.\n\nThe best part is the self-healing: scratch the layer open and it re-forms within seconds. Only where oxygen is permanently absent – under a stubborn deposit, say – or where chloride breaks it locally can stainless steel corrode after all.','assets/quiz-illustrations/edelstahl.svg','Technology'),
(35,'en','Why are the letters on a keyboard arranged so awkwardly?','The layout follows letter frequency in English','It was meant to stop typewriter bars from jamming','It derives from the arrangement in the telegraph alphabet','C','In mechanical typewriters, type bars struck the paper from below. If two frequently consecutive letters sat next to each other, the bars jammed when typing quickly. Christopher Latham Sholes therefore pulled common letter pairs apart spatially in the 1870s. The result is the QWERTY row, which German keyboards use with Z and Y swapped.\n\nWith computers the reason fell away, yet the layout stayed: millions of people had learned it. Demonstrably faster layouts such as Dvorak or Neo have never caught on.','assets/quiz-illustrations/qwertz.svg','Technology'),
(36,'en','Why do people drive on the left in Great Britain?','Because of the steering in the first cars built there','So that riders had their sword hand towards oncoming traffic','Because the railways ran on the left and the roads followed','C','The usual explanation reaches back long before the car. Anyone travelling on horseback and carrying a sword wore it on the right. Riding on the left kept the weapon hand facing whoever was coming, and left the right hand free for greeting or for a grip without changing the reins. Pope Boniface VIII is said to have advised pilgrims to keep left in the year 1300.\n\nThat much of the world drives on the right today has a lot to do with France and the United States: wide waggons with several draught horses were steered from the left rear horse – the driver wanted oncoming traffic on his left, so he kept to the right.',NULL,'History'),
(37,'en','Why does a week have seven days?','Because of the seven wandering stars visible to the naked eye','Because a lunar month divides neatly into four parts','Because seven counted as a divine number in Babylon','B','Babylonian astronomers knew seven celestial bodies that move against the background of the stars: sun, moon, Mercury, Venus, Mars, Jupiter and Saturn. Each was assigned a day. The seven-day week reached Europe via the Greeks and Romans – so unlike the month and the year, it has no astronomical rhythm it has to follow.\n\nThe names still betray the origin. In English, Saturday, Sunday and Monday are directly Saturn, sun and moon. Tuesday, Wednesday, Thursday and Friday hold Germanic gods who replaced the Roman ones: Tiw, Woden, Thunor and Frige.',NULL,'History'),
(38,'en','Why is the German word for Wednesday, unlike the other weekdays, not named after a god?','Because in antiquity it counted as a day of rest without a deity','Because the church displaced the name of the god Woden','Because it was only added to the week in the Middle Ages','B','Originally it was the day of the god Woden – in English it is still Wednesday, in Dutch woensdag. In the German-speaking world the church pushed through the sober counting form in the early Middle Ages: Mittwoch, the day in the middle of the week.\n\nWith Saturday it partly succeeded too. The north of Germany says Sonnabend, the eve of Sunday, the south says Samstag – which comes by a roundabout route from the Hebrew sabbath. Only Tuesday, Thursday and Friday kept their old divine names in German.',NULL,'Language'),
(39,'en','Why do sparkling wine corks have the shape of a mushroom?','They are pressed that way so you can grip them better','They are cylindrical and only deformed inside the bottle','The mushroom head spreads the pressure of the wire cage','B','Before corking, a sparkling wine cork is a thick cylinder, noticeably wider than the neck of the bottle. Sealing it compresses it hard. The lower part stays trapped in the neck and keeps that compressed shape, while the upper part springs back out outside – and that becomes the mushroom head.\n\nThe shape even lets you read the age: the longer the bottle has lain, the less elastic the cork and the narrower the pulled cork stays. An almost cylindrical cork points to a long-aged sparkling wine.','assets/quiz-illustrations/sektkorken.svg','Food & Drink'),
(40,'en','Why do wine glasses have a long stem?','So your hand does not warm the wine','So the glass stands more steadily when swirled','So the aromas collect in the stem','A','Held by the stem, the warmth of your hand stays away from the wine – with a chilled white that amounts to several degrees over a long meal. Side effect: the bowl stays free of fingerprints and does not fog up, so you can see colour and clarity better.\n\nThat is exactly why a brandy snifter has no long stem: there the warmth of the hand is wanted, it drives the aromas out. And modern stemless glasses are a deliberate compromise – easier to wash, but your hand warms the wine.',NULL,'Food & Drink'),
(41,'en','Why does your stomach rumble?','Stomach acid bubbles when the stomach is empty','Gas and liquid are pushed through the intestine','The stomach wall vibrates with tension','B','Stomach and intestine work even without food: roughly every one and a half to two hours a strong cleaning wave runs through the digestive tract and pushes leftovers along. When it meets a mixture of liquid and air, you get the gurgling noises doctors call borborygmus.\n\nThere is a simple reason it is so loud on an empty stomach: the contents that would muffle the sound are missing. A full stomach rumbles just as much, you just do not hear it.',NULL,'Body'),
(42,'en','What happens in the body when you have hiccups?','The oesophagus cramps in a ring','The diaphragm twitches and the vocal folds snap shut','The stomach briefly presses against the lung','C','A reflex makes the diaphragm contract abruptly – you involuntarily draw in air. Only a fraction of a second later the larynx closes the vocal folds. The inrushing air hits that closure, and that is exactly what produces the characteristic sound.\n\nWhy the reflex exists is unclear; one suspicion traces it back to tadpoles, which do something similar when breathing through gills. The home remedies at least share a principle: holding your breath, drinking water or swallowing something cold either raise the CO₂ level or stimulate the nerve involved – either can interrupt the reflex.',NULL,'Body'),
(43,'en','Why do you get a headache when you eat ice cream too fast?','The brain measurably cools down for a moment','Vessels in the palate react and the pain is mislocated','The sugar makes your blood pressure dip briefly','B','Cold at the palate makes blood vessels first contract and then widen quickly. The trigeminal nerve registers this response – the same nerve that also supplies large areas of the face and forehead. The brain cannot pin the message down precisely and relocates the pain forward into the forehead. Specialists call it referred pain.\n\nThe brain itself does not cool down, and it has no pain receptors either. The whole thing is over within half a minute at most; pressing your tongue against the palate warms the spot and shortens it.',NULL,'Body'),
(44,'en','Why do you hear a rushing sound like the sea in a large shell?','You are hearing your own blood in the vessels of the ear','The shell amplifies quiet ambient noise','Trapped air vibrates at a fixed pitch','C','The cavity of the shell is a resonating body. It picks particular frequencies out of the ever-present quiet carpet of ambient noise and amplifies them – what comes out is a broadband rushing that resembles the sea. A cup or a cupped hand at your ear does exactly the same.\n\nThe blood explanation is easy to refute: in a very quiet room the rushing becomes noticeably weaker, and climbing stairs with a racing pulse does not make it louder. If it were your own blood, it would be the other way round.',NULL,'Body'),
(45,'en','Why do people get seasick?','The balance organ reports something different from the eyes','The rocking throws the stomach mechanically out of rhythm','The air pressure on deck changes the inner pressure of the ear','C','Below deck the eye sees a cabin at rest, while the balance organ in the inner ear feels rocking. The brain cannot reconcile the contradictory messages. A common explanation: it interprets the conflict as poisoning – and the sensible response to poisoning is vomiting.\n\nThe effective countermeasures follow directly from that: go on deck and look at the horizon, so that eyes and inner ear report the same thing. For the same reason the driver rarely feels ill, while the passenger with a book soon does.',NULL,'Body'),
(46,'en','Why can an owl turn its head so far?','Its skull sits on a ball joint','Because its eyes cannot move','So that it can see backwards in flight','A','Owl eyes are huge for maximum light-gathering and are not spheres but tubes – they fill the eye socket completely and are practically immobile. So the owl cannot glance with its eyes, it has to turn its whole head. For that it has 14 neck vertebrae, twice as many as a human, and manages around 270 degrees.\n\nThe blood supply is adapted to this extreme: the arteries run in wide channels and have reserve pockets, so they are not pinched off during the strong twist. A human would cut off the blood supply to the brain with the same movement.','assets/quiz-illustrations/eule.svg','Animals'),
(47,'en','Why do goats have rectangular pupils?','For a very wide field of view without turning the head','So that they can tell colours apart better','To let in less light in bright sunshine','C','The horizontal slit works like a panoramic format: it lets light in from a very wide horizontal angle and delivers a sharp image at ground level, while little is lost above and below. Together with the eyes set at the sides, the goat reaches a field of view of nearly 320 degrees – while grazing it sees almost all around without lifting its head.\n\nThe pattern matches the way of life: grazing prey animals such as goats, sheep and horses have horizontal pupils. Cats, as ambush hunters, have vertical slits, which help judge distances. And while grazing the slit stays horizontal – the eye rotates to compensate for the lowered head.','assets/quiz-illustrations/ziegenpupille.svg','Animals'),
(48,'en','How does a firefly produce its light?','By rubbing fine plates of chitin together','By a chemical reaction with oxygen','By bacteria living in its abdomen','C','In the abdomen an enzyme brings the substance luciferin together with oxygen. Almost all the energy of the reaction is given off as light and hardly any as heat – hence the name cold light. The efficiency is around 40 per cent and beats any light bulb by a mile.\n\nThe flashing is a personal advertisement, and every species has its own rhythm. In the European glow-worms it is usually the flightless females that sit in the grass and glow while the males search on the wing. Some American species take it further: their females imitate the rhythm of other species and eat the males they lure in.',NULL,'Animals'),
(49,'en','Why can a fly walk across the ceiling?','It creates a slight vacuum with its legs','Tiny hairs hold on via a liquid','Its claws grip unevenness in the plaster','A','At the tips of its feet sit two adhesive pads with thousands of extremely fine hairs. Each releases a minute amount of an oily liquid. The thin film of liquid pulls the hair against the surface through capillary forces – almost nothing for each one, but considerably more than the weight of the fly for all of them together.\n\nThat explains two observations: it holds better on smooth glass than on dusty surfaces, because dust breaks the contact. And the fly has to peel itself off actively to get free – sticking fast and coming loose again are two separate tricks.','assets/quiz-illustrations/fliege.svg','Animals'),
(50,'en','What colour were carrots originally?','Orange, just as today','Purple and white','Green like their leaves','B','The cultivated carrot comes from the region of Afghanistan and was purple, yellowish or white. Orange varieties only arose in the early modern period through selection, largely in the Netherlands. They contained plenty of beta-carotene, tasted milder and caught on across Europe – until orange counted as the natural colour of a carrot.\n\nThe popular tale that Dutch gardeners bred the carrot orange in honour of the House of Orange is charming but not historically supported. Purple varieties are back in the shops, by the way – as a novelty.',NULL,'Nature'),
(51,'en','Why does a cut avocado turn brown?','An enzyme reacts with oxygen from the air','The fatty acids in the flesh go rancid','Chlorophyll breaks down under light','C','Cutting destroys cells and an enzyme called polyphenol oxidase meets oxygen. It converts plant compounds into brown pigments – the same reaction colours cut apples, bananas and potatoes. It does not mean the fruit has spoiled.\n\nThe enzyme needs oxygen and dislikes acid. That is why lemon juice and airtight covering work, and why it helps to mix the flesh straight into guacamole with lime. The stone left in the dip, on the other hand, only keeps clear the area it covers itself.',NULL,'Food & Drink'),
(52,'en','Why does bread go stale especially quickly in the fridge?','It dries out faster there than at room temperature','The starch crystallises fastest at fridge temperature','Cold kills the yeasts that keep it soft','B','Going stale is not drying out but a rearrangement: the starch opened up during baking gradually forms firm, crystalline regions again and forces water out. The technical term is retrogradation. And this process runs fastest in the range of a few degrees above zero – fridge temperature is the worst possible point.\n\nSo the rule is: store bread at room temperature or freeze it straight away, because deep-frozen the process practically stops. And because it is reversible, stale bread goes soft again in the oven – brief reheating melts the crystals.',NULL,'Food & Drink'),
(53,'en','Which summit is furthest from the centre of the earth?','Mount Everest in the Himalaya','Chimborazo in Ecuador','Denali in Alaska','A','The earth is not a sphere but bulges at the equator because of its rotation – sea level there lies around 21 kilometres further out than at the poles. Chimborazo stands almost on the equator. Although at a good 6,260 metres above sea level it remains far below Everest, its summit lies about two kilometres further from the centre of the earth.\n\nEverest is still the highest mountain, just by a different measure. Take the foot as the reference and a third contender wins: Mauna Kea in Hawaii rises over 10,000 metres from the sea floor – almost half of it under water.','assets/quiz-illustrations/chimborazo.svg','Space'),
(54,'en','Why do you hear thunder only after the lightning?','The thunder only forms shortly after the discharge','Sound is around a million times slower than light','Clouds hold the sound back at first','B','Lightning and thunder arise at the same moment: the lightning channel heats the air to many thousands of degrees within microseconds, it expands explosively, and that pressure wave is the thunder. Light needs practically no time for the distance, sound about three seconds per kilometre.\n\nHence the familiar rule of thumb: count the seconds, divide by three, and you have the distance in kilometres. The long rolling comes from the fact that the lightning channel is kilometres long – its sections are at different distances, so the sound arrives bit by bit.','assets/quiz-illustrations/blitz-donner.svg','Physics'),
(55,'en','Why are clouds white but rain clouds grey?','Rain clouds contain dust that colours them dark','Thick clouds let hardly any light through to the ground','Water droplets darken as they grow','A','Cloud droplets scatter all colours equally, which is why a cloud appears white. As it grows taller, the light has to pass more and more droplets, is deflected a little at each scattering event and barely arrives at the bottom. Seen from below the cloud therefore looks grey to almost black – not because of its colour but because of its thickness.\n\nFrom above, say from an aircraft, the same thunderstorm cloud is brilliant white. And because large raindrops offer less surface per amount of water than many small droplets, a cloud also scatters more weakly shortly before it rains.',NULL,'Nature'),
(56,'en','Why is red the international colour for »stop«?','Because it recalls blood and therefore danger','Because it stays visible furthest and rarely occurs in nature','Because early signal lamps only had red glass','C','Red light is scattered less by haze and rain than blue is, and is therefore easy to see over great distances – the same principle that makes sunsets red. Add to that the fact that red is rare in the landscape and so stands out. The railways established it as a stop signal in the 19th century, and road traffic took it over from there.\n\nOne colour was dropped along the way: originally white meant »line clear«. After a case in which the red glass fell out and the driver read the bare white lamp as permission to proceed, green took over.',NULL,'Everyday life'),
(57,'en','Why are airliners usually white?','White stays coolest and shows up damage','White paints are particularly durable','White is easiest to pick up on radar','B','White reflects sunlight and keeps the fuselage noticeably cooler on the ground, which takes load off the air conditioning and the material. On a light background, cracks, oil traces and fuel leaks are also immediately visible during inspection. White barely fades, whereas strong colours bleach quickly under high-altitude radiation and need repainting more often.\n\nThere is also a hard-nosed argument: full-surface paint on a large aircraft weighs several hundred kilograms and costs fuel over the years. Some airlines therefore deliberately leave parts bare or paint as thinly as possible.',NULL,'Technology'),
(58,'en','Why do shopping trolleys have a lock for a coin?','To be able to count how many trolleys are handed out','So that the trolleys get brought back','To make stealing the trolleys impossible','B','The coin is a deposit that only the person who hooks the trolley back up gets returned. Commercially it pays off not because of the money but because of the working time saved: without a deposit, staff have to collect trolleys from the car park constantly, and that is where most of the dents in customers\' cars come from.\n\nThe amount is deliberately small. It only has to be large enough to make pushing the trolley back worthwhile – not so large that it puts off customers who have no suitable coin on them.',NULL,'Everyday life'),
(59,'en','Where does the German expression »Schwein gehabt« – literally »had a pig« – come from?','From the pig as a consolation prize at contests','From the piggy bank as a sign of wealth','From a pig-shaped lucky charm of sailors','B','At medieval shooting and sporting contests the person who came last received a pig as a consolation prize. Anyone who carried home a valuable animal despite losing had been lucky after all – and that became the expression. A pig was a fortune: it supplied meat, fat and offspring.\n\nThe lucky pig given at New Year comes from the same root. The piggy bank, on the other hand, probably has an entirely different origin: a type of clay called »pygg« that was used to form saving vessels – and the English similarity in sound to »pig« did the rest.',NULL,'Language'),
(60,'en','Why does the day begin at midnight in our reckoning of time?','Because the Romans changed the official day at midnight','Because sunrise wanders with the season','Because the church had the day begin with the night mass','B','Several points are conceivable as the start of a day, and historically all of them were in use: for the Egyptians and later the Romans the civil day began at midnight, while Jewish and Islamic calendars have it begin at sunset. Midnight won out in practice for a simple reason: sunrise and sunset wander over the year and with latitude, whereas midnight, as the opposite point to the sun\'s highest position, can be defined astronomically and fixed.\n\nAstronomers ignored this for a long time: until 1925 their day began at noon, so that a night of observation did not fall across a change of date. Anyone reading old star catalogues has to allow for that difference.',NULL,'History'),
(61,'en','How does a cat produce its purr?','By vibrating the muscles of the larynx','By air brushing past its teeth','By a fluttering of the diaphragm','B','A signal from the brain makes the muscles at the larynx contract about 25 to 30 times per second. The vocal folds open and close in that rhythm, and because this works while breathing in and out, a cat can purr for minutes without a break – unlike miaowing.\n\nPurring does not automatically mean contentment. Cats also purr in pain, at the vet and while dying. One suspicion: the frequency lies in the range that has been shown in experiments to stimulate bone healing – purring would then also be self-soothing, and perhaps more.',NULL,'Animals'),
(62,'en','What is inside a camel\'s hump?','A water reservoir','Fat','A network of blood vessels','C','The hump is a fat store of up to 35 kilograms. Fat is the best energy store a body can build, and burning it even produces a little water – but the real gain is the energy. After long hunger the hump shrinks and flops limply to one side.\n\nThe camel\'s water performance lies elsewhere: it lets its body temperature rise by several degrees during the day instead of sweating, and its red blood cells are oval and stretchable, so they survive drinking over 100 litres at once without bursting.','assets/quiz-illustrations/kamel.svg','Animals'),
(63,'en','What is the main purpose of an African elephant\'s large ears?','Especially fine hearing','Giving off body heat','Warding off insects','B','The ears are laced with a dense network of surface blood vessels and offer several square metres of area. Fanning them makes air pass over and cool the blood before it flows back into the body – by several degrees in favourable conditions. For an animal of this mass, getting rid of heat is the bigger problem than keeping it.\n\nThat is how you can tell the species apart: the African elephant lives in hotter, open country and has noticeably larger ears than the Asian one. Its hearing is good anyway, though mainly for very low tones, which it picks up for kilometres.','assets/quiz-illustrations/elefantenohr.svg','Animals'),
(64,'en','How many neck vertebrae does a giraffe have?','Seven, exactly as many as a human','Fourteen','Over twenty, similar to a swan','A','Almost all mammals have seven neck vertebrae – the mouse, the human, the whale and indeed the giraffe. In her case each individual vertebra is up to 25 centimetres long. The number is so strictly fixed during development that deviations in humans usually come with malformations.\n\nThere are exceptions: sloths have six to nine depending on the species, manatees six. Birds are not bound at all, a swan has over twenty – which is why its neck is so flexible, while the giraffe moves hers more like a crane.',NULL,'Animals'),
(65,'en','Why do moths circle a lamp?','They mistake the lamp for the moon and miscalculate','They instinctively turn their backs to the brightest light','They are attracted by the warmth of the lamp','C','The moon explanation held sway for a long time. But high-speed footage of flying insects has shown something else: they reflexively keep their backs towards the brightest source of light. In the sky that is the right way to stay upright. Next to a lamp this reflex tips the flight path – the animal ends up in a tight curve around the lamp instead of heading for it.\n\nThat explains observations that never fitted the moon theory: moths do not fly straight into the lamp but circle, tumble and sometimes hang beneath it. For nocturnal insects, artificial light is therefore less an attraction than a navigational trap.',NULL,'Animals'),
(66,'en','Why do a cat\'s eyes glow in headlights?','The retina emits light itself','There is a mirroring layer behind the retina','The cornea throws the light back like a lens','A','Behind the retina lies the tapetum lucidum, a layer of fine crystals that throws light back towards the front. Whatever the visual cells missed on the first pass they get on the second – which improves twilight vision considerably. The rest leaves the eye again and is what you see as the glow.\n\nThe price is sharpness: the reflected light scatters a little and the image gets grainier. Humans do not have this layer, which is why our eyes appear red in flash photographs – there you simply see the blood-filled retina.','assets/quiz-illustrations/katzenauge.svg','Animals'),
(67,'en','What shape would a candle flame have in weightlessness?','It would be spherical','It would be flat and wide','It would look exactly as it does on earth','C','The pointed shape comes from gravity alone: hot gas is lighter, rises and draws cool air in below. Remove that buoyancy and oxygen can only diffuse in from all sides – the flame becomes a small sphere. This has been observed several times on the space station.\n\nIt also looks different: bluish rather than yellow, and noticeably cooler. Without a rising current it gets less oxygen and hardly any soot forms – and a candle flame on earth is only yellow because glowing particles of soot shine inside it.','assets/quiz-illustrations/kerze.svg','Physics'),
(68,'en','How does soap dissolve grease that water alone cannot shift?','It breaks the grease down chemically','Its molecules have a water-loving and a grease-loving end','It lowers the temperature at which grease melts','A','A soap molecule is a hybrid: a long grease-loving tail and a water-loving head. In water, many of them arrange themselves around a droplet of grease so that all the tails sit in the grease and all the heads point outwards. These little spheres are called micelles – from the outside they look water-friendly and simply rinse away.\n\nThe same construction makes soap effective against many viruses: they have a fatty envelope, and the soap tails drive right into it and tear it open. So thorough hand washing is more than merely rinsing things off.','assets/quiz-illustrations/seife.svg','Everyday life'),
(69,'en','Why does old paper turn yellow?','The size between the fibres decays','Constituents of wood are broken down by air and light','Paper takes up dust into its fibres over time','C','Cheap paper contains lignin, the substance that makes wood stiff. Lignin reacts with oxygen and light, and the breakdown products are yellowish-brown. On top of that comes acid from manufacturing, which slowly takes the cellulose fibres apart – the paper does not just go yellow but brittle as well.\n\nNewsprint yellows within days at a window, good book paper lasts decades. Archives therefore use acid-free, low-lignin paper. And books from the 16th century are often better preserved than ones from 1900: back then people worked from rags, not wood pulp.',NULL,'Everyday life'),
(70,'en','Why does ordinary window glass have a green tinge at the cut edge?','From a coating against heat radiation','From iron impurities in the sand','From a green dye that makes cracks visible','C','The quartz sand used for flat glass always contains traces of iron. Iron oxide absorbs mainly in the red range, and what remains is a slight green cast. Through a thin pane you hardly notice it, but along the edge you are looking through many centimetres of glass – and there the effect adds up visibly.\n\nWhere colour fidelity matters, low-iron sand is used: such white glass costs more and is found in display cases, picture frames and solar panels. Conversely, other metal additions produce strong colours – cobalt for blue, selenium for red.',NULL,'Physics'),
(71,'en','Why does your own voice sound so strange in a recording?','Microphones reproduce low tones more weakly','When speaking you also hear yourself through the bones of your skull','You always hear yourself with a delay','B','When you speak, the sound reaches your inner ear by two routes: through the air and directly through the bones of the jaw and skull. The bone route transmits low frequencies particularly well. So you hear yourself fuller and darker than you actually sound. The recording knows only the air route – and that is the honest version.\n\nIt is also why you still hear your own voice booming when you cover your ears. Singers and speakers therefore practise with recordings: only that way do they hear what the audience hears.','assets/quiz-illustrations/stimme.svg','Body'),
(72,'en','Why can you not tickle yourself?','The cerebellum announces your own touch in advance','Your own hand touches too evenly','The stimulus reaches the brain too slowly','C','With every movement of your own, the cerebellum sends a prediction to the sensory areas of the brain: careful, this touch is coming from us. Whatever matches the prediction is damped down. That is exactly why you are not startled by your own footstep and not bothered by the feel of your own clothes.\n\nResearchers have defeated the effect with a robot arm: build in a small delay between the movement of the hand and the touch, and suddenly it does tickle. And people with certain psychiatric conditions in which this prediction is disturbed can indeed tickle themselves.',NULL,'Body'),
(73,'en','Why do blood vessels under the skin look bluish, although blood is red?','Oxygen-poor blood in the veins really is blue','Skin lets red light pass differently from blue','The vessel walls themselves are bluish in colour','C','Oxygen-poor blood is not blue but dark red – you can see that when blood is taken. The blue only arises through the skin: red light penetrates deeply and is almost completely swallowed in the tissue, while blue is scattered back in the upper layers already. Over a dark vessel the blue share therefore wins.\n\nSo the effect depends on depth: very superficial vessels look reddish, deeper ones are barely visible, and at intermediate depth they appear blue. It is the same reason tattoo ink in deeper layers of skin takes on a bluish shimmer.',NULL,'Body'),
(74,'en','Why do some people sneeze when they step into bright light?','Light dries out the nasal mucosa','A nerve misroutes the stimulus','The movement of the pupil irritates the sinuses','B','The optic nerve and the facial nerves run close together, and in some people the strong light stimulus jumps across to the pathway that triggers the sneeze reflex. The brain interprets it as irritation in the nose. The reflex is inherited, affects 18 to 35 per cent of the population depending on the study, and is usually over after one to three sneezes.\n\nAristotle already described it, though he put it down to the warmth of the sun. For fighter pilots and ski jumpers it really is an issue – a sneeze on leaving a tunnel comes at the worst possible moment.',NULL,'Body'),
(75,'en','Why does hair go grey?','It deposits white keratin with age','The pigment cells in the root give up','Air penetrates into the shaft of the hair','B','The colour of a hair comes from melanocytes in the root, which add pigment to the growing hair. Their supply of stem cells is exhausted over the years; once no more pigment arrives, the hair grows back colourless. It looks white because light is scattered inside it. Grey is only the mixed impression of white and still-pigmented hairs.\n\nSo an individual hair does not turn grey – it grows in grey. Hydrogen peroxide, which accumulates in the root and bleaches pigment, is also considered an accelerator. That hair turns white overnight from fright, on the other hand, is physically impossible.',NULL,'Body'),
(76,'en','Why do men have nipples?','They are a leftover from the evolution of mammals','All embryos lay them down before hormones take effect','They serve a purpose in temperature regulation','B','In the first weeks all embryos develop along the same blueprint, and that includes laying down the mammary glands. Only afterwards do hormones steer further development in one direction. The structure already laid down is not dismantled – it simply stays undeveloped.\n\nThat it is functional tissue shows in the exceptions: under certain hormonal conditions breast tissue can grow in men too, and men can develop breast cancer. Around one per cent of all cases affect men – often recognised late, because nobody expects it.',NULL,'Body'),
(77,'en','Why does food taste bland on an aircraft?','It is kept warm for too long','Dry air, low pressure and noise dampen the sense of taste','The galley is not allowed to use salt','B','Three things come together. The cabin air is extremely dry, so the nasal mucosa takes up aromas less well – and taste is mostly smell. The reduced pressure dampens it further. And the constant noise of around 85 decibels measurably lowers the perception of sweet and salty. Roughly 30 per cent of sensitivity is lost.\n\nOne taste is largely spared and is even enhanced by the noise: umami. That is exactly why tomato juice is so popular on board although hardly anyone orders it on the ground – and why airline kitchens season far more strongly than would taste right at sea level.',NULL,'Food & Drink'),
(78,'en','Why does an empty room echo so strongly?','Because furniture and textiles would otherwise absorb the sound','Because air vibrates better without furniture','Because the sound is refracted at more corners','B','Sound is reflected almost completely by hard, smooth surfaces and runs back and forth in the room until the energy is used up. Soft and porous things – sofa, carpet, curtain, bookshelf, people too – absorb it instead and turn it into a little heat. Without them, the decay takes noticeably longer.\n\nThat decay time is the central quantity of room acoustics: in a living room it is about half a second, in an empty new building often over two, in a large church six or more. And because an audience absorbs strongly, a concert hall sounds different at rehearsal than at the performance.',NULL,'Everyday life'),
(79,'en','Why can you see the moon in broad daylight?','Because it is closer than any star','Because it is bright enough to hold its own against the blue sky','Because sunlight illuminates it additionally during the day','A','The moon is not a night-time object – it is simply in the sky whenever its orbit takes it there, and that is often during the day. It is visible because its surface reflects enough sunlight to be brighter than the scattered blue sky behind it. Stars cannot manage that; their light is lost in it.\n\nIt works best around the half-moon phases: then the moon stands about 90 degrees from the sun, that is high in the sky, while the sun is still shining. At full moon, by contrast, it rises roughly at sunset – during the day it is then below the horizon.',NULL,'Space'),
(80,'en','Why do almost all screws have a right-hand thread?','Because it suits right-handers when tightening','Because left-hand threads come loose more easily','Because the first thread-cutting machines could only work that way','A','When tightening with the right hand, turning clockwise is stronger and better controlled than the opposite direction – the forearm rotates inwards as it does so. Since most people are right-handed, this direction became the norm and was later simply written into standards.\n\nLeft-hand threads exist where the norm would be dangerous: on the left bicycle pedal, so that it does not unscrew itself in use, on some saw blade nuts, and on gas cylinders for flammable gases, so that you cannot screw on the wrong connection. So the exception is always a deliberate safeguard.',NULL,'History'),
(81,'en','What does »ok« originally mean?','It is the abbreviation of a place name','It was a joke using a deliberately wrong spelling','It comes from a Native American word for agreement','C','In 1839 a fashion was circulating in Boston newspapers for deliberately misspelling phrases and then abbreviating them. »Oll korrect« for »all correct« became o.k. Most of these joke abbreviations died within months – this one did not, because shortly afterwards it acquired a second meaning in a presidential campaign.\n\nMartin Van Buren came from Kinderhook and was called »Old Kinderhook«; his supporters founded O.K. clubs. The two together made the two letters immortal – today »ok« counts as the most widely spread word in the world.',NULL,'Language'),
(82,'en','Where does the word »panic« come from?','From a Greek god','From a Latin word for flight','From a medieval physician who described it','C','Pan was the Greek god of shepherds with goat\'s legs, responsible for woods and pastures. He was said to fall upon travellers and whole herds with a sudden fright – a groundless terror that ran through the crowd with no discernible cause. That panic fright became the word.\n\nMore goes back to him: the panpipes, which legend says he invented, and by a detour the Christian depiction of the devil with horns and goat\'s feet. The word »pandemic«, on the other hand, has nothing to do with him – that is Greek for »the whole people«.',NULL,'Language'),
(83,'en','Why does rain have such a characteristic smell?','Lightning produces ozone near the ground','Drops fling soil oils and bacterial spores into the air','Evaporating water carries the smell of dust with it','A','When a drop hits dry ground, it briefly traps air. That escapes as a swarm of tiny bubbles and carries substances up from the surface with it: plant oils that settle during dry spells, and the compound geosmin from soil bacteria. The process has been made visible with high-speed cameras.\n\nGeosmin is the main carrier of this earthy smell, and the human nose is extremely sensitive to it – a few parts per trillion are enough. The same substance makes beetroot taste earthy and is the reason a single drop of rainwater in drinking water is noticed at once. The name for the scent: petrichor.',NULL,'Nature'),
(84,'en','Why is snow white but ice transparent?','Snow contains trapped air that scatters the light','Snow crystals have a white colour of their own','Snow only reflects light from the surface','A','Snow is nothing but ice – it just consists of millions of tiny crystals with air in between. At every boundary between ice and air, light is deflected a little. After countless deflections it leaves the snow in all directions and in all colours equally: that is what we perceive as white.\n\nThe same principle makes candyfloss, foam and clouds white although their components are clear. And where snow is deep and tightly pressed you see the next effect: in glaciers, red light is absorbed after a long path after all – which is why glacier ice glows blue.',NULL,'Nature'),
(85,'en','Why does water stay in a bucket that you swing in a circle?','A force presses it outwards against the bottom','The bottom of the bucket keeps forcing it onto the circular path','The airflow keeps it in the bucket','B','By inertia the water wants to keep flying straight on. The bottom of the bucket is constantly in its way and redirects it inwards – that inward force is what holds it on the circular path. At the highest point gravity takes over part of it, and the bottom still supplies the rest. Swing too slowly and gravity alone is not enough as the turning force, and the water falls out.\n\nThe often-cited centrifugal force »outwards« exists only as an aid to calculation for an observer who turns along with it. Seen from outside, no outward force is acting – there is merely too little acting inwards.',NULL,'Physics'),
(86,'en','Why do aircraft wings often have upturned ends?','To save space during ground manoeuvres','To slow the vortex at the wingtip','To give the wing more strength','A','At the wingtip the overpressure from below meets the underpressure above and rolls up into a strong vortex. That vortex costs energy without producing lift. An upturned end – a winglet or a curved tip – makes this flow around harder and weakens the vortex. Depending on the design that brings several per cent in fuel savings.\n\nThe vortices are more than a detail: they are the reason for the prescribed spacing between departing aircraft, because a wake vortex can flip a smaller aircraft following a large one. Migrating birds exploit the same effect in formation flight – the follower flies in the updraught of the bird ahead.',NULL,'Technology'),
(87,'en','Why is it cold in space, although the sun shines there unfiltered?','Because with almost no matter, hardly any heat can be transferred','Because solar radiation almost dies away with distance','Because temperature in a vacuum is fundamentally zero','A','Temperature is the movement of particles – where there are almost none, there is hardly anything to warm. On earth, air and water pass heat on by contact and flow; in a vacuum both fall away and only radiation remains. An object in the sun therefore gets very hot, one in the shade very cold, and hundreds of degrees lie between the two sides.\n\nSo cooling is the real problem in space, not heating: the space station carries large radiators to get rid of waste heat. And space suits are not thick against the cold but insulate in both directions and have a cooling system of their own against body heat.',NULL,'Space'),
(88,'en','Why is there a coloured rectangle at the top of a toothpaste tube?','It encodes the ingredients','It is a marker for the cutting machine','It indicates the origin of the raw materials','A','The coloured squares are register marks for the packaging machine. A light sensor detects the block of colour against the bright background and thereby knows exactly where the endless strip of tubing has to be cut and sealed. The colour itself is arbitrary – it only has to provide enough contrast.\n\nAccordingly, the widespread tale that green stands for purely natural and black for purely chemical ingredients is invented. The same marks appear on crisp packets, coffee packaging and sausage film, where nobody suspects a secret message.',NULL,'Everyday life'),
(89,'en','Why does a phone battery run flat so quickly outdoors in winter?','The display needs more power in the cold','The chemical processes in the battery run more slowly','The battery really does lose charge in the cold','A','In a lithium-ion battery, ions have to migrate through an electrolyte. In the cold that becomes more viscous and the migration slower, so internal resistance rises. The battery can no longer deliver the power demanded, the voltage collapses under load, and the electronics read that as »empty« and shut down. The energy is not lost – back in the warmth the device often shows charge again.\n\nThe consequence for charging matters: a battery below zero degrees should not be charged, because metallic lithium can then be deposited, which damages it permanently. Good devices therefore refuse to charge in the cold of their own accord.',NULL,'Technology'),
(90,'en','Why are railway tracks in many countries exactly 1,435 millimetres apart?','The figure came out of calculations on stability in curves','It took over the gauge of English coal railways','It matches the axle width of a Roman chariot','C','George Stephenson built his locomotives for coal railways in the north-east of England, whose gauge had grown out of local waggon building. When his machines caught on, their measurement came along and was later written down as standard gauge – a good 1,435 millimetres, that is four feet eight and a half inches.\n\nThe popular tale that the figure goes back to the axle width of Roman chariots is a legend without evidence. That various countries deliberately chose different gauges often had military reasons: a differing gauge slows an attacker down, because he cannot simply keep his trains rolling.',NULL,'History'),
(1,'hr','Zašto ementaler ima rupe?','Probijaju se iglama pri oblikovanju','Bakterije u siru proizvode ugljikov dioksid','Pri zrenju tekućina isparava iz šupljina','B','Odgovorne su propionske bakterije. Tijekom zrenja razgrađuju mliječnu kiselinu i pri tome otpuštaju ugljikov dioksid. Plin ne može izaći iz čvrstoga kolača pa se skuplja na sitnim začetnim mjestima – i iz njih nastaju okrugle rupe, u struci zvane »oči«.\n\nZanimljivo je što se dogodi kad se radi previše čisto: nekada su kao začetna mjesta služile male čestice sijena u mlijeku. Otkako moderni sustavi za strojnu mužnju daju gotovo posve čisto mlijeko, rupe su mjerljivo manje. Neke sirane zato danas namjerno ponovno dodaju prah sijena.','assets/quiz-illustrations/emmentaler.svg','Hrana i piće'),
(2,'hr','Zašto su banane zakrivljene?','Plod raste prema gore, protiv sile teže','Težina grozda povija ih prema dolje','Kora se s jedne strane suši i steže','A','Cvjetna stabljika banane najprije visi prema dolje. Mladi plodovi zatim rastu natrag prema gore, protiv sile teže i prema svjetlu – botaničari to nazivaju negativnim gravitropizmom. Budući da počinju nisko a završavaju visoko, nastaje luk.\n\nZakrivljenost dakle nije rezultat oplemenjivanja, nego obična reakcija rasta. Divlje banane jednako su zakrivljene – samo su pune tvrdih sjemenki i gotovo nejestive.',NULL,'Priroda'),
(3,'hr','Zašto čili peče u ustima, iako ništa nije vruće?','Ljuta tvar blago nagriza sluznicu','Draži upravo one živce koji javljaju toplinu','Nakratko podiže temperaturu u ustima','C','Ljuta tvar kapsaicin veže se na receptor zvan TRPV1. On je zapravo detektor topline i obično se pokreće od približno 43 stupnja. Kapsaicin ga otvara kemijskim putem – mozak tako dobiva pravu dojavu o toplini, a da nigdje nema topline.\n\nZato voda gotovo ne pomaže: kapsaicin je topljiv u mastima. Mlijeko, jogurt ili vrhnje uspješno ga vežu. A budući da ptice taj receptor imaju drukčije građen, njima čili nije nimalo ljut – što je za biljku praktično, jer ptice raznose sjemenke neoštećene.','assets/quiz-illustrations/chili.svg','Tijelo'),
(4,'hr','Zašto pri rezanju luka moramo plakati?','Plin na oku stvara kiselinu','Sok luka mehanički draži rožnicu','Jak miris pokreće refleks u mozgu','C','Kad se luk ošteti, sastanu se dvije tvari koje su prije bile odvojene u stanici. Enzim iz njih gradi hlapljiv sumporni spoj. On se diže i na vlažnoj površini oka reagira u slabu kiselinu. Oko to ispire suzama.\n\nTo objašnjava i zašto kućni trikovi rade: ohlađeni luk otpušta manje plina, oštar nož uništava manje stanica, a onaj koji radi blizu nape dobiva manje toga u oči.',NULL,'Hrana i piće'),
(5,'hr','Zašto loptica za golf ima udubljenja?','Poboljšavaju prihvat pri udarcu','Loptica se tako bolje vidi u travi','Znatno smanjuju otpor zraka','A','Kod glatke loptice strujanje zraka otkida se rano i za sobom vuče široko područje podtiska. Udubljenja stvaraju tanak, uzvitlan sloj neposredno na površini koji dulje prati oblik. Područje podtiska se smanjuje, otpor pada – a rotacija natrag dodatno stvara uzgon.\n\nUčinak je ogroman: glatka loptica leti samo približno upola manje daleko. Otkriven je posve slučajno, jer su igrači u 19. stoljeću primijetili da njihove stare, izgrebane loptice lete bolje od novih.','assets/quiz-illustrations/golfball.svg','Tehnika'),
(6,'hr','Zašto su teniske loptice žute?','Žuta na zemljanoj podlozi najdulje ostaje čista','Zbog vidljivosti na televiziji u boji','Bojilo čini filc izdržljivijim','A','Do sedamdesetih godina teniske loptice bile su bijele. S televizijom u boji to je postalo problem: pred svjetlim linijama i bijelom odjećom lopticu se na ekranu teško pratilo. Istraživanja su pokazala da se najjasnije vidi jarka žutozelena. Svjetska federacija dopustila ju je 1972.\n\nWimbledon je ipak do 1986. ostao pri bijeloj loptici – tradicija. Službeni naziv boje je »optic yellow«, a je li loptica žuta ili zelena, gledatelji se spore do danas.',NULL,'Povijest'),
(7,'hr','Zašto se pri polijetanju i slijetanju svjetlo u kabini prigušuje?','Da se uštedi struja za motore','Da oči budu prilagođene mraku','Da piloti imaju manje odsjaja u pilotskoj kabini','A','Polijetanje i slijetanje kritične su faze. Kad bi trebalo evakuirati u mraku, očima koje su se upravo naviknule na jako svjetlo kabine trebalo bi nekoliko minuta da vani bilo što razaznaju. Uz prigušeno svjetlo već su unaprijed prilagođene.\n\nIz istog razloga zasloni na prozorima moraju ostati otvoreni: posada iznutra mora vidjeti ima li s jedne strane vatre ili krhotina prije nego što otvori vrata. A rasvjeta za slučaj nužde ide po podu, jer je tamo dolje vidljiva i u dimu.',NULL,'Tehnika'),
(8,'hr','Zašto svaki prozor u zrakoplovu ima malu rupicu na dnu?','Da se staklo iznutra ne rosi','Služi kao odvod za kondenzat','Osigurava da vanjsko staklo nosi pritisak','B','Prozor kabine sastoji se od nekoliko akrilnih stakala. Sitna rupica u srednjem staklu povezuje međuprostor s kabinom. Zbog toga cijela razlika pritiska prema razrijeđenom vanjskom zraku leži na vanjskom staklu, koje je za to i građeno. Srednje je rezerva, u slučaju da vanjsko popusti.\n\nKao nusučinak, vlaga izlazi iz međuprostora pa se stakla iznutra ne zaleđuju. Riješiti oboje odjednom dobro je inženjerstvo s jednom izvrtanom rupicom.','assets/quiz-illustrations/flugzeugfenster.svg','Tehnika'),
(9,'hr','Zašto je more slano?','Rijeke u njega nose otopljenu stijenu','Podmorska ležišta soli polako se otapaju','Morski organizmi neprestano otpuštaju soli','A','Kiša je blago kisela i pri otjecanju otapa minerale iz stijena. Rijeke te soli prenose u more. Voda odande ponovno isparava – soli ostaju. Kroz milijune godina tako se ustalio sadržaj od približno 35 grama na litru. Podmorski vulkanski izvori daju drugi doprinos.\n\nZašto onda ne postaje sve slanije? Jer soli i nestaju: ugrađuju se u sedimente, odlažu u odsječenim morskim bazenima i s tektonskim pločama odvlače u dubinu. Dotok i odvod približno se izjednačuju.',NULL,'Priroda'),
(10,'hr','Što pucne kad krcnemo prstima?','Tetive preskoče preko koštanog izdanka','Mjehurić plina u zglobnoj tekućini','Hrskavične površine nakratko se otaru jedna o drugu','A','Kad zglob razvučemo, pukotina se širi brže nego što tekućina može doteći. Pritisak pada i otopljeni plinovi naglo stvaraju mjehurić. Upravo nastajanje toga mjehurića proizvodi zvuk – snimke magnetskom rezonancijom to su u međuvremenu i zabilježile.\n\nZato ne ide odmah još jednom: plin se prvo mora ponovno otopiti, a to traje oko 20 minuta. I raširena opomena ne stoji baš tako – istraživanja među onima koji to redovito rade nisu našla povećanu stopu artroze, najviše nešto slabiji stisak.',NULL,'Tijelo'),
(11,'hr','Koliko srca ima hobotnica?','Jedno, ali s četiri komore','Dva, po jedno za svaku polovicu tijela','Tri','A','Dva škržna srca svako protiskuje krv kroz jednu škrgu, a veće glavno srce zatim je šalje kroz tijelo. To je potrebno jer prenositelj kisika u krvi hobotnice, hemocijanin s bakrom, radi znatno neučinkovitije od našega hemoglobina sa željezom. Krv, uzgred, čini plavičastom.\n\nGlavno srce zastaje dok hobotnica pliva – jedan od razloga zašto radije hoda po dnu nego pliva. Plivanje ju jednostavno brže iscrpljuje.',NULL,'Životinje'),
(12,'hr','Zašto se pingvini ne zalede stopalima za led?','Potplati su im izolirani slojem masti','Dotječuća i otječuća krv izmjenjuju toplinu','Stopala trajno drže malo podignuta','A','U nogama arterije i vene leže tijesno jedna do druge i teku u suprotnim smjerovima. Topla krv iz tijela svoju toplinu predaje neposredno hladnoj krvi koja se vraća. Dolje dolazi još samo malo iznad ništice – dovoljno toplo da se ne zaledi, i dovoljno hladno da se gotovo ništa topline ne izgubi.\n\nTo protustrujno načelo koriste i patke na ledu, kitovi u perajama i sobovi u nogama. Pingvin uz to može regulirati protok krvi – toplih dana kroz stopala otpušta više topline.','assets/quiz-illustrations/pinguin.svg','Životinje'),
(13,'hr','Koje je boje koža polarnog medvjeda?','Crna','Ružičasta kao kod drugih medvjeda','Svjetlosiva s bijelim mrljama','C','Pod krznom je koža polarnog medvjeda crna – dobro se vidi na nosu i usnama. Tamna koža bolje prima toplinu. Same dlake nisu bijele, nego bezbojne i propuštaju svjetlo. Izgledaju bijelo jer se svjetlo u njima rasipa, kao u snijegu ili šećernoj vuni.\n\nZato polarni medvjedi u zoološkim vrtovima mogu postati zelenkasti: nasele li se alge u šuplje dlake, krzno dobiva zeleni odsjaj. Rašireno mišljenje da dlake sunčevo svjetlo vode do kože kao svjetlovodi danas se smatra opovrgnutim.',NULL,'Životinje'),
(14,'hr','Zašto je nebo plavo?','Odražava boju oceana','Molekule zraka najjače rasipaju plavo svjetlo','Vodena para izdvaja crveno svjetlo','B','Sunčevo svjetlo sadrži sve boje. Molekule zraka svjetlo kratkih valnih dužina rasipaju u svim smjerovima daleko jače od onoga dugih – ta se veza naziva Rayleighovim rasipanjem. Plavo nam zato dolazi s cijeloga neba, a ne samo neposredno od Sunca.\n\nLjubičasto bi se rasipalo još jače, ali ga Sunce manje izlučuje a naše su oči na njega manje osjetljive. A navečer? Tada svjetlo ukoso prolazi kroz mnogo više zraka, plavo je putem već rasuto – ostaju narančasto i crveno.','assets/quiz-illustrations/himmelblau.svg','Priroda'),
(15,'hr','Zašto led pluta na vodi?','Nose ga zatvoreni mjehurići zraka','Površinska napetost drži ga na vrhu','Voda pri skrutnjavanju postaje lakša','A','Gotovo sve tvari pri skrutnjavanju postaju gušće. Voda ne: u ledu se molekule uređuju u široku rešetku sa šupljinama. Led zato zauzima približno devet posto više prostora od iste količine tekuće vode – pa pluta. Voda je najgušća pri oko četiri stupnja.\n\nTa je anomalija gustoće jedan od razloga zašto život u jezerima preživi zimu: ledeni se pokrov stvara na površini i izolira, a ispod ostaje tekuće na četiri stupnja. Kad bi led tonuo, jezera bi se ledila od dna.','assets/quiz-illustrations/eis.svg','Fizika'),
(16,'hr','Zašto su poklopci šahtova okrugli?','Jer okrugli poklopac ne može upasti u šaht','Jer su cijevi okrugle pa poklopac odgovara','Jer se okrugli poklopci lakše liju','B','Krug u svakom smjeru ima isti promjer. Okrugli se poklopac zato ne može okrenuti tako da propadne kroz vlastiti otvor – kod četvrtastoga dovoljno ga je postaviti dijagonalno. Za radnike ispod ulice to je vrlo konkretan sigurnosni argument.\n\nNa to se nadovezuje i praktično: okrugli poklopac pri vraćanju ne treba usmjeravati, može se kotrljati umjesto nositi, a okrugli oblik težinu kamiona koji prelaze ravnomjerno prenosi u obod – kutovi bi bili slabe točke.','assets/quiz-illustrations/kanaldeckel.svg','Svakodnevica'),
(17,'hr','Odakle dolazi ime bežične tehnike Bluetooth?','Od plavog dijela u prvom prototipu','Od danskoga kralja','Od kodnog imena za plave kabele u Ericssonu','B','Kum je Harald Plavozubi, koji je u 10. stoljeću ujedinio danska plemenska područja i pridružio Norvešku. Inženjer je ime predložio kao radni naslov: kako je kralj ujedinio plemena, tako je tehnika trebala ujediniti različite uređaje. Radni je naslov ostao jer se marketing nije mogao dogovoriti o nečem drugom.\n\nČak i logotip odgovara: spaja starnordijske rune za H i B – kraljeve inicijale. Odakle nadimak Plavozubi, nije jasno; možda od tamnoga, mrtvog zuba.',NULL,'Jezik'),
(18,'hr','Zašto traperice imaju male metalne zakovice na džepovima?','Znak su prave markirane robe','Pojačavaju mjesta na kojima tkanina puca','Odvode statički naboj','B','Krojač Jacob Davis krpao je radne hlače za tragatelje za zlatom i smetalo ga je što se uglovi džepova uvijek raspadaju. Jednostavno je ugradio zakovice iz radionice za konjsku opremu. Kako mu je nedostajalo novca za patent, 1873. povezao se sa svojim dobavljačem tkanine Levijem Straussom – i iz te je zakovice nastala moderna traperica.\n\nJedna je zakovica kasnije ponovno nestala: ona u koraku. Uz logorsku vatru postajala je neprijatno vruća. A mali peti džep sprijeda nekoć je bio džep za džepni sat.',NULL,'Svakodnevica'),
(19,'hr','Zašto s Mjeseca uvijek vidimo istu stranu?','Uopće se ne vrti','Jedan mu okret traje jednako dugo kao jedan obilazak','Zemlja svojom sjenom zakriva drugu stranu','A','Mjesec se svakako vrti – samo mu za to treba jednako dugo kao za jedan krug oko Zemlje, oko 27 dana. Zato nam uvijek pokazuje isto lice. Ta vezana rotacija nije slučajna: plimne sile Zemlje kroz milijune godina kočile su njegovo vrtnju dok se nije uklopila.\n\nPrizor nije posve nepomičan. Budući da je Mjesečeva staza blago eliptična i nagnuta, on se malo koleba naprijed-natrag. S vremenom zato sa Zemlje postaje vidljivo oko 59 posto njegove površine.','assets/quiz-illustrations/mond.svg','Svemir'),
(20,'hr','Zašto postoje godišnja doba?','Jer je Zemljina os nagnuta','Jer se udaljenost od Sunca mijenja','Jer Sunce zrači različito jako','A','Zemljina os nagnuta je za dobrih 23 stupnja. Zbog toga sunčevo svjetlo sjevernu polutku u lipnju pogađa okomitije i dulje, a u prosincu položenije i kraće – na južnoj polutki upravo obrnuto. Okomitije znači: ista se energija raspoređuje na manju površinu.\n\nUdaljenost to već zato ne može biti jer bi tada svugdje istodobno bilo ljeto. Zemlja je zapravo početkom siječnja najbliža Suncu – u sredini europske zime.','assets/quiz-illustrations/jahreszeiten.svg','Svemir'),
(21,'hr','Zašto zvijezde trepere, a planeti gotovo ne?','Planeti ne svijetle sami, nego samo odbijaju svjetlo','Zvijezde zaista neprestano mijenjaju svoju svjetlinu','Planeti se prikazuju kao pločica, zvijezde kao točka','C','Treperenje ne nastaje na zvijezdi, nego u našoj atmosferi: slojevi zraka različite temperature svjetlo različito lome i odbijaju ga tu i tamo. Zvijezda je i u teleskopu samo svjetlosna točka – kad se ona otkloni, odmah se vidi.\n\nPlanet je pak toliko blizu da tvori sitnu pločicu, dakle mnogo točaka jednu do druge. Njihova kolebanja se izjednačuju i svjetlo ostaje mirno. Praktičan trik pod noćnim nebom: što stoji mirno, obično je planet.',NULL,'Fizika'),
(22,'hr','Zašto med praktički nikada ne pokvari?','Pčele dodaju prirodno sredstvo za konzerviranje','U njemu je previše malo slobodne vode da bi klice rasle','Visok sadržaj šećera kemijski ubija klice','B','Zreo med sadrži samo oko 17 posto vode, a šećer je čvrsto veže. Mikroorganizmima treba slobodna voda – u medu im okolina umjesto toga izvlači tekućinu. Med je uz to kiselkast i sadrži male količine vodikova peroksida, koji pčele unose preko enzima.\n\nU egipatskim grobnicama nađen je med koji se nakon tisućljeća još nije pokvario. Razrijedi li ga se, zaštita otpada i on počinje vreti – a upravo se to koristi pri izradi medovine.',NULL,'Hrana i piće'),
(23,'hr','Zašto kola tako silovito prska kad se u nju ubaci Mentos?','Bomboni kemijski reagiraju s kiselinom','Njihova gruba površina nudi nebrojene začetke mjehurića','Naglo se otapaju i istiskuju tekućinu','B','Gazirana su pića prezasićena plinom. Da bi se mjehurić stvorio, treba mu polazišna točka. Površina Mentosa pod mikroskopom je puna pora i rubova – tisuće polazišnih točaka odjednom. Plin izlazi u nekoliko sekundi i tekućinu potiskuje uvis kao vodoskok.\n\nKemijska reakcija to nije. Dodaci u bombonima uz to snižavaju površinsku napetost, što stvaranje mjehurića dodatno olakšava. S light kolom vodoskok je viši, jer je bez šećernog sirupa rjeđa.',NULL,'Hrana i piće'),
(24,'hr','Zašto se koža na prstima u vodi naboraju?','Koža se napije vodom i rasteže','Živčani sustav aktivno steže krvne žile','Kožna mast se ispire i koža upada','C','Očekivalo bi se puko upijanje – zapravo je to upravljana reakcija. Autonomni živčani sustav steže krvne žile pod kožom, volumen ispod se smanjuje, a čvrsti rožnati sloj nabire se. Dokaz: ako je zadužni živac oštećen, prsti se više ne naboraju.\n\nZašto tijelo to čini, nije konačno razjašnjeno. Pokusi upućuju na to da žljebovi omogućuju bolje hvatanje mokrih predmeta – slično kao što profil gume odvodi vodu.',NULL,'Tijelo'),
(25,'hr','Zašto ptice na električnom vodu ne dobiju udar?','Njihove su kandže od izolacijskog materijala','Perje ne vodi struju dalje','Između njihovih stopala gotovo nema napona','C','Struja teče samo kad postoji razlika napona. Oba stopala ptice sjede na istoj žici, nekoliko centimetara jedno od drugoga – između njih gotovo nema napona, pa kroz pticu praktički ne teče struja. Ugodniji put ostaje bakar.\n\nOpasno postaje u trenutku kad ptica dodirne i nešto drugo: drugu žicu, stup ili uzemljeni dio. Upravo su zato velike vrste ptica velikog raspona krila na stupovima visokoga napona posebno ugrožene.','assets/quiz-illustrations/vogel-leitung.svg','Životinje'),
(26,'hr','Odakle dolazi izraz »pasti s kruške«?','Iz slike čovjeka koji se iznenada nađe na zemlji, bez pojma gdje je','Od stare kazne za krađu voća','Od mjere za visinu koju su koristili vrtlari','A','Izraz opisuje nekoga tko govori ili se ponaša kao da ništa ne zna o stvari o kojoj je riječ – kao da je upravo pao s drveta i našao se posve izgubljen. Slika je jednostavna i zato razumljiva bez ikakva objašnjenja: onaj koji padne s kruške u trenutku ne zna ni gdje je ni kako je tamo došao.\n\nSlične slike postoje u mnogim jezicima. Njemački kaže da je nekoga »s Mjeseca«, engleski da je pao »off the back of a lorry« kad je riječ o stvarima sumnjiva podrijetla. Zajedničko im je da naglo i nepripremljeno pojavljivanje znači neznanje.',NULL,'Jezik'),
(27,'hr','Što izvorno znači želja »Hals- und Beinbruch«, njemački pandan izrazu »slomi nogu«?','Opomenu pred opasnim radom','Blagoslov iz jidiša','Zdravicu rudara','C','U pozadini je vrlo vjerojatno jidiška formula »hatslokhe un brokhe« – sreća i blagoslov. Njemačke su uši iz toga glasovno čule »Hals und Bruch«, a kako to nije imalo smisla, narodni je govor iz toga napravio potpunu želju za nesrećom.\n\nTo se dobro uklopilo u raširenu praznovjericu: onaj koji otvoreno želi sreću, priziva suprotno – pa se radije želi nešto zlo. U engleskom se čini upravo isto s »break a leg«, a u hrvatskom se kaže »slomi nogu«.',NULL,'Jezik'),
(28,'hr','Zašto je natpis sprijeda na vozilu hitne pomoći zrcalno napisan?','Da se u retrovizoru ispravno čita','Jer se folija tako lakše lijepi s unutrašnje strane','To je međunarodni propis za vozila s rotacijskim svjetlom','B','Natpis na prednjoj strani namijenjen je vozaču automobila koji vozi ispred. On vozilo vidi u retrovizoru – a tamo se svaki tekst prikazuje obrnuto. Ako se od početka postavi zrcalno, u zrcalu ga čita ispravno i može brže reagirati.\n\nZato zrcalni natpis stoji uvijek samo sprijeda, nikada na stranama ili straga: samo prednja strana ikada dospije u tuđi retrovizor.',NULL,'Svakodnevica'),
(29,'hr','Zašto udar munje ne ugrožava putnike u zrakoplovu?','Gumene gume izoliraju zrakoplov','Metalna ovojnica vodi struju s vanjske strane','Visina munju toliko oslabi','C','Vodljiva vanjska ovojnica djeluje kao Faradayev kavez: struja teče preko površine i zrakoplov napušta na jednom odvodnom šiljku, a unutrašnjost ostaje praktički bez polja. Statistički, prometne zrakoplove munja pogodi približno jednom godišnje, a putnici obično osjete samo prasak i bljesak.\n\nZahtjevno je to kod modernih dijelova trupa od ugljičnih vlakana, koja slabije vode. Tamo se ulaminiraju fine metalne mrežice ili bakrene folije da kavez i dalje djeluje. Uz to na rubovima krila i repnih površina sjede mali odvodni šiljci.','assets/quiz-illustrations/blitz-flugzeug.svg','Fizika'),
(30,'hr','Zašto su flamingosi ružičasti?','Perje sadrži vlastito crveno bojilo','Boja dolazi iz njihove hrane','Građa perja lomi svjetlo u ružičasto','A','Flamingosi iz vode filtriraju male rakove i alge. U njima su karotenoidi – ista skupina tvari koja mrkvu čini narančastom. Ptica ih ugrađuje u kožu i perje. Bez te hrane ostaje blijedo bijela, što se u zoološkim vrtovima nekada redovito viđalo, prije nego što je hrana prilagođena.\n\nBoja je i signal: snažno ružičasta pokazuje da se životinja dobro hrani i da je zdrava – i pri odabiru partnera djeluje odgovarajuće privlačno. Roditelji koji gnijezde pak blijede, jer bojila predaju svojim mladima.',NULL,'Priroda'),
(31,'hr','Zašto mokraća nakon jela šparoga ima poseban miris?','Šparoge same sadrže jako mirisna ulja','Tijelo šparogovu kiselinu razgrađuje u sumporne spojeve','Šparoge izbacuju vodu pa mokraća postaje koncentriranija','A','Šparoge sadrže šparogovu kiselinu, koja se u tom obliku gotovo ne javlja u nijednoj drugoj hrani. Probava je razlaže u male, vrlo hlapljive sumporne spojeve. Budući da su toliko hlapljivi, osjete se već nakon petnaest minuta.\n\nZanimljivo je da miris ne osjeti svatko. Rasprostranjena genska varijanta u osjetu mirisa čini znatan dio ljudi slijepima za njega. Zato se dugo mislilo da miris uopće proizvode samo neki – zapravo ga proizvode gotovo svi.',NULL,'Tijelo'),
(32,'hr','Zašto sok od naranče neposredno nakon pranja zuba ima odvratan okus?','Pasta reagira s kiselinom iz voća','Sredstvo za pjenjenje blokira osjet slatkoga','Mentol posve obamre jezik','C','Krivac je obično natrijev laurilsulfat, tvar koja pastu čini pjenušavom. Ona priguši receptore za slatko i istodobno napada molekule masti koje inače ublažavaju osjet gorčine. Rezultat: slatkoća soka izostaje, kiselina i gorke tvari ostaju – i odjednom imaju nepodnošljiv okus.\n\nPasta bez toga sredstva za pjenjenje gotovo ne izaziva taj učinak. A onaj koji ne želi čekati može doručak jednostavno obaviti prije pranja zuba.',NULL,'Tijelo'),
(33,'hr','Zašto kečap najprije ne izlazi, a onda navali sav odjednom?','Tresenjem postaje rjeđi','Uzak otvor ga najprije zaustavlja','Zrak najprije mora doteći u bocu','C','Kečap pripada nenewtonskim tekućinama. U mirovanju čestice rajčice tvore rahlu mrežu koja ga drži zajedno gotovo kao čvrsto tijelo. Djeluje li dovoljna sila – tresenje, udaranje, pritisak – ta se mreža ruši i žilavost u nekoliko sekundi dramatično padne. Tada sve poteče odjednom.\n\nTo se ponašanje naziva tiksotropijom i namjerno se koristi: boja za stijene treba biti rijetka pod kistom i ne kapati sa stijene, pasta za zube treba stajati u tubi i izlaziti pod pritiskom.','assets/quiz-illustrations/ketchup.svg','Fizika'),
(34,'hr','Zašto nerđajući čelik ne rđa, iako se sastoji uglavnom od željeza?','Prekriven je naknadno nanesenim zaštitnim slojem','Krom u njemu sam tvori tanašnu zapornu opnu','Legiranje čini željezo kemijski nedodirljivim','C','Od približno dvanaest posto kroma dogodi se nešto elegantno: krom na površini odmah reagira s kisikom u gust oksidni sloj debeo samo nekoliko atomskih slojeva. On čvrsto stoji, nevidljiv je i kisiku više ne dopušta da dođe do željeza pod njim. A rđi je potreban upravo taj pristup.\n\nNajbolje je samoizlječenje: izgrebe li se sloj, ponovno se stvori u nekoliko sekundi. Samo kad kisika trajno nema – primjerice pod tvrdokornom naslagom – ili kad ga klorid mjestimično probije, i nerđajući čelik može korodirati.','assets/quiz-illustrations/edelstahl.svg','Tehnika'),
(35,'hr','Zašto su slova na tipkovnici tako nepraktično razmještena?','Razmještaj slijedi učestalost slova u engleskom','Trebao je spriječiti zapinjanje poluga pisaćeg stroja','Potječe od razmještaja u telegrafskoj abecedi','C','U mehaničkim pisaćim strojevima poluge s tipovima udarale su o papir odozdo. Ako su dva slova koja često slijede jedno drugo stajala jedno do drugoga, poluge su pri brzom udaranju zapinjale. Christopher Latham Sholes zato je sedamdesetih godina 19. stoljeća česte parove slova prostorno razdvojio. Rezultat je red QWERTY, koji njemačke tipkovnice koriste sa zamijenjenim Z i Y.\n\nS računalima je razlog otpao, no razmještaj je ostao: milioni su ga ljudi naučili. Dokazano brži razmještaji kao Dvorak ili Neo nikada se nisu probili.','assets/quiz-illustrations/qwertz.svg','Tehnika'),
(36,'hr','Zašto se u Velikoj Britaniji vozi lijevom stranom?','Zbog upravljača u prvim tamo građenim automobilima','Da jahači imaju ruku s mačem prema onima koji dolaze','Jer je željeznica išla lijevo pa su ceste slijedile','C','Uobičajeno objašnjenje seže daleko prije automobila. Onaj koji je putovao na konju i nosio mač, nosio ga je desno. Jahanjem lijevo ruka s oružjem ostala je okrenuta onome koji dolazi, a desna je bila slobodna za pozdrav ili hvat bez mijenjanja uzda. Papa Bonifacije VIII. navodno je 1300. hodočasnicima savjetovao da idu lijevo.\n\nDa velik dio svijeta danas vozi desno, mnogo ima s Francuskom i Sjedinjenim Državama: širokim se zapregama s više vučnih konja upravljalo s lijevoga zadnjeg konja – kočijaš je one koji dolaze htio imati lijevo od sebe pa se držao desno.',NULL,'Povijest'),
(37,'hr','Zašto tjedan ima sedam dana?','Zbog sedam golim okom vidljivih lutajućih zvijezda','Jer se lunarni mjesec lijepo dijeli na četiri dijela','Jer sedmica u Babilonu vrijedi kao božanski broj','B','Babilonski su astronomi poznavali sedam nebeskih tijela koja se kreću pred zvjezdanom pozadinom: Sunce, Mjesec, Merkur, Veneru, Mars, Jupiter i Saturn. Svakom je pripisan jedan dan. Preko Grka i Rimljana sedmodnevni je tjedan došao u Europu – dakle, drukčije od mjeseca i godine, nema astronomski takt koji bi morao slijediti.\n\nImena podrijetlo odaju do danas. U engleskom su Saturday, Sunday i Monday neposredno Saturn, Sunce i Mjesec. U hrvatskom se pak vidi drugi red: ponedjeljak je dan po nedjelji, a srijeda i četvrtak imenovani su prema mjestu u tjednu.',NULL,'Povijest'),
(38,'hr','Zašto njemačka riječ za srijedu, drukčije od ostalih dana, nije imenovana po bogu?','Jer je u antici vrijedila kao dan odmora bez božanstva','Jer je Crkva potisnula ime boga Wodana','Jer je tjednu pridodan tek u srednjem vijeku','B','Izvorno je to bio dan boga Wodana – u engleskom je još Wednesday, u nizozemskom woensdag. U njemačkom je govornom prostoru Crkva u ranom srednjem vijeku provela suhi brojevni oblik: Mittwoch, dan u sredini tjedna.\n\nKod subote je to dijelom također uspjelo. Sjever Njemačke kaže Sonnabend, predvečerje nedjelje, jug Samstag – što zaobilaznim putem dolazi od hebrejskoga šabata. Samo su utorak, četvrtak i petak u njemačkom zadržali stara božanska imena. Hrvatski je pak sve dane imenovao po redu u tjednu.',NULL,'Jezik'),
(39,'hr','Zašto čepovi za pjenušac imaju oblik gljive?','Tako se stiskaju da bi se bolje mogli uhvatiti','Valjkasti su i oblikuju se tek u boci','Glava gljive raspoređuje pritisak žičane košarice','B','Prije zatvaranja čep za pjenušac debeo je valjak, znatno širi od grla boce. Pri zatvaranju se snažno stisne. Donji dio ostaje zarobljen u grlu i zadržava stisnuti oblik, a gornji se izvan boce ponovno opruži – i iz toga nastaje glava gljive.\n\nPo obliku se čak može pročitati starost: što je boca dulje ležala, kora je manje elastična i izvučeni čep ostaje uži. Gotovo valjkast čep upućuje na dugo odležali pjenušac.','assets/quiz-illustrations/sektkorken.svg','Hrana i piće'),
(40,'hr','Zašto vinske čaše imaju dugu nožicu?','Da ruka ne grije vino','Da čaša pri kruženju stabilnije stoji','Da se arome skupljaju u nožici','A','Držano za nožicu, vino ostaje podalje od topline ruke – kod ohlađenoga bijelog to kroz dulji obrok znači nekoliko stupnjeva. Nusučinak: kupa ostaje bez otisaka prstiju i ne rosi se, pa se boja i bistrina bolje vide.\n\nUpravo zato čaša za konjak nema dugu nožicu: tamo je toplina ruke željena, ona istiskuje arome. A moderne čaše bez nožice svjestan su kompromis – lakše za pranje, ali ruka grije vino.',NULL,'Hrana i piće'),
(41,'hr','Zašto želudac kruli?','Želučana kiselina vrije kad je želudac prazan','Plin i tekućina protiskuju se kroz probavni trakt','Želučana stijenka vibrira od napetosti','B','Želudac i crijevo rade i bez hrane: približno svakih sat i pol do dva kroz probavni trakt prolazi snažan val čišćenja i potiskuje ostatke dalje. Naiđe li na mješavinu tekućine i zraka, nastaju grgljavi zvukovi koje medicina naziva borborigmom.\n\nDa je pri praznom želucu tako glasno, ima jednostavan razlog: nedostaje sadržaj koji bi zvuk prigušio. Pun želudac kruli jednako, samo se ne čuje.',NULL,'Tijelo'),
(42,'hr','Što se u tijelu događa pri štucanju?','Jednjak se prstenasto stegne','Dijafragma se trgne i glasnice se zaklope','Želudac nakratko pritisne pluća','C','Refleks natjera dijafragmu da se naglo stegne – nevoljno se uvlači zrak. Samo djelić sekunde kasnije grkljan zaklopi glasnice. Zrak koji ulazi udari u tu zapreku, i upravo to proizvodi karakterističan zvuk.\n\nZašto taj refleks postoji, nije jasno; jedna sumnja vodi ga do punoglavaca, koji pri disanju škrgama čine nešto slično. Kućni trikovi ipak imaju zajedničko načelo: zadržavanje zraka, pijenje vode ili gutanje hladnoga povisuju sadržaj CO₂ ili dražie uključeni živac – oboje može prekinuti refleks.',NULL,'Tijelo'),
(43,'hr','Zašto zaboli glava kad se sladoled jede prebrzo?','Mozak se nakratko mjerljivo ohladi','Žile na nepcu reagiraju, a bol se pogrešno smjesti','Šećer nakratko obori krvni pritisak','B','Hladnoća na nepcu čini da se krvne žile najprije stegnu a zatim brzo rašire. Tu reakciju registrira trovlasni živac – isti onaj koji opskrbljuje i velika područja lica i čela. Mozak dojavu ne može točno smjestiti pa bol premješta naprijed u čelo. Stručnjaci govore o prenesenoj boli.\n\nSam se mozak pri tome ne hladi, a nema ni receptore za bol. Sve je prošlo nakon najviše pola minute; onaj koji jezik pritisne na nepce grije to mjesto i skraćuje ga.',NULL,'Tijelo'),
(44,'hr','Zašto se u velikoj školjki čuje šum kao na moru?','Čuje se vlastita krv u žilama uha','Školjka pojačava tihe zvukove okoline','Zatvoreni zrak titra na stalnoj visini tona','C','Šupljina školjke je rezonantno tijelo. Iz sveprisutnoga tihog sloja zvukova okoline izdvaja određene frekvencije i pojačava ih – ishod je širokopojasni šum koji podsjeća na more. Šalica ili šuplja ruka na uhu čine upravo isto.\n\nObjašnjenje s krvlju lako se pobija: u vrlo tihoj prostoriji šum postaje osjetno slabiji, a pri uspinjanju stubama s ubrzanim pulsom ne postaje glasniji. Da je to vlastita krv, moralo bi biti obrnuto.',NULL,'Tijelo'),
(45,'hr','Zašto se dobiva morska bolest?','Organ za ravnotežu dojavljuje nešto drugo nego oči','Ljuljanje mehanički izbaci želudac iz takta','Zračni pritisak na palubi mijenja unutarnji pritisak uha','C','Pod palubom oko vidi kabinu u mirovanju, a organ za ravnotežu u unutarnjem uhu osjeća ljuljanje. Mozak protivrječne dojave ne može spojiti. Uobičajeno objašnjenje: tumači sukob kao otrovanje – a razuman odgovor na otrovanje je izbacivanje.\n\nIz toga neposredno slijede i djelotvorna protusredstva: izaći na palubu i gledati u obzor, da oči i unutarnje uho dojavljuju isto. Iz istoga razloga vozaču rijetko pozli, a suvozaču s knjigom brzo.',NULL,'Tijelo'),
(46,'hr','Zašto sova može tako daleko okrenuti glavu?','Lubanja joj sjedi na kuglastom zglobu','Jer joj se oči ne mogu micati','Da u letu može gledati natrag','A','Sovine su oči za najveći mogući prihvat svjetla ogromne i nisu kugle, nego cijevi – posve ispunjavaju očnu duplju i praktički su nepomične. Sova dakle ne može pogledati očima, mora okrenuti cijelu glavu. Za to ima 14 vratnih kralježaka, dvostruko više od čovjeka, i postiže oko 270 stupnjeva.\n\nOpskrba krvlju prilagođena je toj krajnosti: arterije prolaze širokim kanalima i imaju rezervne jastučiće, pa se pri snažnom zavrtanju ne prikliješte. Čovjek bi istim pokretom prekinuo dotok krvi u mozak.','assets/quiz-illustrations/eule.svg','Životinje'),
(47,'hr','Zašto koze imaju četvrtaste zjenice?','Za vrlo široko vidno polje bez okretanja glave','Da bolje razlikuju boje','Da pri jarkom suncu propuste manje svjetla','C','Vodoravna pukotina djeluje kao panoramski format: propušta svjetlo iz vrlo širokoga vodoravnog kuta i pri tlu daje oštru sliku, a gore i dolje malo se gubi. Zajedno s očima postavljenima na strane koza postiže vidno polje od gotovo 320 stupnjeva – pasući vidi gotovo posvuda oko sebe, bez podizanja glave.\n\nUzorak odgovara načinu života: pasuće životinje plijena kao koze, ovce i konji imaju vodoravne zjenice. Mačke, kao lovci iz zasjede, imaju uspravne pukotine, koje bolje omogućuju procjenu udaljenosti. A pri pasenju pukotina ostaje vodoravna – oko se zavrće nasuprot spuštenoj glavi.','assets/quiz-illustrations/ziegenpupille.svg','Životinje'),
(48,'hr','Kako krijesnica proizvodi svoje svjetlo?','Trenjem finih hitinskih pločica','Kemijskom reakcijom s kisikom','Bakterijama koje žive u zatku','C','U zatku enzim spaja tvar luciferin s kisikom. Energija reakcije gotovo se posve otpušta kao svjetlo, a kao toplina gotovo nikako – odatle ime hladno svjetlo. Iskoristivost je oko 40 posto i nadmašuje svaku žarulju za mnogo duljina.\n\nTreperenje je oglas za partnera, a svaka vrsta ima svoj takt. Kod domaćih krijesnica obično lete mužjaci i traže, a bezkrilne ženke sjede u travi i svijetle. Neke američke vrste idu dalje: njihove ženke oponašaju takt drugih vrsta i pojedu privučene mužjake.',NULL,'Životinje'),
(49,'hr','Zašto muha može hodati po stropu?','Nogama stvara blagi podtisak','Sitne dlačice drže preko tekućine','Kandžice se hvataju za neravnine u zidu','A','Na vršcima nogu sjede dva ljepljiva jastučića s tisućama najfinijih dlačica. Svaka otpušta sitnu količinu uljaste tekućine. Tanki film tekućine kapilarnim silama privlači dlačicu na površinu – svaka pojedina gotovo ništa, ali sve zajedno znatno više od težine muhe.\n\nTo objašnjava dva opažanja: na glatkom staklu drži bolje nego na prašnim površinama, jer prašina prekida dodir. A muha se mora aktivno odvaljati da se odvoji – prilijepiti se i ponovno se otpustiti dvije su odvojene vještine.','assets/quiz-illustrations/fliege.svg','Životinje'),
(50,'hr','Koje su boje mrkve izvorno bile?','Narančaste, kao i danas','Ljubičaste i bijele','Zelene kao njihova cima','B','Kulturna mrkva dolazi iz područja Afganistana i bila je ljubičasta, žućkasta ili bijela. Narančaste sorte nastale su tek u ranom novom vijeku odabirom, uglavnom u Nizozemskoj. Sadržavale su mnogo beta-karotena, imale blaži okus i probile se u Europi – dok narančasta nije počela vrijediti kao naravna boja mrkve.\n\nOmiljena priča da su nizozemski vrtlari mrkvu uzgojili narančastom u čast kuće Oranje lijepa je, ali povijesno nije potvrđena. Ljubičaste su sorte, uzgred, ponovno u prodaji – kao novost.',NULL,'Priroda'),
(51,'hr','Zašto prerezani avokado potamni?','Enzim reagira s kisikom iz zraka','Masne kiseline u mesu užegnu','Klorofil se raspada pod svjetlom','C','Rezanjem se uništavaju stanice i enzim zvan polifenol oksidaza dođe u dodir s kisikom. On biljne sastojke pretvara u smeđe pigmente – ista reakcija boji prerezane jabuke, banane i krumpir. Plod time nije pokvaren.\n\nEnzimu treba kisik i ne voli kiselinu. Zato djeluju sok limuna i nepropusno pokrivanje, i zato pomaže meso odmah pomiješati s limetom u guacamole. Koštica u umaku pak drži čistom samo onu površinu koju sama prekriva.',NULL,'Hrana i piće'),
(52,'hr','Zašto kruh u hladnjaku posebno brzo postane star?','Tamo se suši brže nego na sobnoj temperaturi','Škrob kristalizira najbrže upravo na temperaturi hladnjaka','Hladnoća ubija kvasce koji ga drže mekim','B','Starenje kruha nije sušenje, nego preuređenje: škrob otvoren pri pečenju postupno ponovno stvara čvrsta, kristalna područja i istiskuje vodu. Stručni je naziv retrogradacija. A upravo taj postupak najbrže teče u području od nekoliko stupnjeva iznad ništice – temperatura hladnjaka najnepovoljnija je točka.\n\nPravilo je dakle: kruh držati na sobnoj temperaturi ili ga odmah zamrznuti, jer duboko zamrznut postupak praktički stane. A kako je obratan, star kruh u pećnici ponovno omekša – kratko dopečen kristale rastopi.',NULL,'Hrana i piće'),
(53,'hr','Koji je vrh najdalje od središta Zemlje?','Mount Everest u Himalaji','Chimborazo u Ekvadoru','Denali na Aljaski','A','Zemlja nije kugla, nego je zbog vrtnje na ekvatoru izbočena – razina mora tamo leži približno 21 kilometar dalje prema van nego na polovima. Chimborazo stoji gotovo na ekvatoru. Iako s dobrih 6260 metara nad morem ostaje daleko ispod Everesta, njegov vrh leži oko dva kilometra dalje od središta Zemlje.\n\nEverest je time i dalje najviša gora, samo po drugom mjerilu. Uzme li se stopa kao polazište, pobjeđuje treći: Mauna Kea na Havajima uzdiže se s morskoga dna više od 10.000 metara – gotovo polovica toga leži pod vodom.','assets/quiz-illustrations/chimborazo.svg','Svemir'),
(54,'hr','Zašto se grmljavina čuje tek nakon munje?','Grmljavina nastaje tek nedugo nakon izboja','Zvuk je oko milijun puta polaganiji od svjetla','Oblaci zvuk najprije zadržavaju','B','Munja i grmljavina nastaju istodobno: kanal munje u nekoliko mikrosekundi zagrije zrak na mnogo tisuća stupnjeva, on se eksplozivno rasteže, i taj je tlačni val grmljavina. Svjetlu za tu razdaljinu ne treba praktički nikakvo vrijeme, zvuku oko tri sekunde po kilometru.\n\nOdatle poznato pravilo: brojiti sekunde, dijeliti s tri, i imate udaljenost u kilometrima. Duga tutnjava dolazi od toga što je kanal munje kilometrima dug – njegovi su odsječci različito daleko, pa zvuk dolazi postupno.','assets/quiz-illustrations/blitz-donner.svg','Fizika'),
(55,'hr','Zašto su oblaci bijeli, a oblaci s kišom sivi?','Oblaci s kišom sadrže prašinu koja ih boji tamno','Debeli oblaci gotovo ne propuštaju svjetlo do tla','Kapljice vode potamne kako rastu','A','Kapljice u oblaku rasipaju sve boje jednako, zato se oblak čini bijelim. Kako raste u visinu, svjetlo mora prolaziti kroz sve više kapljica, pri svakom se rasipanju malo otkloni i dolje gotovo ne dođe. Odozdo gledan oblak zato djeluje sivo do gotovo crno – ne zbog svoje boje, nego zbog svoje debljine.\n\nOdozgo, primjerice iz zrakoplova, isti je grmljavinski oblak blistavo bijel. A kako velike kapi kiše nude manje površine po količini vode nego mnogo malih kapljica, oblak neposredno prije kiše rasipa i slabije.',NULL,'Priroda'),
(56,'hr','Zašto je crvena međunarodno boja za »stani«?','Jer podsjeća na krv, a time na opasnost','Jer ostaje vidljiva najdalje i rijetko se javlja u prirodi','Jer su rane signalne svjetiljke imale samo crveno staklo','C','Crveno svjetlo izmaglica i kiša rasipaju slabije od plavoga, pa se dobro vidi na velike udaljenosti – isto načelo koje zalaze Sunca čini crvenima. Dodatno, crvena je u krajoliku rijetka pa se ističe. Željeznica ju je u 19. stoljeću uvela kao signal za zaustavljanje, a od nje ju je preuzeo cestovni promet.\n\nJedna je boja pri tome ispala: izvorno je bijela značila »slobodan prolaz«. Nakon slučaja u kojem je crveno staklo ispalo a strojovođa golu bijelu svjetiljku pročitao kao dopuštenje, preuzela je zelena.',NULL,'Svakodnevica'),
(57,'hr','Zašto su prometni zrakoplovi obično bijeli?','Bijela ostaje najhladnija i pokazuje oštećenja','Bijeli su lakovi posebno izdržljivi','Bijelu je najlakše zahvatiti radarom','B','Bijela odbija sunčevo svjetlo i trup na zemlji drži osjetno hladnijim, što olakšava posao klimatizaciji i materijalu. Na svijetloj se podlozi pri pregledu odmah vide i pukotine, uljni tragovi i propuštanje goriva. Bijela uz to gotovo ne blijedi, a jarke boje pod zračenjem na velikim visinama brzo izgube boju i moraju se češće prelakirati.\n\nDolazi i vrlo konkretan argument: lak po cijeloj površini velikoga zrakoplova teži nekoliko stotina kilograma i kroz godine troši gorivo. Neki prijevoznici zato dijelove svjesno ostavljaju neobojenima ili lakiraju što tanje.',NULL,'Tehnika'),
(58,'hr','Zašto kolica u trgovini imaju zaključavanje za novčić?','Da se može brojiti koliko je kolica izdano','Da se kolica vraćaju','Da krađa kolica bude nemoguća','B','Novčić je zalog koji dobiva natrag samo onaj koji kolica ponovno zakvači. Poslovno se to isplati ne zbog novca, nego zbog uštede radnog vremena: bez zaloga osoblje mora stalno skupljati kolica s parkirališta, a pri tome nastaje najviše udubljenja na automobilima kupaca.\n\nIznos je svjesno malen. Mora biti samo dovoljno velik da se vraćanje kolica isplati – ne toliko velik da odbije kupce koji nemaju odgovarajući novčić uz sebe.',NULL,'Svakodnevica'),
(59,'hr','Odakle dolazi njemački izraz »Schwein gehabt« – doslovno »imao svinju« – u značenju imati sreću?','Od svinje kao utješne nagrade na natjecanjima','Od svinjice za novac kao znaka bogatstva','Od svinje kao amuleta pomoraca','B','Na srednjovjekovnim streljačkim i sportskim natjecanjima onaj koji je bio posljednji dobivao je svinju kao utješnu nagradu. Onaj koji je kao gubitnik kući ipak odnio vrijednu životinju, imao je sreće – i iz toga je nastao izraz. Svinja je bila imetak: davala je meso, mast i potomstvo.\n\nIz istoga korijena dolazi i svinja za sreću uz Novu godinu. Svinjica za novac vjerojatno ima posve drugo podrijetlo: vrstu gline zvanu »pygg« iz koje su se oblikovale posude za štednju – a engleska zvučna sličnost s »pig« učinila je ostatak.',NULL,'Jezik'),
(60,'hr','Zašto dan u našem računanju vremena počinje u ponoć?','Jer su Rimljani službeni dan mijenjali u ponoć','Jer izlazak Sunca putuje s godišnjim dobom','Jer je Crkva dala da dan počinje noćnom misom','B','Kao početak dana zamislivo je više točaka, i povijesno su sve bile u upotrebi: Egipćanima i kasnije Rimljanima građanski je dan počinjao u ponoć, a židovski i islamski kalendari daju mu početak sa zalaskom Sunca. Ponoć se u praksi probila iz jednostavnog razloga: izlazak i zalazak Sunca putuju kroz godinu i sa zemljopisnom širinom, a ponoć se, kao protutočka najvišem položaju Sunca, može astronomski odrediti i utvrditi.\n\nAstronomi se toga dugo nisu držali: do 1925. njihov je dan počinjao u podne, da noć promatranja ne bi pala preko promjene datuma. Onaj koji čita stare zvjezdane kataloge mora tu razliku uračunati.',NULL,'Povijest'),
(61,'hr','Kako mačka proizvodi predenje?','Titranjem mišića grkljana','Zrakom koji struji uz zube','Lepršanjem dijafragme','B','Signal iz mozga čini da se mišići na grkljanu stežu približno 25 do 30 puta u sekundi. Glasnice se u tom taktu otvaraju i zatvaraju, a kako to radi i pri udisaju i pri izdisaju, mačka može predsti minutama bez prekida – drukčije od mijaukanja.\n\nPredenje ne znači automatski zadovoljstvo. Mačke predu i u bolovima, kod veterinara i pri umiranju. Jedna sumnja: frekvencija leži u području koje u pokusima podstiče zarastanje kostiju – predenje bi tada bilo i samoumirivanje, a možda i više.',NULL,'Životinje'),
(62,'hr','Što je u grbi deve?','Zaliha vode','Mast','Splet krvnih žila','C','Grba je zaliha masti do 35 kilograma. Mast je najbolja zaliha energije koju tijelo može izgraditi, a pri izgaranju nastaje čak i malo vode – prava je dobit ipak energija. Nakon duge gladi grba se smanji i mlitavo prevali na stranu.\n\nDevina se sposobnost sa vodom nalazi na drugom mjestu: tijekom dana pušta da joj tjelesna temperatura poraste za nekoliko stupnjeva umjesto da se znoji, a crvena su joj krvna tjelešca ovalna i rastezljiva, pa preživljavaju naglo pijenje preko 100 litara bez pucanja.','assets/quiz-illustrations/kamel.svg','Životinje'),
(63,'hr','Čemu prije svega služe velike uši afričkoga slona?','Posebno finom sluhu','Otpuštanju tjelesne topline','Odbijanju insekata','B','Uši su protkane gustom mrežom površinskih krvnih žila i nude nekoliko četvornih metara površine. Mahanjem zrak prolazi uz njih i hladi krv prije nego što se vrati u tijelo – pri povoljnim uvjetima za nekoliko stupnjeva. Za životinju te mase riješiti se topline veći je problem od zadržavanja topline.\n\nPo tome se vrste razlikuju: afrički slon živi u toplijem, otvorenom krajoliku i ima osjetno veće uši od azijskoga. Sluh mu je ionako dobar, no prije svega za vrlo niske tonove, koje čuje kilometrima.','assets/quiz-illustrations/elefantenohr.svg','Životinje'),
(64,'hr','Koliko vratnih kralježaka ima žirafa?','Sedam, upravo koliko i čovjek','Četrnaest','Preko dvadeset, slično labudu','A','Gotovo svi sisavci imaju sedam vratnih kralježaka – miš, čovjek, kit i doista i žirafa. Kod nje je svaki pojedini kralježak dug do 25 centimetara. Broj je u razvoju tako strogo utvrđen da odstupanja kod ljudi obično idu s razvojnim nepravilnostima.\n\nIznimke postoje: lijenčine imaju šest do devet, ovisno o vrsti, morske krave šest. Ptice nisu vezane, labud ima preko dvadeset – zato mu je vrat toliko gibak, a žirafa svoj pokreće više kao dizalicu.',NULL,'Životinje'),
(65,'hr','Zašto noćni leptiri kruže oko svjetiljke?','Svjetiljku smatraju Mjesecom i pogrešno računaju','Refleksno okreću hrbat prema najsvjetlijem svjetlu','Privlači ih toplina svjetiljke','C','Objašnjenje s Mjesecom dugo je vrijedilo. No snimke insekata u letu velikom brzinom pokazale su nešto drugo: oni refleksno drže hrbat prema najsvjetlijem izvoru svjetla. Na nebu je to ispravan način da ostanu okrenuti prema gore. Uz svjetiljku taj refleks prevrne putanju leta – životinja završi u uskom zavoju oko svjetiljke umjesto da je smjera.\n\nTo objašnjava opažanja koja teoriji s Mjesecom nikada nisu odgovarala: leptiri ne lete pravo u svjetiljku, nego kruže, prevrću se i ponekad ostaju visjeti pod njom. Za noćne insekte umjetno je svjetlo zato manje privlačenje a više zamka za orijentaciju.',NULL,'Životinje'),
(66,'hr','Zašto mačje oči svijetle u svjetlu farova?','Mrežnica sama izlučuje svjetlo','Za mrežnicom sjedi zrcalni sloj','Rožnica odbija svjetlo natrag kao leća','A','Za mrežnicom leži tapetum lucidum, sloj finih kristala koji svjetlo odbija natrag prema naprijed. Ono što su vidne stanice propustile pri prvom prolazu, dobiju pri drugom – što znatno poboljšava vid u sumraku. Ostatak ponovno napušta oko i vidi se kao svjetlucanje.\n\nCijena je oštrina: odbijeno se svjetlo malo rasipa i slika postaje zrnatija. Ljudi taj sloj ne imaju, zato naše oči na snimkama s bljeskalicom izgledaju crveno – tamo se jednostavno vidi mrežnica prožeta krvlju.','assets/quiz-illustrations/katzenauge.svg','Životinje'),
(67,'hr','Kakav bi oblik imao plamen svijeće u bestežinskom stanju?','Bio bi kuglast','Bio bi plosnat i širok','Izgledao bi upravo kao na Zemlji','C','Šiljasti oblik dolazi isključivo od sile teže: vrući je plin lakši, diže se i odozdo povlači hladan zrak. Izostane li taj uzgon, kisik može ulaziti samo difuzijom sa svih strana – plamen postaje mala kugla. Na svemirskoj je postaji to opaženo više puta.\n\nIzgleda pri tome i drukčije: plavičast umjesto žut i osjetno hladniji. Bez uzlazne struje dobiva manje kisika i gotovo ne nastaje čađa – a plamen svijeće na Zemlji žut je samo zato što u njemu svijetle raspaljene čestice čađe.','assets/quiz-illustrations/kerze.svg','Fizika'),
(68,'hr','Kako sapun otapa mast koju voda sama ne može odstraniti?','Mast razgrađuje kemijski','Molekule imaju kraj koji voli vodu i kraj koji voli mast','Snižava temperaturu na kojoj se mast topi','A','Molekula sapuna je dvostruka: dugi rep koji voli mast i glava koja voli vodu. U vodi se mnogo njih smjesti oko kapljice masti tako da svi repovi stoje u masti a sve glave gledaju prema van. Te se kuglice nazivaju micelama – izvana djeluju vodi prijateljski i lako se ispiru.\n\nIsta građa sapun čini djelotvornim protiv mnogih virusa: oni imaju masnu ovojnicu, a repovi sapuna doslovno u nju ulaze i razderu je. Temeljito pranje ruku dakle nije puko ispiranje.','assets/quiz-illustrations/seife.svg','Svakodnevica'),
(69,'hr','Zašto stari papir požuti?','Ljepilo između vlakana se raspada','Sastojci drva razgrađuju se zrakom i svjetlom','Papir s vremenom prima prašinu u vlakna','C','Jeftin papir sadrži lignin, tvar koja drvo čini krutim. Lignin reagira s kisikom i svjetlom, a razgradni su proizvodi žućkastosmeđi. Dodatno dolazi kiselina iz proizvodnje, koja celulozna vlakna polako razlaže – papir ne samo da požuti, nego postane i krhak.\n\nNovinski papir na prozoru požuti u nekoliko dana, dobar knjižni papir drži desetljećima. Arhivi zato koriste papir bez kiseline i s malo lignina. A knjige iz 16. stoljeća često su bolje sačuvane od onih iz 1900.: tada se radilo od krpa, a ne od drvne mase.',NULL,'Svakodnevica'),
(70,'hr','Zašto obično prozorsko staklo na rezanom rubu ima zelenkast ton?','Od premaza protiv toplinskog zračenja','Od primjesa željeza u pijesku','Od zelene boje koja pukotine čini vidljivima','C','Kvarcni pijesak za ravno staklo uvijek sadrži tragove željeza. Željezov oksid upija prije svega u crvenom području, a ostaje blagi zelenkasti ton. Kroz tanko staklo to se gotovo ne primijeti, ali uz rub gleda se kroz mnogo centimetara stakla – i tamo se učinak vidljivo zbroji.\n\nGdje je vjernost boja važna, koristi se pijesak s malo željeza: takva bijela stakla više koštaju i nalaze se u vitrinama, okvirima za slike i solarnim modulima. Obrnuto, drugim se metalnim dodacima proizvode jarke boje – kobalt za plavu, selen za crvenu.',NULL,'Fizika'),
(71,'hr','Zašto vlastiti glas u snimci zvuči tako tuđe?','Mikrofoni niske tonove prenose slabije','Pri govoru sebe čujemo i preko kostiju lubanje','Sebe uvijek čujemo sa zakašnjenjem','B','Pri govoru zvuk dolazi do unutarnjeg uha dvama putovima: kroz zrak i neposredno kroz kosti čeljusti i lubanje. Koštani put niske frekvencije prenosi posebno dobro. Sebe zato čujemo punije i dublje nego što zaista zvučimo. Snimka poznaje samo zračni put – i ona je iskrena verzija.\n\nZato se vlastiti glas i pri zatvorenim ušima još čuje kao tutnjava. Pjevači i govornici zato uvježbavaju sa snimkama: samo tako čuju ono što čuje publika.','assets/quiz-illustrations/stimme.svg','Tijelo'),
(72,'hr','Zašto se ne možemo sami škakljati?','Mali mozak vlastiti dodir najavljuje unaprijed','Vlastita ruka dodiruje previše jednolično','Podražaj do mozga dolazi presporo','C','Pri svakom vlastitom pokretu mali mozak šalje predviđanje u osjetna područja mozga: pazi, ovaj dodir dolazi od nas. Ono što odgovara predviđanju, prigušuje se. Upravo se zato ne prepadamo vlastitoga koraka i ne smeta nas osjet vlastite odjeće.\n\nIstraživači su učinak nadmudrili robotskom rukom: ugradi li se malo zakašnjenje između pokreta ruke i dodira, odjednom ipak škaklja. A ljudi s određenim psihičkim bolestima, kod kojih je to predviđanje poremećeno, mogu se sasvim dobro sami škakljati.',NULL,'Tijelo'),
(73,'hr','Zašto se krvne žile pod kožom vide plavičasto, iako je krv crvena?','Krv s malo kisika u venama zaista je plava','Koža crveno svjetlo propušta drukčije od plavoga','Same su stijenke žila plavičasto obojene','C','Krv s malo kisika nije plava, nego tamnocrvena – to se vidi pri vađenju krvi. Plava nastaje tek kroz kožu: crveno svjetlo prodire duboko i u tkivu se gotovo posve proguta, a plavo se rasipa natrag već u gornjim slojevima. Nad tamnom žilom zato pobjeđuje plavi dio.\n\nUčinak dakle ovisi o dubini: vrlo površinske žile djeluju crvenkasto, dublje se gotovo ne vide, a u srednjoj dubini izgledaju plave. To je isti razlog zbog kojega boja za tatuiranje u dubljim slojevima kože dobiva plavičast odsjaj.',NULL,'Tijelo'),
(74,'hr','Zašto neki ljudi moraju kihnuti kad izađu na jarko svjetlo?','Svjetlo isušuje sluznicu nosa','Živac pogrešno prenosi podražaj','Pokret zjenice draži sinuse','B','Vidni živac i živci lica prolaze blizu jedan drugoga, a kod dijela ljudi jak svjetlosni podražaj preskoči na put koji pokreće refleks kihanja. Mozak ga tumači kao dražljaj u nosu. Refleks je nasljedan, ovisno o istraživanju zahvaća 18 do 35 posto ljudi i obično se završi nakon jednoga do tri kihanja.\n\nOpisao ga je već Aristotel, koji ga je pripisao toplini Sunca. Za pilote borbenih zrakoplova i skakače na skijama on je zaista tema – kihanje pri izlasku iz tunela dolazi u najnepovoljnijem trenutku.',NULL,'Tijelo'),
(75,'hr','Zašto kosa posijedi?','S godinama u sebe ugrađuje bijeli keratin','Stanice za boju u korijenu dlake predaju se','Zrak prodire u vlas','B','Boja dlake dolazi od melanocita u korijenu, koji dlaci koja raste dodaju pigment. Njihova se zaliha matičnih stanica kroz godine iscrpi; kad pigment više ne dolazi, dlaka izraste bezbojna. Djeluje bijelo jer se svjetlo u njoj rasipa. Sijedo je samo mješani ugođaj bijelih i još pigmentiranih dlaka.\n\nPojedinačna dlaka dakle ne posijedi – ona izraste sijeda. Kao ubrzivač vrijedi i vodikov peroksid, koji se nakuplja u korijenu i blijedi pigment. Da kosa od straha pobijeli preko noći pak je fizikalno nemoguće.',NULL,'Tijelo'),
(76,'hr','Zašto muškarci imaju bradavice?','Ostatak su iz evolucije sisavaca','Svi ih zametci polažu prije nego što hormoni počnu djelovati','Imaju zadaću u regulaciji temperature','B','U prvim se tjednima svi zametci razvijaju po istom nacrtu, a to uključuje i polaganje mliječnih žlijezda. Tek nakon toga hormoni daljnji razvoj usmjeravaju u jednu stranu. Već položena građa ne razgrađuje se – ona jednostavno ostaje nerazvijena.\n\nDa je to djelatno tkivo, pokazuju iznimke: pod određenim hormonskim uvjetima tkivo dojke može rasti i kod muškaraca, a muškarci mogu oboljeti od raka dojke. Približno jedan posto svih slučajeva zahvaća muškarce – često prepoznat prepozno, jer nitko to ne očekuje.',NULL,'Tijelo'),
(77,'hr','Zašto hrana u zrakoplovu ima bljutav okus?','Predugo se drži toplom','Suh zrak, nizak pritisak i buka prigušuju osjet okusa','Kuhinja na letu ne smije koristiti sol','B','Tri se stvari sastaju. Zrak u kabini krajnje je suh, pa sluznica nosa mirisne tvari slabije prima – a okus je većim dijelom miris. Smanjeni pritisak dodatno prigušuje. A stalna buka od približno 85 decibela mjerljivo snižava osjet slatkoga i slanoga. Izgubi se oko 30 posto osjetljivosti.\n\nJedan je smjer okusa uglavnom pošteđen i u buci se čak pojačava: umami. Upravo je zato sok od rajčice na letu tako popularan, iako ga na zemlji gotovo nitko ne naruči – i zato zrakoplovne kuhinje začinjavaju znatno jače nego što bi na zemlji imalo dobar okus.',NULL,'Hrana i piće'),
(78,'hr','Zašto prazna prostorija tako jako odjekuje?','Jer bi namještaj i tekstil zvuk inače upili','Jer zrak bez namještaja bolje titra','Jer se zvuk lomi na više kutova','B','Zvuk se od tvrdih, glatkih površina odbija gotovo posve i u prostoriji putuje tu i tamo dok se energija ne potroši. Mekane i porozne stvari – kauč, tepih, zavjesa, polica s knjigama, i ljudi – umjesto toga ga upijaju i pretvaraju u malo topline. Nedostaju li, gašenje traje osjetno dulje.\n\nUpravo je to vrijeme odjeka središnja veličina akustike prostora: u dnevnoj je sobi oko pola sekunde, u praznoj novogradnji često preko dvije, u velikoj crkvi šest ili više. A kako publika snažno upija, koncertna dvorana na probi zvuči drukčije nego na izvedbi.',NULL,'Svakodnevica'),
(79,'hr','Zašto se Mjesec može vidjeti i po danu?','Jer je bliži od svake zvijezde','Jer je dovoljno svijetao da se održi pred plavim nebom','Jer ga sunčevo svjetlo po danu dodatno obasjava','A','Mjesec nije noćni predmet – on je jednostavno na nebu kad ga njegova staza tamo odvede, a to je često po danu. Vidljiv je jer njegova površina odbija dovoljno sunčeva svjetla da bude svjetliji od rasutoga plavog neba za njim. Zvijezde to ne mogu, njihovo se svjetlo u njemu izgubi.\n\nNajbolje ide oko faza polumjeseca: tada Mjesec stoji približno 90 stupnjeva od Sunca, dakle visoko na nebu, a Sunce još sja. Pri punom Mjesecu on pak izlazi približno sa zalaskom Sunca – po danu je tada pod obzorom.',NULL,'Svemir'),
(80,'hr','Zašto gotovo svi vijci imaju desni navoj?','Jer je pri zatezanju povoljniji za dešnjake','Jer se lijevi navoji lakše sami otpuštaju','Jer su prvi strojevi za rezanje navoja mogli raditi samo tako','A','Pri zatezanju desnom rukom okretanje u smjeru kazaljke na satu snažnije je i lakše se nadzire od suprotnoga – podlaktica se pri tome zavrće prema unutra. Kako je većina ljudi dešnjaka, taj se smjer ustalio kao norma i kasnije je jednostavno propisan.\n\nLijevi navoji postoje tamo gdje bi norma bila opasna: na lijevoj pedali bicikla, da se u vožnji sama ne odvrne, na nekim maticama za listove pile i na plinskim bocama za goriva plinove, da se ne priključi pogrešan spoj. Iznimka je dakle uvijek svjesno osiguranje.',NULL,'Povijest'),
(81,'hr','Što »ok« izvorno znači?','Skraćenica je imena jednoga mjesta','Bila je šala s namjerno pogrešnim pisanjem','Dolazi od indijanske riječi za pristajanje','C','Godine 1839. u bostonskim je novinama kolala moda da se izrazi namjerno pogrešno pišu i zatim skraćuju. »Oll korrect« za »all correct« postalo je o.k. Većina je tih šaljivih skraćenica umrla u nekoliko mjeseci – ova nije, jer je nedugo zatim u predsjedničkoj kampanji dobila drugo značenje.\n\nMartin Van Buren dolazio je iz Kinderhooka i zvali su ga »Old Kinderhook«; njegovi su pristaše osnivali O.K. klubove. Oboje zajedno učinilo je ta dva slova besmrtnima – danas »ok« vrijedi kao najrasprostranjenija riječ na svijetu.',NULL,'Jezik'),
(82,'hr','Odakle dolazi riječ »panika«?','Od jednoga grčkog boga','Od latinske riječi za bijeg','Od srednjovjekovnoga liječnika koji ju je opisao','C','Pan je bio grčki bog pastira s kozjim nogama, zadužen za šume i pašnjake. Govorilo se da putnike i cijela krda napada iznenadnim strahom – bezrazložnim užasom koji je bez vidljiva povoda prolazio kroz mnoštvo. Taj panični strah postao je riječ.\n\nNa njega se svodi i više: Panova svirala, koju je po predanju izmislio, i zaobilaznim putem kršćanski prikaz đavla s rogovima i kozjim nogama. Riječ »pandemija« s njim pak nema ništa – to je grčki »sav narod«.',NULL,'Jezik'),
(83,'hr','Zašto kiša ima tako karakterističan miris?','Munje pri tlu stvaraju ozon','Kapi u zrak izbacuju ulja iz tla i spore bakterija','Voda koja isparava sa sobom nosi miris prašine','A','Kad kap padne na suho tlo, nakratko zatvori zrak. On izlazi kao roj sitnih mjehurića i sa sobom povlači tvari s površine: biljna ulja koja se u sušnim razdobljima nakupljaju, i mirisnu tvar geosmin iz bakterija u tlu. Postupak je učinjen vidljivim kamerama velike brzine.\n\nGeosmin je glavni prenositelj toga zemljanog mirisa, a ljudski je nos na njega krajnje osjetljiv – dostatno je nekoliko dijelova na bilijun. Ista tvar cikli daje zemljani okus i razlog je zašto se jedna jedina kap kišnice u vodi za piće odmah osjeti. Ime za taj miris: petrihor.',NULL,'Priroda'),
(84,'hr','Zašto je snijeg bijel, a led proziran?','Snijeg sadrži zatvoren zrak koji rasipa svjetlo','Snježni kristali imaju vlastitu bijelu boju','Snijeg odbija svjetlo samo s površine','A','Snijeg nije ništa drugo nego led – samo se sastoji od milijuna sitnih kristala sa zrakom između njih. Na svakoj granici između leda i zraka svjetlo se malo otkloni. Nakon nebrojenih otklona napušta snijeg u svim smjerovima i u svim bojama jednako: to opažamo kao bijelo.\n\nIsto načelo šećernu vunu, pjenu i oblake čini bijelima, iako su njihovi sastojci prozirni. A gdje je snijeg dubok i gusto stisnut, vidi se sljedeći učinak: u ledenjacima se crveno svjetlo nakon dugoga puta ipak upije – zato led ledenjaka svijetli plavo.',NULL,'Priroda'),
(85,'hr','Zašto voda ostaje u vjedru koje vitlamo u krug?','Sila je pritiskuje prema van na dno','Dno vjedra neprestano ju prisiljava na kružnu stazu','Struja zraka drži je u vjedru','B','Po tromosti voda želi nastaviti letjeti pravo. Dno je vjedra pri tome neprestano na putu i preusmjerava je prema unutra – ta sila prema unutra drži je na kružnoj stazi. U najvišoj točki dio toga preuzima sila teža, ostatak dalje daje dno. Vitla li se presporo, sila teža sama nije dovoljna kao sila zavoja, i voda ispada.\n\nČesto navođena centrifugalna sila »prema van« postoji samo kao pomoć u računu za promatrača koji se vrti zajedno s vjedrom. Gledano izvana, nikakva sila prema van ne djeluje – djeluje samo previše malo prema unutra.',NULL,'Fizika'),
(86,'hr','Zašto krila zrakoplova često imaju krajeve povijene prema gore?','Da se pri manevrima na zemlji uštedi prostor','Da se prikoči vrtlog na vrhu krila','Da krilo dobije više čvrstoće','A','Na vrhu krila pretisak odozdo dolazi do podtiska iznad i uvija se u snažan vrtlog. Taj vrtlog troši energiju, a ne donosi uzgon. Uzdignut kraj – winglet ili povijen vrh – to obilaženje otežava i vrtlog slabi. Ovisno o izvedbi to donosi nekoliko posto uštede goriva.\n\nVrtlozi su više od pojedinosti: oni su razlog za propisane razmake između zrakoplova koji polijeću, jer vrtložni trag može prevrnuti manji zrakoplov za velikim. Ptice u selidbi isti učinak koriste letom u formaciji – onaj koji leti iza je u uzlaznoj struji prethodnika.',NULL,'Tehnika'),
(87,'hr','Zašto je u svemiru hladno, iako Sunce tamo sja nefiltrirano?','Jer se bez materije toplina gotovo ne može prenijeti','Jer se sunčevo zračenje s udaljenošću gotovo izgubi','Jer je temperatura u vakuumu načelno ništica','A','Temperatura je kretanje čestica – gdje ih gotovo nema, gotovo nema ni što zagrijati. Na Zemlji zrak i voda toplinu predaju dodirom i strujanjem; u vakuumu oboje otpada, ostaje samo zračenje. Predmet na Suncu zato postane vrlo vruć, u sjeni vrlo hladan, a između te dvije strane leže stotine stupnjeva.\n\nStoga je hlađenje u svemiru pravi problem, a ne grijanje: svemirska postaja nosi velike radijatore da se oslobodi otpadne topline. A svemirska odijela nisu debela protiv hladnoće, nego izoliraju u oba smjera i imaju vlastiti sustav hlađenja protiv tjelesne topline.',NULL,'Svemir'),
(88,'hr','Zašto tuba paste za zube gore ima obojeni četverokut?','Šifrira sastojke','To je oznaka za stroj koji reže','Pokazuje podrijetlo sirovina','A','Obojeni su kvadratići oznake za stroj koji pakira. Svjetlosni senzor prepoznaje blok boje na svijetloj podlozi i time točno zna na kojem mjestu beskrajnu vrpcu tube treba odrezati i zavariti. Sama je boja bilo koja – mora samo dati dovoljan kontrast.\n\nU skladu s tim, raširena je priča da zelena stoji za posve prirodne a crna za posve kemijske sastojke izmišljena. Iste se oznake nalaze na vrećicama čipsa, pakiranjima kave i folijama za kobasice, gdje nitko ne sumnja u tajnu poruku.',NULL,'Svakodnevica'),
(89,'hr','Zašto se baterija mobitela zimi na otvorenom tako brzo isprazni?','Zaslon na hladnoći troši više struje','Kemijski procesi u bateriji teku polaganije','Baterija na hladnoći zaista izgubi naboj','A','U litij-ionskoj bateriji ioni moraju putovati kroz elektrolit. Na hladnoći on postaje gušći a putovanje polaganije, pa unutarnji otpor raste. Baterija više ne može davati traženu snagu, napon se pod opterećenjem sruši, a elektronika to tumači kao »prazno« i isključi se. Energija pri tome nije izgubljena – na toplom uređaj često ponovno pokaže naboj.\n\nVažna je posljedica za punjenje: bateriju pod ništicom ne bi trebalo puniti, jer se tada može izdvojiti metalni litij, što je trajno oštećuje. Dobri uređaji zato punjenje na hladnoći odbijaju sami.',NULL,'Tehnika'),
(90,'hr','Zašto su tračnice u mnogim zemljama široke točno 1435 milimetara?','Mjera je proizašla iz izračuna o stabilnosti u zavojima','Preuzela je mjeru engleskih željeznica za ugalj','Odgovara širini osi rimskih bojnih kola','C','George Stephenson gradio je svoje lokomotive za željeznice za ugalj na sjeveroistoku Engleske, čija je širina proizašla iz mjesne izrade zaprežnih kola. Kad su se njegovi strojevi probili, njihova je mjera došla s njima i kasnije je propisana kao normalni kolosijek – dobrih 1435 milimetara, dakle četiri stope i osam i pol inča.\n\nOmiljena priča da mjera potječe od širine osi rimskih bojnih kola legenda je bez dokaza. Da su različite zemlje svjesno izabrale druge širine, često je imalo vojne razloge: drukčiji kolosijek koči napadača, jer svoje vlakove ne može jednostavno pustiti dalje.',NULL,'Povijest');
