-- Eigene Quizfragen fuer das Spiel "Schon gewusst?"
-- Erzeugt aus scratchpad/own-*.json. Idempotent: DROP + CREATE + INSERT.
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `trivia_questions`;
CREATE TABLE `trivia_questions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `questionNumber` int NOT NULL,
  `language` enum('de','en','hr') NOT NULL,
  `question` text NOT NULL,
  `answerA` text NOT NULL,
  `answerB` text NOT NULL,
  `answerC` text NOT NULL,
  `correctAnswer` enum('A','B','C') NOT NULL,
  `explanation` mediumtext NOT NULL,
  `image` varchar(255) DEFAULT NULL,
  `category` varchar(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_trivia_number_language` (`questionNumber`,`language`),
  KEY `idx_trivia_language` (`language`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

